use std::{
    cell::RefCell,
    io::{BufRead, BufReader, Read, Write},
    process::{Child, ChildStdin, Command, Stdio},
    sync::mpsc,
    time::Duration,
};

use serde_json::{json, Value};
use tower_lsp::lsp_types::Url;

struct Server {
    child: Child,
    stdin: Option<ChildStdin>,
    messages: mpsc::Receiver<Value>,
    pending: RefCell<Vec<Value>>,
}

#[test]
fn hook_string_mutation_guards_refresh_unsaved_providers_without_partial_macro_edits() {
    use latex_lsp::text::Text;
    for versioned in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
        let provider = uri.join("commands.sty").unwrap();
        let source = "% 😀\r\n\\documentclass{article}\\newcommand\\unicodeword{😀}\\usepackage{etoolbox}\\def\\identity#1{#1}\\newcommand\\word{Text}\\input{commands.sty}\\begin{document}\\ifblank{\\word}{\\word}{\\word}\\label{safe}\\ref{safe}\\end{document}";
        let mutation = r"\AtBeginDocument{\let\ifblank\identity}";
        std::fs::write(uri.to_file_path().unwrap(), source).unwrap();
        std::fs::write(provider.to_file_path().unwrap(), mutation).unwrap();
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"initializationOptions":{"distribution":{"enabled":false}},"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":versioned}}}}));
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":uri,"languageId":"latex","version":5,"text":source}}),
        );
        let expected = |edits: Vec<Value>, version| {
            if versioned {
                json!({"documentChanges":[{"textDocument":{"uri":uri,"version":version},"edits":edits}]})
            } else {
                json!({"changes":{uri.as_str():edits}})
            }
        };
        let blocked = |server: &mut Server, source: &str| {
            let text = Text::new(source.into());
            server.send(json!({"jsonrpc":"2.0","id":20,"method":"textDocument/rename","params":{"textDocument":{"uri":uri},"position":text.position(source.rfind("word").unwrap() + 1),"newName":"term"}}));
            let response = server.until(|message| message["id"] == 20);
            assert!(
                response["error"]["code"] == -32602 || response.get("result") == Some(&Value::Null),
                "{response}"
            );
        };
        let safe = |server: &mut Server, source: &str, version| {
            let text = Text::new(source.into());
            let edits = source
                .match_indices("safe")
                .map(|(at, _)| json!({"range":text.range(at, at + 4),"newText":"fresh"}))
                .collect::<Vec<_>>();
            assert_eq!(edits.len(), 2);
            assert_eq!(server.request(2, "textDocument/rename", json!({"textDocument":{"uri":uri},"position":text.position(source.rfind("safe").unwrap() + 1),"newName":"fresh"})), expected(edits, version));
        };
        blocked(&mut server, source);
        safe(&mut server, source, 5);
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":provider,"languageId":"latex","version":12,"text":""}}),
        );
        let text = Text::new(source.into());
        let edits = source
            .match_indices(r"\word")
            .enumerate()
            .filter(|(index, _)| *index != 1)
            .map(|(_, (at, _))| json!({"range":text.range(at, at + 5),"newText":"\\term"}))
            .collect::<Vec<_>>();
        assert_eq!(edits.len(), 3);
        assert_eq!(server.request(3, "textDocument/rename", json!({"textDocument":{"uri":uri},"position":text.position(source.rfind("word").unwrap() + 1),"newName":"term"})), expected(edits, 5));
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":provider,"version":13},"contentChanges":[{"text":mutation}]}));
        blocked(&mut server, source);
        safe(&mut server, source, 5);
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":provider}}),
        );
        blocked(&mut server, source);
        let changed = source.replace("{Text}", "{Value}");
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":uri,"version":7},"contentChanges":[{"text":changed}]}),
        );
        blocked(&mut server, &changed);
        safe(&mut server, &changed, 7);
        server.request(4, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn kernel_hooks_keep_exact_structural_edits_and_refresh_unsaved_parameter_meanings() {
    use latex_lsp::text::Text;
    for versioned in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
        let provider = uri.join("commands.sty").unwrap();
        let source = "% 😀\r\n\\documentclass{article}\\newcommand\\unicodeword{😀}\\input{commands.sty}\\AddToHook{begindocument}{Code \\ref{same}}\\begin{document}\\label{same}\\ref{same}\\end{document}";
        std::fs::write(uri.to_file_path().unwrap(), source).unwrap();
        std::fs::write(provider.to_file_path().unwrap(), "").unwrap();
        let text = Text::new(source.into());
        let code_at = text.position(source.find("Code").unwrap() + 1);
        let ref_at = text.position(source.find(r"\ref{same}").unwrap() + 6);
        let real = source.find(r"\label{same}").unwrap() + 7;
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"initializationOptions":{"distribution":{"enabled":false}},"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":versioned}},"textDocument":{"completion":{"completionItem":{"snippetSupport":true}}}}}));
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":uri,"languageId":"latex","version":5,"text":source}}),
        );
        let code_params = json!({"textDocument":{"uri":uri},"position":code_at});
        let ref_params = json!({"textDocument":{"uri":uri},"position":ref_at});
        let initial_help = server.request(2, "textDocument/signatureHelp", code_params.clone());
        assert_eq!(
            initial_help["signatures"][0]["label"],
            r"\AddToHook{hook}[label]{code}"
        );
        assert_eq!(initial_help["activeParameter"], 2);
        let location = json!({"uri":uri,"range":text.range(real, real + 4)});
        assert_eq!(
            server.request(3, "textDocument/definition", ref_params.clone()),
            json!([location])
        );
        let renamed = |server: &mut Server, source: &str, version| {
            let text = Text::new(source.into());
            let at = text.position(source.rfind("same").unwrap() + 1);
            let response = server.request(
                4,
                "textDocument/rename",
                json!({"textDocument":{"uri":uri},"position":at,"newName":"fresh"}),
            );
            let edits = source
                .match_indices("same")
                .map(|(start, _)| json!({"range":text.range(start, start + 4),"newText":"fresh"}))
                .collect::<Vec<_>>();
            assert_eq!(edits.len(), 3);
            let expected = if versioned {
                json!({"documentChanges":[{"textDocument":{"uri":uri,"version":version},"edits":edits}]})
            } else {
                json!({"changes":{uri.as_str():edits}})
            };
            assert_eq!(response, expected);
        };
        renamed(&mut server, source, 5);
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":provider,"languageId":"latex","version":12,"text":"\\renewcommand\\AddToHook[2]{}"}}));
        let hook_at = text.position(source.find("begindocument").unwrap() + 1);
        let help = server.request(
            5,
            "textDocument/signatureHelp",
            json!({"textDocument":{"uri":uri},"position":hook_at}),
        );
        assert_eq!(help["signatures"][0]["label"], r"\AddToHook{#1}{#2}");
        assert_eq!(
            server.request(6, "textDocument/definition", ref_params.clone()),
            json!([])
        );
        let outer = text.position(source.rfind("same").unwrap() + 1);
        for method in ["textDocument/prepareRename", "textDocument/rename"] {
            server.send(json!({"jsonrpc":"2.0","id":20,"method":method,"params":{"textDocument":{"uri":uri},"position":outer,"newName":"fresh"}}));
            let response = server.until(|message| message["id"] == 20);
            assert!(
                response["error"]["code"] == -32602 || response.get("result") == Some(&Value::Null),
                "{response}"
            );
        }
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":provider}}),
        );
        assert_eq!(
            server.request(7, "textDocument/definition", ref_params),
            json!([location])
        );
        assert_eq!(
            server.request(8, "textDocument/signatureHelp", code_params),
            initial_help
        );
        renamed(&mut server, source, 5);
        let changed = source.replace("Code", "Updated code");
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":uri,"version":7},"contentChanges":[{"text":changed}]}),
        );
        renamed(&mut server, &changed, 7);
        let completion_uri = Url::parse("untitled:kernel-hook-completion.tex").unwrap();
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":completion_uri,"languageId":"latex","version":1,"text":"\\AddToHo"}}));
        let items = server.request(
            9,
            "textDocument/completion",
            json!({"textDocument":{"uri":completion_uri},"position":{"line":0,"character":8}}),
        );
        let item = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["label"] == "AddToHook")
            .unwrap();
        assert_eq!(
            item["textEdit"],
            json!({"range":{"start":{"line":0,"character":1},"end":{"line":0,"character":8}},"newText":"AddToHook{${1:hook}}{${2:code}}"})
        );
        server.request(10, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn literal_label_readers_refresh_exact_ranges_and_safe_edits_over_stdio() {
    use latex_lsp::text::Text;
    for versioned in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
        let provider = uri.join("commands.sty").unwrap();
        let source = "% 😀\r\n\\documentclass{article}\\newcommand\\unicodeword{😀}\\input{commands.sty}\\newcommand\\literal[1]{\\detokenize{#1}}\\begin{document}\\literal{\\label{same}}\\label{same}\\ref{same}\\literal{\\label{ghost}}\\ref{ghost}\\label{safe}\\ref{safe}\\end{document}";
        std::fs::write(uri.to_file_path().unwrap(), source).unwrap();
        std::fs::write(provider.to_file_path().unwrap(), "").unwrap();
        let text = Text::new(source.into());
        let data = source.find("same").unwrap();
        let real = source.rfind(r"\label{same}").unwrap() + 7;
        let ghost = source.rfind("ghost").unwrap();
        let params = json!({"textDocument":{"uri":uri},"position":text.position(source.rfind("same").unwrap() + 1),"newName":"fresh"});
        let location = |start| json!({"uri":uri,"range":text.range(start, start + 4)});
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"initializationOptions":{"distribution":{"enabled":false}},"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":versioned}},"textDocument":{"diagnostic":{}}}}));
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":uri,"languageId":"latex","version":5,"text":source}}),
        );
        assert_eq!(
            server.request(2, "textDocument/definition", params.clone()),
            json!([location(real)])
        );
        let initial = server.request(
            3,
            "textDocument/diagnostic",
            json!({"textDocument":{"uri":uri}}),
        );
        assert_eq!(initial["items"].as_array().unwrap().len(), 1, "{initial}");
        assert_eq!(initial["items"][0]["code"], "undefined-reference");
        assert_eq!(
            initial["items"][0]["range"],
            json!(text.range(ghost, ghost + 5))
        );
        for method in ["textDocument/prepareRename", "textDocument/rename"] {
            server.send(json!({"jsonrpc":"2.0","id":20,"method":method,"params":params}));
            let response = server.until(|message| message["id"] == 20);
            assert!(
                response["error"]["code"] == -32602 || response.get("result") == Some(&Value::Null),
                "{response}"
            );
        }
        for (name, new_name) in [("safe", "fresh"), ("literal", "reader")] {
            let response = server.request(4, "textDocument/rename", json!({"textDocument":{"uri":uri},"position":text.position(source.rfind(name).unwrap() + 1),"newName":new_name}));
            let old = if name == "literal" {
                format!(r"\{name}")
            } else {
                name.into()
            };
            let new_text = if name == "literal" {
                format!(r"\{new_name}")
            } else {
                new_name.into()
            };
            let edits = source.match_indices(&old).map(|(start, _)| json!({"range":text.range(start, start + old.len()),"newText":new_text})).collect::<Vec<_>>();
            let expected = if versioned {
                json!({"documentChanges":[{"textDocument":{"uri":uri,"version":5},"edits":edits}]})
            } else {
                json!({"changes":{uri.as_str():edits}})
            };
            assert_eq!(response, expected);
        }
        for (version, replacement, active) in [
            (12, r"\def\detokenize#1{#1}", true),
            (13, "", false),
            (14, r"\renewcommand\literal[1]{#1}", true),
        ] {
            server.notify("textDocument/didOpen", json!({"textDocument":{"uri":provider,"languageId":"latex","version":version,"text":replacement}}));
            let expected = if active {
                json!([location(data), location(real)])
            } else {
                json!([location(real)])
            };
            assert_eq!(
                server.request(5, "textDocument/definition", params.clone()),
                expected
            );
            let report = server.request(
                6,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":uri}}),
            );
            assert_eq!(report["items"].as_array().unwrap().len(), 1, "{report}");
            assert_eq!(
                report["items"][0]["code"],
                if active {
                    "duplicate-label"
                } else {
                    "undefined-reference"
                }
            );
            if active {
                assert_eq!(
                    report["items"][0]["range"],
                    json!(text.range(real, real + 4))
                );
                assert_eq!(
                    report["items"][0]["relatedInformation"][0]["location"],
                    location(data)
                );
            }
        }
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":provider}}),
        );
        assert_eq!(
            server.request(7, "textDocument/definition", params),
            json!([location(real)])
        );
        let restored = server.request(
            8,
            "textDocument/diagnostic",
            json!({"textDocument":{"uri":uri}}),
        );
        assert_eq!(restored["items"], initial["items"]);
        server.request(9, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn repeated_parameter_grammars_follow_unsaved_providers_without_certifying_bodies() {
    use latex_lsp::text::Text;
    for versioned in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
        let shared = uri.join("shared.tex").unwrap();
        let provider = uri.join("commands.sty").unwrap();
        let other = uri.join("unsaved.tex").unwrap();
        let source = "% 😀\r\n\\documentclass{article}\\newcommand\\unicodeword{😀}\\newcommand\\one[1]{#1}\\input{commands.sty}\\begin{document}\\input{shared}\\one{Text}\\ref{same}\\end{document}";
        let declaration = "% 😀\r\n\\newcommand\\unicodeword{😀}\\label{same}";
        for (file, content) in [
            (&uri, source),
            (&shared, declaration),
            (&provider, r"\renewcommand\one[1]{#1}"),
        ] {
            std::fs::write(file.to_file_path().unwrap(), content).unwrap();
        }
        let text = Text::new(source.into());
        let shared_text = Text::new(declaration.into());
        let at = text.position(source.rfind("same").unwrap() + 1);
        let shared_start = declaration.find("same").unwrap();
        let location =
            json!({"uri":shared,"range":shared_text.range(shared_start, shared_start + 4)});
        let params = json!({"textDocument":{"uri":uri},"position":at,"newName":"fresh"});
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"initializationOptions":{"distribution":{"enabled":false}},"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":versioned}}}}));
        server.notify("initialized", json!({}));
        for (file, content, version) in [(&uri, source, 5), (&shared, declaration, 7)] {
            server.notify("textDocument/didOpen", json!({"textDocument":{"uri":file,"languageId":"latex","version":version,"text":content}}));
        }
        let allowed = |server: &mut Server| {
            assert_eq!(
                server.request(2, "textDocument/definition", params.clone()),
                json!([location])
            );
            assert!(!server
                .request(3, "textDocument/prepareRename", params.clone())
                .is_null());
            let response = server.request(4, "textDocument/rename", params.clone());
            let mut expected = vec![];
            let mut changes = serde_json::Map::new();
            for (file, text, version) in [(&uri, &text, 5), (&shared, &shared_text, 7)] {
                let start = text.source.find("same").unwrap();
                let edit = json!({"range":text.range(start, start + 4),"newText":"fresh"});
                expected
                    .push(json!({"textDocument":{"uri":file,"version":version},"edits":[edit]}));
                changes.insert(file.to_string(), json!([edit]));
            }
            if versioned {
                let mut actual = response["documentChanges"].as_array().unwrap().clone();
                actual.sort_by_key(|value| value["textDocument"]["uri"].to_string());
                expected.sort_by_key(|value| value["textDocument"]["uri"].to_string());
                assert_eq!(actual, expected);
            } else {
                assert_eq!(response, json!({"changes":changes}));
            }
        };
        let blocked = |server: &mut Server| {
            for method in ["textDocument/prepareRename", "textDocument/rename"] {
                server.send(json!({"jsonrpc":"2.0","id":20,"method":method,"params":params}));
                let response = server.until(|message| message["id"] == 20);
                assert!(
                    response["error"]["code"] == -32602
                        || response.get("result") == Some(&Value::Null),
                    "{response}"
                );
            }
        };
        allowed(&mut server);
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":provider,"languageId":"latex","version":12,"text":"\\renewcommand\\one[2]{#1}"}}));
        assert_eq!(
            server.request(5, "textDocument/definition", params.clone()),
            json!([])
        );
        blocked(&mut server);
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":provider,"version":13},"contentChanges":[{"text":"\\renewcommand\\one[1]{}"}]}));
        allowed(&mut server);
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":other,"languageId":"latex","version":9,"text":"\\documentclass{article}\\newcommand\\one[2]{}\\begin{document}\\input{shared}\\one{Text}\\ref{same}\\end{document}"}}));
        blocked(&mut server);
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":other}}),
        );
        allowed(&mut server);
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":provider}}),
        );
        allowed(&mut server);
        server.request(99, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn pdf_destination_edits_require_complete_executable_uses_over_stdio() {
    use latex_lsp::text::Text;

    for versioned in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
        let shared = uri.join("shared.tex").unwrap();
        let provider = uri.join("commands.sty").unwrap();
        let other = uri.join("unsaved.tex").unwrap();
        let source = "% 😀\r\n\\documentclass{article}\\newcommand\\unicodeword{😀}\\input{commands.sty}\\newcommand\\word{Text}\\begin{document}\\input{shared}\\typeout{\\unexpanded{\\hypertarget{ghost}{\\word}}}\\message{\\unexpanded{\\hypertarget{otherghost}{Text}}}\\hyperlink{here}{Link}\\hypertarget{safe}{Target}\\hyperlink{safe}{Link}\\word\\end{document}";
        let shared_source = "% 😀\r\n\\newcommand\\unicodeword{😀}\\hypertarget{here}{Target}";
        for (file, contents) in [(&uri, source), (&shared, shared_source), (&provider, "")] {
            std::fs::write(file.to_file_path().unwrap(), contents).unwrap();
        }
        let text = Text::new(source.into());
        let shared_text = Text::new(shared_source.into());
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"initializationOptions":{"distribution":{"enabled":false}},"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":versioned}}}}));
        server.notify("initialized", json!({}));
        for (file, contents, version) in [(&uri, source, 5), (&shared, shared_source, 7)] {
            server.notify("textDocument/didOpen", json!({"textDocument":{"uri":file,"languageId":"latex","version":version,"text":contents}}));
        }
        let blocked = |server: &mut Server, key: &str| {
            for method in ["textDocument/prepareRename", "textDocument/rename"] {
                server.send(json!({"jsonrpc":"2.0","id":20,"method":method,"params":{"textDocument":{"uri":uri},"position":text.position(source.find(key).unwrap() + 1),"newName":"fresh"}}));
                let response = server.until(|message| message["id"] == 20);
                assert!(
                    response["error"]["code"] == -32602
                        || response.get("result") == Some(&Value::Null),
                    "{key}: {response}"
                );
            }
        };
        let exact = |server: &mut Server, key: &str, expected: Vec<(&Url, i32, Vec<Value>)>| {
            let params = json!({"textDocument":{"uri":uri},"position":text.position(source.rfind(key).unwrap() + 1),"newName":"fresh"});
            assert!(!server
                .request(21, "textDocument/prepareRename", params.clone())
                .is_null());
            let response = server.request(22, "textDocument/rename", params);
            if versioned {
                let mut actual = response["documentChanges"].as_array().unwrap().clone();
                let mut expected: Vec<_> = expected.into_iter().map(|(file, version, edits)| json!({"textDocument":{"uri":file,"version":version},"edits":edits})).collect();
                actual.sort_by_key(|value| value["textDocument"]["uri"].to_string());
                expected.sort_by_key(|value| value["textDocument"]["uri"].to_string());
                assert_eq!(actual, expected);
                assert!(response.get("changes").is_none());
            } else {
                let mut changes = serde_json::Map::new();
                for (file, _, edits) in expected {
                    changes.insert(file.to_string(), json!(edits));
                }
                assert_eq!(response, json!({"changes":changes}));
            }
        };
        let spans = |text: &Text, key: &str| -> Vec<Value> {
            text.source.match_indices(key).map(|(start, _)| json!({"range":text.range(start, start + key.len()),"newText":"fresh"})).collect()
        };
        let here = || {
            vec![
                (&uri, 5, spans(&text, "here")),
                (&shared, 7, spans(&shared_text, "here")),
            ]
        };
        blocked(&mut server, "ghost");
        blocked(&mut server, "otherghost");
        exact(&mut server, "here", here());
        exact(&mut server, "safe", vec![(&uri, 5, spans(&text, "safe"))]);
        // A new independent root does not affect the destination's consumers.
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":other,"languageId":"latex","version":9,"text":"\\documentclass{article}\\def\\jump{\\hyperlink}\\begin{document}\\jump{here}{Link}\\end{document}"}}));
        exact(&mut server, "here", here());
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":other,"version":10},"contentChanges":[{"text":"\\documentclass{article}\\def\\jump{\\hyperlink}\\begin{document}\\input{shared}\\jump{here}{Link}\\end{document}"}]}));
        blocked(&mut server, "here");
        exact(&mut server, "safe", vec![(&uri, 5, spans(&text, "safe"))]);
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":other}}),
        );
        exact(&mut server, "here", here());
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":provider,"languageId":"latex","version":12,"text":"\\renewcommand\\hyperlink[2]{#2}"}}));
        blocked(&mut server, "here");
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":provider,"version":13},"contentChanges":[{"text":""}]}),
        );
        exact(&mut server, "here", here());
        exact(
            &mut server,
            "word",
            vec![(
                &uri,
                5,
                source.match_indices(r"\word")
                    .map(|(start, _)| json!({"range":text.range(start, start + 5),"newText":"\\fresh"}))
                    .collect(),
            )],
        );
        for (index, call) in [
            r"\def\jump{\hyperlink}\jump{here}{Link}",
            r"\let\jump\hyperlink\jump{here}{Link}",
            r"\csuse{hyperlink}{here}{Link}",
            r"\csname hyperlink\endcsname{here}{Link}",
        ]
        .into_iter()
        .enumerate()
        {
            let changed = format!("{source}{call}");
            server.notify(
                "textDocument/didChange",
                json!({"textDocument":{"uri":uri,"version":6 + index},"contentChanges":[{"text":changed}]}),
            );
            blocked(&mut server, "here");
        }
        server.request(99, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn inert_label_declarations_refresh_navigation_and_diagnostics_over_stdio() {
    use latex_lsp::text::Text;

    let directory = tempfile::tempdir().unwrap();
    let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    let provider = uri.join("commands.sty").unwrap();
    let source = "% 😀\r\n\\documentclass{article}\\newcommand\\unicodeword{😀}\\input{commands.sty}\\newcommand\\discard[1]{}\\begin{document}\\discard{\\label{same}}\\typeout{\\label{same}}\\label{same}\\ref{same}\\message{\\label{ghost}}\\ref{ghost}\\end{document}";
    std::fs::write(uri.to_file_path().unwrap(), source).unwrap();
    std::fs::write(provider.to_file_path().unwrap(), "").unwrap();
    let text = Text::new(source.into());
    let real = source.rfind(r"\label{same}").unwrap() + 7;
    let logged = source.find(r"\typeout{\label{same}").unwrap() + 16;
    let ghost = source.rfind("ghost").unwrap();
    let params = json!({"textDocument":{"uri":uri},"position":text.position(source.rfind("same").unwrap() + 1)});
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"initializationOptions":{"distribution":{"enabled":false}},"capabilities":{"textDocument":{"diagnostic":{}}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":5,"text":source}}),
    );
    let location = |start| json!({"uri":uri,"range":text.range(start, start + 4)});
    assert_eq!(
        server.request(2, "textDocument/definition", params.clone()),
        json!([location(real)])
    );
    let initial = server.request(
        3,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":uri}}),
    );
    assert_eq!(initial["items"].as_array().unwrap().len(), 1, "{initial}");
    assert_eq!(initial["items"][0]["code"], "undefined-reference");
    assert_eq!(
        initial["items"][0]["range"],
        json!(text.range(ghost, ghost + 5))
    );
    server.notify("textDocument/didOpen", json!({"textDocument":{"uri":provider,"languageId":"latex","version":12,"text":"\\renewcommand\\typeout[1]{#1}\\renewcommand\\message[1]{#1}"}}));
    assert_eq!(
        server.request(4, "textDocument/definition", params.clone()),
        json!([location(logged), location(real)])
    );
    let changed = server.request(
        5,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":uri},"previousResultId":initial["resultId"]}),
    );
    assert_eq!(changed["kind"], "full");
    assert_ne!(changed["resultId"], initial["resultId"]);
    assert_eq!(changed["items"].as_array().unwrap().len(), 1, "{changed}");
    assert_eq!(changed["items"][0]["code"], "duplicate-label");
    assert_eq!(
        changed["items"][0]["range"],
        json!(text.range(real, real + 4))
    );
    assert_eq!(
        changed["items"][0]["relatedInformation"][0]["location"],
        location(logged)
    );
    server.notify(
        "textDocument/didClose",
        json!({"textDocument":{"uri":provider}}),
    );
    assert_eq!(
        server.request(6, "textDocument/definition", params),
        json!([location(real)])
    );
    let restored = server.request(
        7,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":uri},"previousResultId":changed["resultId"]}),
    );
    assert_eq!(restored["items"], initial["items"]);
    for (version, reader) in [(6, "typeout"), (7, "message")] {
        let partial = format!("% 😀\r\n\\{reader}{{\\label{{ghost}}");
        let partial_text = Text::new(partial.clone());
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":uri,"version":version},"contentChanges":[{"text":partial}]}));
        assert_eq!(server.request(8, "textDocument/definition", json!({"textDocument":{"uri":uri},"position":partial_text.position(partial.find("ghost").unwrap() + 1)})), json!([]));
    }
    server.request(9, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn expanded_messages_keep_keys_inert_and_macro_names_editable_over_stdio() {
    use latex_lsp::text::Text;

    for versioned in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
        let provider = uri.join("commands.sty").unwrap();
        std::fs::write(provider.to_file_path().unwrap(), "").unwrap();
        std::fs::write(
            directory.path().join("data.bib"),
            "@book{collection,title={Raw}} @book{member,title={Member}}",
        )
        .unwrap();
        let source = "% 😀\r\n\\documentclass{article}\\input{commands.sty}\\usepackage{biblatex}\\addbibresource{data.bib}\\newcommand\\word{Text}\\begin{document}\\typeout{\\label{ghost}\\ref{absentlabel}\\word}\\mkbibparens{\\message{\\mkbibparens{\\entrydata{collection}{Text}}}}\\defbibentryset{collection}{member}\\cite{collection}\\label{safe}\\ref{safe}\\word\\end{document}";
        std::fs::write(uri.to_file_path().unwrap(), source).unwrap();
        let text = Text::new(source.into());
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"initializationOptions":{"distribution":{"enabled":false}},"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":versioned}},"textDocument":{"diagnostic":{}}}}));
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":uri,"languageId":"latex","version":5,"text":source}}),
        );
        let ghost = source.find("ghost").unwrap();
        let key = source.find(r"\entrydata{collection}").unwrap() + 11;
        let blocked = |server: &mut Server, at: usize| {
            for method in ["textDocument/prepareRename", "textDocument/rename"] {
                server.send(json!({"jsonrpc":"2.0","id":20,"method":method,"params":{"textDocument":{"uri":uri},"position":text.position(at + 1),"newName":"fresh"}}));
                let response = server.until(|message| message["id"] == 20);
                assert!(
                    response["error"]["code"] == -32602
                        || response.get("result") == Some(&Value::Null),
                    "{response}"
                );
            }
        };
        blocked(&mut server, ghost);
        blocked(&mut server, key);
        assert_eq!(
            server.request(
                2,
                "textDocument/definition",
                json!({"textDocument":{"uri":uri},"position":text.position(key + 1)})
            ),
            json!([])
        );
        let report = server.request(
            3,
            "textDocument/diagnostic",
            json!({"textDocument":{"uri":uri}}),
        );
        assert!(
            report["items"]
                .as_array()
                .unwrap()
                .iter()
                .all(|d| d["code"] != "undefined-reference"),
            "{report}"
        );
        let edits = |edit: Value| {
            if versioned {
                assert_eq!(edit["documentChanges"].as_array().unwrap().len(), 1);
                assert_eq!(
                    edit["documentChanges"][0]["textDocument"],
                    json!({"uri":uri,"version":5})
                );
                edit["documentChanges"][0]["edits"].clone()
            } else {
                assert_eq!(edit["changes"].as_object().unwrap().len(), 1);
                edit["changes"][uri.as_str()].clone()
            }
        };
        for (id, name, new) in [(4, "safe", "fresh"), (5, "word", "term")] {
            let actual = edits(server.request(id, "textDocument/rename", json!({"textDocument":{"uri":uri},"position":text.position(source.rfind(name).unwrap() + 1),"newName":new})));
            let old = if name == "word" {
                format!(r"\{name}")
            } else {
                name.into()
            };
            let replacement = if name == "word" {
                format!(r"\{new}")
            } else {
                new.into()
            };
            let expected = source
                .match_indices(&old)
                .map(
                    |(at, _)| json!({"range":text.range(at, at + old.len()),"newText":replacement}),
                )
                .collect::<Vec<_>>();
            assert_eq!(actual, json!(expected));
        }
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":provider,"languageId":"latex","version":12,"text":"\\renewcommand\\typeout[1]{#1}"}}));
        let restored = edits(server.request(6, "textDocument/rename", json!({"textDocument":{"uri":uri},"position":text.position(ghost + 1),"newName":"fresh"})));
        assert_eq!(
            restored,
            json!([{"range":text.range(ghost, ghost + 5),"newText":"fresh"}])
        );
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":provider}}),
        );
        blocked(&mut server, ghost);
        for (version, reader) in [(6, "typeout"), (7, "message")] {
            let partial = format!("% 😀\r\n\\documentclass{{article}}\\input{{commands.sty}}\\usepackage{{biblatex}}\\addbibresource{{data.bib}}\\begin{{document}}\\defbibentryset{{collection}}{{member}}\\{reader}{{\\mkbibparens{{\\entrydata{{collection}}{{Text}}}}");
            let partial_text = Text::new(partial.clone());
            let at = partial_text.position(partial.find(r"\entrydata{collection}").unwrap() + 12);
            server.notify("textDocument/didChange", json!({"textDocument":{"uri":uri,"version":version},"contentChanges":[{"text":partial}]}));
            let params = json!({"textDocument":{"uri":uri},"position":at,"newName":"fresh"});
            assert_eq!(
                server.request(8, "textDocument/definition", params.clone()),
                json!([])
            );
            for method in ["textDocument/prepareRename", "textDocument/rename"] {
                server.send(json!({"jsonrpc":"2.0","id":30,"method":method,"params":params}));
                let response = server.until(|message| message["id"] == 30);
                assert!(
                    response["error"]["code"] == -32602
                        || response.get("result") == Some(&Value::Null),
                    "{reader}: {response}"
                );
            }
        }
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":uri,"version":8},"contentChanges":[{"text":source}]}),
        );
        blocked(&mut server, ghost);
        server.request(7, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn label_declaration_data_rejects_edits_and_refreshes_unsaved_provider_arities() {
    use latex_lsp::text::Text;

    for versioned in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
        let provider = uri.join("commands.sty").unwrap();
        std::fs::write(
            provider.to_file_path().unwrap(),
            r"\newcommand\discard[1]{}",
        )
        .unwrap();
        let source = "% 😀\r\n\\documentclass{article}\\input{commands.sty}\\def\\ifblank#1#2#3{#2}\\begin{document}\\discard{\\label{ghost}}\\label{safe}\\ref{safe}\\end{document}";
        std::fs::write(uri.to_file_path().unwrap(), source).unwrap();
        let text = Text::new(source.into());
        let ghost = source.find("ghost").unwrap();
        let safe = source.rfind("safe").unwrap();
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"initializationOptions":{"distribution":{"enabled":false}},"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":versioned}}}}));
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":uri,"languageId":"latex","version":5,"text":source}}),
        );
        let query = json!({"textDocument":{"uri":uri},"position":text.position(ghost + 1),"newName":"fresh"});
        let blocked = |server: &mut Server| {
            for method in ["textDocument/prepareRename", "textDocument/rename"] {
                server.send(json!({"jsonrpc":"2.0","id":20,"method":method,"params":query}));
                let result = server.until(|message| message["id"] == 20);
                assert!(
                    result["error"]["code"] == -32602 || result.get("result") == Some(&Value::Null),
                    "{result}"
                );
            }
        };
        blocked(&mut server);
        let edit = server.request(2, "textDocument/rename", json!({"textDocument":{"uri":uri},"position":text.position(safe + 1),"newName":"fresh"}));
        let edits = if versioned {
            assert_eq!(edit["documentChanges"].as_array().unwrap().len(), 1);
            assert_eq!(
                edit["documentChanges"][0]["textDocument"],
                json!({"uri":uri,"version":5})
            );
            &edit["documentChanges"][0]["edits"]
        } else {
            &edit["changes"][uri.as_str()]
        };
        assert_eq!(edits.as_array().unwrap().len(), 2);
        assert!(edits
            .as_array()
            .unwrap()
            .iter()
            .all(|edit| edit["newText"] == "fresh"));
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":provider,"languageId":"latex","version":12,"text":"\\newcommand\\discard{}"}}));
        let restored = server.request(3, "textDocument/rename", query.clone());
        let edits = if versioned {
            assert_eq!(
                restored["documentChanges"][0]["textDocument"],
                json!({"uri":uri,"version":5})
            );
            &restored["documentChanges"][0]["edits"]
        } else {
            &restored["changes"][uri.as_str()]
        };
        assert_eq!(
            edits,
            &json!([{"range":text.range(ghost, ghost + 5),"newText":"fresh"}])
        );
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":provider,"version":13},"contentChanges":[{"text":"\\newcommand\\discard[1]{}"}]}));
        blocked(&mut server);
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":provider,"version":14},"contentChanges":[{"text":"\\newcommand\\discard{}"}]}));
        assert!(!server
            .request(4, "textDocument/rename", query.clone())
            .is_null());
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":provider}}),
        );
        blocked(&mut server);
        server.request(5, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn standard_footnotes_negotiate_completion_and_refresh_cross_file_overrides() {
    use latex_lsp::text::Text;

    for snippets in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
        let provider = uri.join("commands.sty").unwrap();
        std::fs::write(provider.to_file_path().unwrap(), "").unwrap();
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"initializationOptions":{"distribution":{"enabled":false}},"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true}},"textDocument":{"completion":{"completionItem":{"snippetSupport":snippets}}}}}));
        server.notify("initialized", json!({}));
        let source = "% 😀\r\n\\documentclass{article}\\input{commands.sty}\\begin{document}\\section{Heading}\\label{safe}\\footnotemark[7]\\footnotetext[7]{Note \\ref{safe}}\\footnotemark{\\label{after}}\\ref{after}\\footno\\end{document}";
        let text = Text::new(source.into());
        std::fs::write(uri.to_file_path().unwrap(), source).unwrap();
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":uri,"languageId":"latex","version":5,"text":source}}),
        );
        let cursor = source.find(r"\footno\end").unwrap() + r"\footno".len();
        let completion = server.request(
            2,
            "textDocument/completion",
            json!({"textDocument":{"uri":uri},"position":text.position(cursor)}),
        );
        for (name, expected) in [
            ("footnotemark", "footnotemark"),
            ("footnotetext", "footnotetext{${1:text}}"),
        ] {
            let item = completion
                .as_array()
                .unwrap()
                .iter()
                .find(|item| item["label"] == name)
                .unwrap();
            assert_eq!(
                item["textEdit"]["newText"],
                if snippets { expected } else { name }
            );
            assert_eq!(
                item["textEdit"]["range"],
                json!(text.range(cursor - 6, cursor))
            );
            assert_eq!(item["insertTextFormat"], if snippets { 2 } else { 1 });
        }
        for (prefix, label, active) in [
            (r"\footnotemark[", r"\footnotemark[number]", 0),
            (r"\footnotetext[", r"\footnotetext[number]{text}", 0),
            ("{Note ", r"\footnotetext[number]{text}", 1),
        ] {
            let offset = source.find(prefix).unwrap() + prefix.len();
            let help = server.request(
                3,
                "textDocument/signatureHelp",
                json!({"textDocument":{"uri":uri},"position":text.position(offset)}),
            );
            assert_eq!(help["signatures"][0]["label"], label);
            assert_eq!(help["activeParameter"], active);
        }
        let query = source.find(r"\ref{after}").unwrap() + 5;
        let declaration = source.find(r"\label{after}").unwrap() + 7;
        let params = json!({"textDocument":{"uri":uri},"position":text.position(query)});
        let expected = json!([{"uri":uri,"range":text.range(declaration, declaration + 5)}]);
        assert_eq!(
            server.request(4, "textDocument/definition", params.clone()),
            expected
        );
        let edit = server.request(
            5,
            "textDocument/rename",
            json!({"textDocument":{"uri":uri},"position":text.position(query),"newName":"fresh"}),
        );
        assert_eq!(edit["documentChanges"].as_array().unwrap().len(), 1);
        assert_eq!(
            edit["documentChanges"][0]["textDocument"],
            json!({"uri":uri,"version":5})
        );
        let edits: Vec<tower_lsp::lsp_types::TextEdit> =
            serde_json::from_value(edit["documentChanges"][0]["edits"].clone()).unwrap();
        let mut ranges = edits.iter().map(|edit| edit.range).collect::<Vec<_>>();
        ranges.sort_by_key(|range| range.start);
        assert_eq!(
            ranges,
            [
                text.range(declaration, declaration + 5),
                text.range(query, query + 5)
            ]
        );
        assert!(edits.iter().all(|edit| edit.new_text == "fresh"));

        let inner_at = source.find(r"\ref{safe}").unwrap() + 5;
        let safe_at = source.find(r"\label{safe}").unwrap() + 7;
        let inner = json!({"textDocument":{"uri":uri},"position":text.position(inner_at)});
        let inner_expected = json!([{"uri":uri,"range":text.range(safe_at, safe_at + 4)}]);
        assert_eq!(
            server.request(11, "textDocument/definition", inner.clone()),
            inner_expected
        );
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":provider,"languageId":"latex","version":12,"text":"\\renewcommand\\footnotetext[2][]{}"}}));
        assert_eq!(
            server.request(6, "textDocument/definition", inner.clone()),
            json!([])
        );
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":provider,"version":13},"contentChanges":[{"text":""}]}),
        );
        assert_eq!(
            server.request(7, "textDocument/definition", inner.clone()),
            inner_expected
        );
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":provider,"version":14},"contentChanges":[{"text":"\\renewcommand\\footnotetext[2][]{}"}]}));
        assert_eq!(
            server.request(8, "textDocument/definition", inner.clone()),
            json!([])
        );
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":provider}}),
        );
        assert_eq!(
            server.request(9, "textDocument/definition", inner),
            inner_expected
        );
        server.request(10, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn compiled_reference_inlay_hints_follow_ranges_configuration_and_aux_changes() {
    let dir = tempfile::tempdir().unwrap();
    let uri = Url::from_file_path(dir.path().join("main.tex")).unwrap();
    let source = "😀 \\documentclass{article}\\label{x}\\ref{x}\\ref{unknown}";
    std::fs::write(dir.path().join("main.tex"), source).unwrap();
    std::fs::write(
        dir.path().join("main.aux"),
        "\\newlabel{x}{{1.2}{5}{A title}{}}\n",
    )
    .unwrap();
    let mut server = Server::start();
    let initialized=server.request(1,"initialize",json!({"processId":null,"rootUri":Url::from_directory_path(dir.path()).unwrap(),"capabilities":{}}));
    assert_eq!(initialized["capabilities"]["inlayHintProvider"], true);
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":1,"text":source}}),
    );
    let params = json!({"textDocument":{"uri":uri},"range":{"start":{"line":0,"character":0},"end":{"line":1,"character":0}}});
    let hints = server.request(2, "textDocument/inlayHint", params.clone());
    assert_eq!(hints.as_array().unwrap().len(), 1);
    assert_eq!(hints[0]["label"], "→ 1.2, p. 5");
    assert!(hints[0]["tooltip"].as_str().unwrap().contains("A title"));
    let empty=server.request(3,"textDocument/inlayHint",json!({"textDocument":{"uri":uri},"range":{"start":{"line":1,"character":0},"end":{"line":2,"character":0}}}));
    assert_eq!(empty, json!([]));
    std::fs::write(
        dir.path().join("main.aux"),
        "\\newlabel{x}{{3}{8}{Updated title}{}}\n",
    )
    .unwrap();
    assert_eq!(
        server.request(4, "textDocument/inlayHint", params.clone())[0]["label"],
        "→ 3, p. 8"
    );
    server.notify(
        "workspace/didChangeConfiguration",
        json!({"settings":{"inlayHints":{"enabled":false}}}),
    );
    assert_eq!(
        server.request(5, "textDocument/inlayHint", params),
        json!([])
    );
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn indexing_limits_are_visible_and_completion_reports_incompleteness() {
    let dir = tempfile::tempdir().unwrap();
    for name in ["a.tex", "b.tex"] {
        std::fs::write(dir.path().join(name), "text").unwrap();
    }
    let uri = Url::from_file_path(dir.path().join("a.tex")).unwrap();
    let mut server = Server::start();
    server.request(1,"initialize",json!({"processId":null,"rootUri":Url::from_directory_path(dir.path()).unwrap(),"capabilities":{},"initializationOptions":{"distribution":{"enabled":false},"indexing":{"maxFiles":1,"completionLimit":3}}}));
    server.notify("initialized", json!({}));
    let status = server.request(
        2,
        "workspace/executeCommand",
        json!({"command":"latex.indexingStatus"}),
    );
    assert_eq!(status["files"], 1);
    assert_eq!(status["truncated"], json!(["maxFiles"]));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":1,"text":"\\"}}),
    );
    let response = server.request(
        3,
        "textDocument/completion",
        json!({"textDocument":{"uri":uri},"position":{"line":0,"character":1}}),
    );
    assert_eq!(response["isIncomplete"], true);
    assert_eq!(response["items"].as_array().unwrap().len(), 3);
    server.notify("workspace/didChangeConfiguration",json!({"settings":{"distribution":{"enabled":false},"indexing":{"maxFiles":4,"completionLimit":3}}}));
    let status = server.request(
        4,
        "workspace/executeCommand",
        json!({"command":"latex.indexingStatus"}),
    );
    assert_eq!(status["files"], 2);
    assert_eq!(status["truncated"], json!([]));
    let status = server.request(
        5,
        "workspace/executeCommand",
        json!({"command":"latex.reindex"}),
    );
    assert_eq!(status["files"], 2);
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn chktex_checks_buffer_on_save_and_discards_stale_results() {
    use std::os::unix::fs::PermissionsExt;
    let dir = tempfile::tempdir().unwrap();
    let executable = dir.path().join("checker");
    std::fs::write(&executable, "#!/bin/sh\nprintf '%s\\n' \"$@\" > args\ncat > input\ntouch ready\nwhile test -f delay; do sleep 0.05; done\nprintf '1:11:3:Warning:11:Use dots: here\\n'\nexit 1\n").unwrap();
    std::fs::set_permissions(&executable, std::fs::Permissions::from_mode(0o755)).unwrap();
    let uri = Url::from_file_path(dir.path().join("main.tex")).unwrap();
    std::fs::write(dir.path().join("main.tex"), "disk").unwrap();
    let mut server = Server::start();
    server.request(1,"initialize",json!({"processId":null,"rootUri":Url::from_directory_path(dir.path()).unwrap(),"capabilities":{},"initializationOptions":{"distribution":{"enabled":false},"diagnostics":{"chktex":{"enabled":true,"executable":executable}}}}));
    server.notify("initialized", json!({}));
    open_formatting_document(&mut server, &uri, "😀 hello...\n");
    server.notify("textDocument/didSave", json!({"textDocument":{"uri":uri}}));
    let diagnostic = server.until(|message| {
        message["method"] == "textDocument/publishDiagnostics"
            && message["params"]["diagnostics"]
                .as_array()
                .is_some_and(|items| items.iter().any(|item| item["source"] == "chktex"))
    });
    assert_eq!(
        diagnostic["params"]["diagnostics"][0]["range"],
        json!({"start":{"line":0,"character":8},"end":{"line":0,"character":11}})
    );
    assert_eq!(
        std::fs::read_to_string(dir.path().join("input")).unwrap(),
        "😀 hello...\n"
    );
    assert!(std::fs::read_to_string(dir.path().join("args"))
        .unwrap()
        .contains("-I0"));
    std::fs::write(dir.path().join("delay"), "").unwrap();
    std::fs::remove_file(dir.path().join("ready")).unwrap();
    server.notify("textDocument/didSave", json!({"textDocument":{"uri":uri}}));
    wait_for_file(&dir.path().join("ready"));
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"text":"clean\n"}]}),
    );
    // A later request must run while the checker still waits.
    server.request(
        2,
        "textDocument/documentSymbol",
        json!({"textDocument":{"uri":uri}}),
    );
    std::fs::remove_file(dir.path().join("delay")).unwrap();
    server.until(|message| {
        message["method"] == "textDocument/publishDiagnostics"
            && message["params"]["version"] == 2
            && message["params"]["diagnostics"] == json!([])
    });
    server.request(3, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

