#[cfg(unix)]
fn formatting_server(script: &str, timeout: u64) -> (Server, tempfile::TempDir, Url) {
    use std::os::unix::fs::PermissionsExt;
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let executable = root.join("formatter with spaces");
    std::fs::write(&executable, format!("#!/bin/sh\n{script}\n")).unwrap();
    std::fs::set_permissions(&executable, std::fs::Permissions::from_mode(0o755)).unwrap();
    let uri = Url::from_file_path(root.join("main.tex")).unwrap();
    std::fs::write(root.join("main.tex"), "original disk contents").unwrap();
    let mut server = Server::start();
    let initialized = server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{},"initializationOptions":{"formatting":{"executable":executable,"timeoutSeconds":timeout}}}));
    assert_eq!(
        initialized["capabilities"]["documentFormattingProvider"],
        true
    );
    server.notify("initialized", json!({}));
    (server, directory, uri)
}

#[cfg(unix)]
fn open_formatting_document(server: &mut Server, uri: &Url, source: &str) {
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":1,"text":source}}),
    );
}

fn formatting_params(uri: &Url) -> Value {
    json!({"textDocument":{"uri":uri},"options":{"tabSize":4,"insertSpaces":true}})
}

#[test]
#[cfg(unix)]
fn formatting_uses_buffer_text_default_tex_fmt_and_configurable_latexindent() {
    use latex_lsp::text::Text;
    use tower_lsp::lsp_types::{TextDocumentContentChangeEvent, TextEdit};
    let (mut server, directory, uri) = formatting_server(
        "printf '%s\\n' \"$@\" > arguments\ncat > input\nsed 's/hello/formatted/' input",
        10,
    );
    let root = directory.path();
    let source = "% 😀中文\r\n\\begin{itemize}\r\n\\item hello\r\n\\end{itemize}\r\n";
    open_formatting_document(&mut server, &uri, source);
    let edits = server.request(2, "textDocument/formatting", formatting_params(&uri));
    let edits: Vec<TextEdit> = serde_json::from_value(edits).unwrap();
    assert_eq!(edits.len(), 1);
    let edits = edits
        .into_iter()
        .map(|edit| TextDocumentContentChangeEvent {
            range: Some(edit.range),
            range_length: None,
            text: edit.new_text,
        })
        .collect();
    assert_eq!(
        Text::new(source.into()).changed(edits).unwrap().source,
        source.replace("hello", "formatted")
    );
    assert_eq!(std::fs::read_to_string(root.join("input")).unwrap(), source);
    assert_eq!(
        std::fs::read_to_string(root.join("arguments")).unwrap(),
        "--stdin\n--tabsize\n4\n"
    );
    assert_eq!(
        std::fs::read_to_string(root.join("main.tex")).unwrap(),
        "original disk contents"
    );
    server.notify("workspace/didChangeConfiguration", json!({"settings":{"formatting":{"formatter":"latexindent","executable":root.join("formatter with spaces")}}}));
    let mut params = formatting_params(&uri);
    params["options"]["insertSpaces"] = json!(false);
    server.request(3, "textDocument/formatting", params);
    let arguments = std::fs::read_to_string(root.join("arguments")).unwrap();
    assert!(arguments.contains("-l\n"));
    assert!(arguments
        .lines()
        .any(|arg| arg.starts_with("-g=") && arg.ends_with("/indent.log")));
    let scratch = arguments
        .lines()
        .find_map(|arg| arg.strip_prefix("-c="))
        .unwrap();
    assert!(!std::path::Path::new(scratch).exists());
    assert!(arguments.contains("-y=defaultIndent: \"\\t\"\n"));
    assert!(arguments.ends_with("-\n"));
    assert!(!root.join("indent.log").exists());
    server.notify("workspace/didChangeConfiguration", json!({"settings":{"formatting":{"executable":root.join("formatter with spaces"),"arguments":["literal;$(false)","--stdin"]}}}));
    server.request(4, "textDocument/formatting", formatting_params(&uri));
    assert_eq!(
        std::fs::read_to_string(root.join("arguments")).unwrap(),
        "literal;$(false)\n--stdin\n"
    );
    open_formatting_document(&mut server, &uri, "% unchanged\r\n");
    assert_eq!(
        server.request(5, "textDocument/formatting", formatting_params(&uri)),
        json!([])
    );
    let bib = Url::from_file_path(root.join("refs.bib")).unwrap();
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":bib,"languageId":"bibtex","version":1,"text":"@book{key}"}}),
    );
    assert_eq!(
        server.request(6, "textDocument/formatting", formatting_params(&bib)),
        json!([])
    );
    server.request(7, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn formatting_reports_process_failures_invalid_output_and_timeout() {
    for (script, expected) in [
        (
            "cat >/dev/null; echo formatter-failed >&2; exit 2",
            "formatter-failed",
        ),
        ("cat >/dev/null; printf '\\377'", "invalid UTF-8"),
        ("cat >/dev/null", "empty output"),
        ("sleep 30", "timed out"),
        (
            "cat >/dev/null; head -c 16777217 /dev/zero",
            "exceeds 16 MiB",
        ),
    ] {
        let (mut server, _directory, uri) = formatting_server(script, 1);
        open_formatting_document(&mut server, &uri, "hello\n");
        server.send(json!({"jsonrpc":"2.0","id":2,"method":"textDocument/formatting","params":formatting_params(&uri)}));
        let response = server.until(|message| message["id"] == 2);
        assert_eq!(response["error"]["code"], -32803, "{response}");
        assert!(
            response["error"]["message"]
                .as_str()
                .unwrap()
                .contains(expected),
            "{response}"
        );
        server.request(3, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
    let (mut server, directory, uri) = formatting_server("cat", 10);
    open_formatting_document(&mut server, &uri, "hello\n");
    server.notify("workspace/didChangeConfiguration", json!({"settings":{"formatting":{"executable":directory.path().join("missing-formatter")}}}));
    server.send(json!({"jsonrpc":"2.0","id":2,"method":"textDocument/formatting","params":formatting_params(&uri)}));
    let response = server.until(|message| message["id"] == 2);
    assert!(response["error"]["message"]
        .as_str()
        .unwrap()
        .contains("Cannot start formatter"));
    server.request(3, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn formatting_rejects_stale_results_and_keeps_other_requests_responsive() {
    for change_configuration in [false, true] {
        let (mut server, directory, uri) = formatting_server(
            "cat > input; touch ready; while [ ! -f continue ]; do sleep 0.01; done; cat input",
            10,
        );
        open_formatting_document(&mut server, &uri, "hello\n");
        server.send(json!({"jsonrpc":"2.0","id":2,"method":"textDocument/formatting","params":formatting_params(&uri)}));
        wait_for_file(&directory.path().join("ready"));
        if change_configuration {
            server.notify(
                "workspace/didChangeConfiguration",
                json!({"settings":{"formatting":{"formatter":"latexindent"}}}),
            );
        } else {
            server.notify("textDocument/didChange", json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"text":"edited\n"}]}));
        }
        server.request(
            3,
            "textDocument/documentSymbol",
            json!({"textDocument":{"uri":uri}}),
        );
        std::fs::write(directory.path().join("continue"), "").unwrap();
        let response = server.until(|message| message["id"] == 2);
        assert_eq!(response["error"]["code"], -32801, "{response}");
        server.request(4, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn formatting_cancellation_and_disconnect_reap_subprocesses() {
    for mode in ["cancel", "exit", "eof", "shutdown"] {
        let (mut server, directory, uri) = formatting_server(
            "sleep 30 &\nprintf '%s' \"$!\" > descendant\ntouch ready\nwait",
            30,
        );
        open_formatting_document(&mut server, &uri, "hello\n");
        server.send(json!({"jsonrpc":"2.0","id":2,"method":"textDocument/formatting","params":formatting_params(&uri)}));
        wait_for_file(&directory.path().join("ready"));
        let pid: i32 = std::fs::read_to_string(directory.path().join("descendant"))
            .unwrap()
            .parse()
            .unwrap();
        if mode == "cancel" {
            server.notify("$/cancelRequest", json!({"id":2}));
            let response = server.until(|message| message["id"] == 2);
            assert_eq!(response["error"]["code"], -32800);
            server.request(3, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        } else if mode == "shutdown" {
            // The pending formatting request may return cancellation before shutdown responds.
            server.send(json!({"jsonrpc":"2.0","id":3,"method":"shutdown"}));
            server.until(|message| message["id"] == 2);
            server.until(|message| message["id"] == 3);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        } else {
            let status = server.terminate_transport(mode);
            assert_eq!(status.code(), Some(if mode == "exit" { 1 } else { 0 }));
        }
        let deadline = std::time::Instant::now() + Duration::from_secs(3);
        while unsafe { libc::kill(pid, 0) } == 0 {
            // Reparented children can remain zombies briefly; they have already stopped.
            if std::fs::read_to_string(format!("/proc/{pid}/stat"))
                .is_ok_and(|stat| stat.contains(") Z"))
            {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "formatter descendant survived {mode}"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
    }
}

#[test]
#[ignore = "requires tex-fmt on PATH"]
fn formatting_with_real_tex_fmt_preserves_verbatim_and_is_idempotent() {
    real_formatter_roundtrip("tex-fmt");
}

#[test]
#[ignore = "requires latexindent on PATH"]
fn formatting_with_real_latexindent_preserves_verbatim_and_is_idempotent() {
    real_formatter_roundtrip("latexindent");
}

fn real_formatter_roundtrip(formatter: &str) {
    use latex_lsp::text::Text;
    use tower_lsp::lsp_types::{TextDocumentContentChangeEvent, TextEdit};
    let directory = tempfile::tempdir().unwrap();
    let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    let source = "% 😀\r\n\\begin{itemize}\r\n\\item hello\r\n\\end{itemize}\r\n\\begin{verbatim}\r\n   raw   data\r\n\\end{verbatim}\r\n";
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"capabilities":{},"initializationOptions":{"formatting":{"formatter":formatter}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":1,"text":source}}),
    );
    let edits: Vec<TextEdit> = serde_json::from_value(server.request(
        2,
        "textDocument/formatting",
        formatting_params(&uri),
    ))
    .unwrap();
    assert!(!edits.is_empty());
    let edits = edits
        .into_iter()
        .map(|edit| TextDocumentContentChangeEvent {
            range: Some(edit.range),
            range_length: None,
            text: edit.new_text,
        })
        .collect();
    let formatted = Text::new(source.into()).changed(edits).unwrap().source;
    assert!(formatted.contains("    \\item hello\r\n"), "{formatted:?}");
    assert!(formatted.contains("\r\n   raw   data\r\n"));
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"text":formatted}]}),
    );
    assert_eq!(
        server.request(3, "textDocument/formatting", formatting_params(&uri)),
        json!([])
    );
    assert!(!directory.path().join("main.tex").exists());
    server.request(4, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn minted_inline_code_stays_opaque_after_incremental_changes_over_stdio() {
    use latex_lsp::text::Text;
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let main = Url::from_file_path(root.join("main.tex")).unwrap();
    let source = "% 😀\r\n\\label{kept}\r\n\\mintinline[breaklines]{tex}|\\label{kept}\\input{fake} }%|\r\n\\ref{kept}\r\n";
    std::fs::write(root.join("main.tex"), source).unwrap();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{"textDocument":{"diagnostic":{}},"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":7,"text":source}}),
    );
    let diagnostics = server.request(
        2,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(diagnostics["items"], json!([]), "{diagnostics}");
    let position = Text::new(source.into()).position(source.rfind("kept").unwrap() + 1);
    let references = server.request(3, "textDocument/references", json!({"textDocument":{"uri":main},"position":position,"context":{"includeDeclaration":true}}));
    assert_eq!(references.as_array().unwrap().len(), 2, "{references}");
    let edit = server.request(
        4,
        "textDocument/rename",
        json!({"textDocument":{"uri":main},"position":position,"newName":"changed"}),
    );
    assert_eq!(edit["documentChanges"][0]["textDocument"]["version"], 7);
    assert_eq!(
        edit["documentChanges"][0]["edits"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    let inside = Text::new(source.into()).position(source.find("\\input").unwrap() + 3);
    assert_eq!(
        server.request(
            5,
            "textDocument/definition",
            json!({"textDocument":{"uri":main},"position":inside})
        ),
        json!([])
    );
    let text = Text::new(source.into());
    let start = source.find('|').unwrap();
    let end = source.rfind('|').unwrap() + 1;
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":8},"contentChanges":[{"range":text.range(start,end),"text":"{\\label{kept} %\r\n{nested}}"}]}));
    let diagnostics = server.request(
        6,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(diagnostics["items"], json!([]), "{diagnostics}");
    let symbols = server.request(
        7,
        "textDocument/documentSymbol",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(symbols.as_array().unwrap().len(), 1, "{symbols}");
    assert_eq!(symbols[0]["name"], "kept");
    let mut source = source.to_owned();
    source.replace_range(start..end, "{\\label{kept} %\r\n{nested}}");
    for (stage, code) in [
        "\\textbf{\\mintinline{tex}{a\\}\\label{kept}\\input{fake}b}}",
        "\\textbf{\\mintinline{tex}|a{b|\\label{kept}\\input{fake}}d|}",
        "\\let\\strong\\textbf\\strong{\\mintinline{tex}% header\r\n|\\label{kept}\\input{fake}|}",
        "\\relax{\\mintinline{tex}{a\\}}",
        "\\mintinline{tex}%\\label{kept}\\input{fake}%",
        "\\textbf{\\mintinline{tex}{a\\}\\label{kept}\\input{fake}b}",
        "\\textbf{\\mintinline{tex}{a\\}\\label{kept}\\input{fake}b}}",
        "\\let\\code\\mintinline\\code{tex}|\\label{kept}\\input{fake}|",
        "\\newcommand{\\code}{\\mintinline}\\code{tex}|\\label{kept}\\input{fake}|",
        "\\mintinline{tex}%\\label{kept}\\input{fake}%",
    ]
    .into_iter()
    .enumerate()
    {
        let start = source.find("\\label{kept}\r\n").unwrap() + "\\label{kept}\r\n".len();
        let end = source.rfind("\r\n\\ref").unwrap();
        let text = Text::new(source.clone());
        let version = 9 + stage;
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":version},"contentChanges":[{"range":text.range(start,end),"text":code}]}));
        source.replace_range(start..end, code);
        let text = Text::new(source.clone());
        let id = 20 + stage as u64 * 8;
        let diagnostics = server.request(
            id,
            "textDocument/diagnostic",
            json!({"textDocument":{"uri":main}}),
        );
        if stage == 5 {
            assert_eq!(
                diagnostics["items"].as_array().unwrap().len(),
                1,
                "{source}: {diagnostics}"
            );
            assert_eq!(diagnostics["items"][0]["message"], "Unclosed brace");
        } else {
            assert_eq!(diagnostics["items"], json!([]), "{source}: {diagnostics}");
        }
        let position = text.position(source.rfind("kept").unwrap());
        let edit = server.request(
            id + 1,
            "textDocument/rename",
            json!({"textDocument":{"uri":main},"position":position,"newName":"changed"}),
        );
        assert_eq!(
            edit["documentChanges"][0]["textDocument"]["version"],
            version
        );
        assert_eq!(
            edit["documentChanges"][0]["edits"]
                .as_array()
                .unwrap()
                .len(),
            2,
            "{source}: {edit}"
        );
        let links = server.request(
            id + 2,
            "textDocument/documentLink",
            json!({"textDocument":{"uri":main}}),
        );
        assert_eq!(links, json!([]), "{source}: {links}");
        let symbols = server.request(
            id + 3,
            "textDocument/documentSymbol",
            json!({"textDocument":{"uri":main}}),
        );
        assert_eq!(
            symbols.as_array().unwrap().len(),
            if matches!(stage, 2 | 7 | 8) { 2 } else { 1 },
            "{source}: {symbols}"
        );
        if let Some(offset) = code.find("\\input") {
            let inside = text.position(start + offset + 3);
            assert_eq!(
                server.request(
                    id + 4,
                    "textDocument/signatureHelp",
                    json!({"textDocument":{"uri":main},"position":inside})
                ),
                Value::Null
            );
            assert_eq!(
                server.request(
                    id + 5,
                    "textDocument/definition",
                    json!({"textDocument":{"uri":main},"position":inside})
                ),
                json!([])
            );
        }
    }
    server.request(100, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn minted_missing_files_publish_and_pull_versioned_repairs_and_clear_after_rebuilding() {
    use latex_lsp::text::Text;
    use tower_lsp::lsp_types::TextEdit;
    for pull in [false, true] {
        let script = r#"cp "${2%/*}/fixture.log" "$1/main.log"
printf '%%PDF-1.4\n' > "$1/main.pdf"
printf 'PWD %s\nINPUT %s\n' "$PWD" "$2" > "$1/main.fls"
"#;
        let mut capabilities = json!({
            "workspace":{"workspaceEdit":{"documentChanges":true}},
            "textDocument":{"codeAction":{"codeActionLiteralSupport":{"codeActionKind":{"valueSet":["quickfix"]}}}}
        });
        if pull {
            capabilities["textDocument"]["diagnostic"] = json!({});
        }
        let (mut server, directory, main) =
            fake_build_server_capabilities(script, false, capabilities);
        let root = directory.path();
        let source =
            "% 😀\r\n\\documentclass{article}\r\n\\inputminted[linenos]{rust}{smaple.rs}\r\n";
        std::fs::write(root.join("main.tex"), source).unwrap();
        std::fs::write(root.join("sample.rs"), "Code.\n").unwrap();
        std::fs::write(root.join("fixture.log"), "(./main.tex\n./main.tex:3: Package minted Error: Cannot find input file \"smaple.rs\"; inserting placeholder.\n\nl.3 \\inputminted[linenos]{rust}{smaple.rs}\n)\n").unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["stale"], false, "{finished}");
        let items = if pull {
            server.request(
                3,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":main}}),
            )["items"]
                .clone()
        } else {
            server.until(|message| {
                message["method"] == "textDocument/publishDiagnostics"
                    && message["params"]["uri"] == main.as_str()
                    && message["params"]["diagnostics"]
                        .as_array()
                        .is_some_and(|items| {
                            items
                                .iter()
                                .any(|item| item["code"] == "missing-minted-input")
                        })
            })["params"]["diagnostics"]
                .clone()
        };
        let item = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["code"] == "missing-minted-input")
            .unwrap_or_else(|| panic!("{items}"));
        let at = source.find("smaple.rs").unwrap();
        assert_eq!(
            item["range"],
            serde_json::to_value(Text::new(source.into()).range(at, at + "smaple.rs".len()))
                .unwrap()
        );
        let actions = server.request(4, "textDocument/codeAction", json!({"textDocument":{"uri":main},"range":item["range"],"context":{"diagnostics":[item],"only":["quickfix"]}}));
        assert_eq!(actions.as_array().unwrap().len(), 1, "{actions}");
        assert_eq!(
            actions[0]["edit"]["documentChanges"][0]["textDocument"]["version"],
            2
        );
        let edit: TextEdit =
            serde_json::from_value(actions[0]["edit"]["documentChanges"][0]["edits"][0].clone())
                .unwrap();
        let updated = Text::new(source.into())
            .changed(vec![tower_lsp::lsp_types::TextDocumentContentChangeEvent {
                range: Some(edit.range),
                range_length: None,
                text: edit.new_text,
            }])
            .unwrap();
        assert_eq!(updated.source, source.replace("smaple.rs", "sample.rs"));
        std::fs::write(root.join("main.tex"), &updated.source).unwrap();
        std::fs::write(root.join("fixture.log"), "(./main.tex)\n").unwrap();
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":3},"contentChanges":[{"text":updated.source}]}));
        server.request(
            5,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["status"], "success", "{finished}");
        assert_eq!(finished["params"]["stale"], false, "{finished}");
        let items = if pull {
            server.request(
                6,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":main}}),
            )["items"]
                .clone()
        } else {
            server.until(|message| {
                message["method"] == "textDocument/publishDiagnostics"
                    && message["params"]["uri"] == main.as_str()
                    && message["params"]["version"] == 3
                    && message["params"]["diagnostics"] == json!([])
            })["params"]["diagnostics"]
                .clone()
        };
        assert_eq!(items, json!([]));
        server.request(7, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn minted_environment_boundaries_refresh_diagnostics_and_linked_names_over_stdio() {
    use latex_lsp::text::Text;
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let main = Url::from_file_path(root.join("main.tex")).unwrap();
    let source = concat!(
        "% 😀\r\n\\label{kept}\r\n",
        "\\begin{minted}[label={\\detokenize{\\end{minted}}}]\r\n{tex}\r\n",
        "\\end{other}\\end{minted}\\label{falseend}\r\n",
        "\\input{fake}\\label{kept}\r\n",
        "\\end{minted}\\label{discarded}\r\n",
        "\\ref{kept}\r\n",
    );
    std::fs::write(root.join("main.tex"), source).unwrap();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{"textDocument":{"diagnostic":{}},"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":7,"text":source}}),
    );
    let diagnostics = server.request(
        2,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(diagnostics["items"], json!([]), "{diagnostics}");
    let text = Text::new(source.into());
    let position = text.position(source.rfind("kept").unwrap());
    let edit = server.request(
        3,
        "textDocument/rename",
        json!({"textDocument":{"uri":main},"position":position,"newName":"changed"}),
    );
    assert_eq!(edit["documentChanges"][0]["textDocument"]["version"], 7);
    assert_eq!(
        edit["documentChanges"][0]["edits"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    let close = source.rfind("\\end{minted}").unwrap();
    let begin = source.find("\\begin{minted}").unwrap();
    let linked = server.request(
        4,
        "textDocument/linkedEditingRange",
        json!({"textDocument":{"uri":main},"position":text.position(close+6)}),
    );
    assert_eq!(
        linked["ranges"],
        json!([
            text.range(begin + 7, begin + 13),
            text.range(close + 5, close + 11)
        ])
    );
    assert_eq!(
        server.request(
            5,
            "textDocument/documentLink",
            json!({"textDocument":{"uri":main}})
        ),
        json!([])
    );
    let range = text.range(close + 5, close + 11);
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":8},"contentChanges":[{"range":range,"text":"other"}]}));
    let diagnostics = server.request(
        6,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":main}}),
    );
    let items = diagnostics["items"].as_array().unwrap();
    assert_eq!(items.len(), 1, "{diagnostics}");
    assert_eq!(items[0]["message"], "Unclosed environment `minted`");
    let broken = text
        .changed(vec![tower_lsp::lsp_types::TextDocumentContentChangeEvent {
            range: Some(range),
            range_length: None,
            text: "other".into(),
        }])
        .unwrap();
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":9},"contentChanges":[{"range":broken.range(close+5,close+10),"text":"minted"}]}));
    let diagnostics = server.request(
        7,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(diagnostics["items"], json!([]), "{diagnostics}");
    let symbols = server.request(
        8,
        "textDocument/documentSymbol",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(symbols.as_array().unwrap().len(), 1, "{symbols}");
    assert_eq!(symbols[0]["name"], "kept");
    let references = server.request(9, "textDocument/references", json!({"textDocument":{"uri":main},"position":position,"context":{"includeDeclaration":true}}));
    assert_eq!(references.as_array().unwrap().len(), 2, "{references}");
    server.request(10, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn listings_inline_literal_boundaries_follow_incremental_edits_over_stdio() {
    use latex_lsp::text::Text;
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let main = Url::from_file_path(root.join("main.tex")).unwrap();
    let initial="% 😀\r\n\\label{kept}\r\n\\lstinline*\\label{kept}\\input{fake}* \\ref{kept}\r\n\\ref{kept}\r\n";
    std::fs::write(root.join("main.tex"), initial).unwrap();
    let mut server = Server::start();
    server.request(1,"initialize",json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{"textDocument":{"diagnostic":{}},"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":7,"text":initial}}),
    );
    let mut source = initial.to_owned();
    for (stage, literal) in [
        None,
        Some("\\lstinline{\\label kept {\\input fake} "),
        Some("\\lstinline[title=[literal]% continue\r\n|\\label{kept}\\input{fake}| "),
        Some("\\lstinline|\\label{kept}\\input{fake} }%"),
        Some("\\lstinline*\\label{kept}\\input{fake}* "),
        Some("\\textbf{\\lstinline{a{\\label{kept}\\input{fake}}b}} "),
        Some("\\textbf{\\lstinline|a% ignored |\r\n\\label{kept}\\input{fake}|} "),
        Some("\\lstinline{\\label kept {\\input fake} "),
        Some("\\let\\strong\\textbf\\strong{\\lstinline{a{\\label{kept}\\input{fake}}b}} "),
        Some("\\let\\strong\\relax\\strong{\\lstinline{\\label kept {\\input fake}} "),
        Some("\\lstinline*\\label{kept}\\input{fake}* "),
        Some("\\textbf{\\lstinline{a{\\label{kept}\\input{fake}}b} "),
        Some("\\textbf{\\lstinline{a{\\label{kept}\\input{fake}}b}} "),
        Some("\\let\\code\\lstinline\\code|\\label{kept}\\input{fake}| "),
        Some("\\newcommand{\\code}{\\lstinline}\\code|\\label{kept}\\input{fake}| "),
        Some("\\lstinline*\\label{kept}\\input{fake}* "),
    ]
    .into_iter()
    .enumerate()
    {
        let start = source.find("\\label{kept}\r\n").unwrap() + "\\label{kept}\r\n".len();
        if let Some(literal) = literal {
            let end = source.find("\\ref{kept}").unwrap();
            let text = Text::new(source.clone());
            let range = text.range(start, end);
            server.notify("textDocument/didChange",json!({"textDocument":{"uri":main,"version":7+stage},"contentChanges":[{"range":range,"text":literal}]}));
            source.replace_range(start..end, literal);
        }
        let text = Text::new(source.clone());
        let id = 10 + stage as u64 * 10;
        let diagnostics = server.request(
            id,
            "textDocument/diagnostic",
            json!({"textDocument":{"uri":main}}),
        );
        if stage == 11 {
            assert_eq!(
                diagnostics["items"].as_array().unwrap().len(),
                1,
                "{source}: {diagnostics}"
            );
            assert_eq!(diagnostics["items"][0]["message"], "Unclosed brace");
        } else {
            assert_eq!(diagnostics["items"], json!([]), "{source}: {diagnostics}");
        }
        let symbols = server.request(
            id + 1,
            "textDocument/documentSymbol",
            json!({"textDocument":{"uri":main}}),
        );
        let symbol_count = if matches!(stage, 8 | 9 | 13 | 14) {
            2
        } else {
            1
        };
        assert_eq!(
            symbols.as_array().unwrap().len(),
            symbol_count,
            "{source}: {symbols}"
        );
        let position = text.position(source.rfind("kept").unwrap());
        let references=server.request(id+2,"textDocument/references",json!({"textDocument":{"uri":main},"position":position,"context":{"includeDeclaration":true}}));
        let count = if stage == 3 { 2 } else { 3 };
        assert_eq!(
            references.as_array().unwrap().len(),
            count,
            "{source}: {references}"
        );
        let edit = server.request(
            id + 3,
            "textDocument/rename",
            json!({"textDocument":{"uri":main},"position":position,"newName":"changed"}),
        );
        assert_eq!(
            edit["documentChanges"][0]["textDocument"]["version"],
            7 + stage
        );
        let edits = edit["documentChanges"][0]["edits"].as_array().unwrap();
        assert_eq!(edits.len(), count);
        let body = start + source[start..].find("\\label").unwrap();
        let inside = text.position(body + 3);
        assert_eq!(
            server.request(
                id + 4,
                "textDocument/definition",
                json!({"textDocument":{"uri":main},"position":inside})
            ),
            json!([])
        );
        assert_eq!(
            server.request(
                id + 5,
                "textDocument/signatureHelp",
                json!({"textDocument":{"uri":main},"position":inside})
            ),
            Value::Null
        );
        assert_eq!(
            server.request(
                id + 6,
                "textDocument/documentLink",
                json!({"textDocument":{"uri":main}})
            ),
            json!([])
        );
    }
    server.request(100, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn listings_environment_header_boundaries_refresh_after_incremental_changes_over_stdio() {
    use latex_lsp::text::Text;
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let main = Url::from_file_path(root.join("main.tex")).unwrap();
    let source = "% 😀\r\n\\begin{lstlisting}[frame=single]\r\n\\label{kept}\\input{fake}\r\n\\end{other}\\end{lstlisting}\\label{kept}\\ref{kept}\r\n";
    std::fs::write(root.join("main.tex"), source).unwrap();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{"textDocument":{"diagnostic":{},"foldingRange":{"lineFoldingOnly":false}},"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":7,"text":source}}),
    );
    let text = Text::new(source.into());
    let start = source.find("[frame=single]").unwrap();
    let range = text.range(start, start + "[frame=single]".len());
    let header = "[title={\\detokenize{\\end{lstlisting}}}] ignored \\end{lstlisting}";
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":8},"contentChanges":[{"range":range,"text":header}]}));
    let updated = text
        .changed(vec![tower_lsp::lsp_types::TextDocumentContentChangeEvent {
            range: Some(range),
            range_length: None,
            text: header.into(),
        }])
        .unwrap();
    let diagnostics = server.request(
        2,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(diagnostics["items"], json!([]), "{diagnostics}");
    let source = &updated.source;
    let close = source.rfind("\\end{lstlisting}").unwrap();
    let open = source.find("lstlisting").unwrap();
    let linked = server.request(
        3,
        "textDocument/linkedEditingRange",
        json!({"textDocument":{"uri":main},"position":updated.position(open+1)}),
    );
    assert_eq!(
        linked["ranges"],
        json!([
            updated.range(open, open + 10),
            updated.range(close + 5, close + 15)
        ])
    );
    let fake = source.find("\\end{lstlisting}").unwrap();
    assert_eq!(
        server.request(
            4,
            "textDocument/linkedEditingRange",
            json!({"textDocument":{"uri":main},"position":updated.position(fake+6)})
        ),
        Value::Null
    );
    let folds = server.request(
        5,
        "textDocument/foldingRange",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(folds.as_array().unwrap().len(), 1);
    assert_eq!(folds[0]["endLine"], 3);
    assert_eq!(
        folds[0]["endCharacter"],
        updated
            .position(close + "\\end{lstlisting}".len())
            .character
    );
    let position = updated.position(source.rfind("kept").unwrap());
    let edit = server.request(
        6,
        "textDocument/rename",
        json!({"textDocument":{"uri":main},"position":position,"newName":"changed"}),
    );
    assert_eq!(edit["documentChanges"][0]["textDocument"]["version"], 8);
    assert_eq!(
        edit["documentChanges"][0]["edits"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    assert_eq!(
        server.request(
            7,
            "textDocument/documentLink",
            json!({"textDocument":{"uri":main}})
        ),
        json!([])
    );
    let range = updated.range(close + 5, close + 15);
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":9},"contentChanges":[{"range":range,"text":"other"}]}));
    let broken = updated
        .clone()
        .changed(vec![tower_lsp::lsp_types::TextDocumentContentChangeEvent {
            range: Some(range),
            range_length: None,
            text: "other".into(),
        }])
        .unwrap();
    let diagnostics = server.request(
        8,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":main}}),
    );
    let items = diagnostics["items"].as_array().unwrap();
    assert_eq!(items.len(), 1, "{diagnostics}");
    assert_eq!(items[0]["message"], "Unclosed environment `lstlisting`");
    assert_eq!(
        server.request(
            9,
            "textDocument/documentSymbol",
            json!({"textDocument":{"uri":main}})
        ),
        json!([])
    );
    server.notify("textDocument/didChange",json!({"textDocument":{"uri":main,"version":10},"contentChanges":[{"range":broken.range(close+5,close+10),"text":"lstlisting"}]}));
    let diagnostics = server.request(
        10,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(diagnostics["items"], json!([]));
    let symbols = server.request(
        11,
        "textDocument/documentSymbol",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(symbols.as_array().unwrap().len(), 1);
    assert_eq!(symbols[0]["name"], "kept");
    let references=server.request(12,"textDocument/references",json!({"textDocument":{"uri":main},"position":position,"context":{"includeDeclaration":true}}));
    assert_eq!(references.as_array().unwrap().len(), 2);
    server.request(13, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn listings_environment_option_signatures_follow_incremental_edits_and_project_overrides() {
    use latex_lsp::text::Text;
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let main = Url::from_file_path(root.join("main.tex")).unwrap();
    let settings = Url::from_file_path(root.join("settings.sty")).unwrap();
    let initial = "% 😀\r\n\\documentclass{article}\\usepackage{settings}\r\n\\begin{lstlisting}[title={A]B},frame=sin";
    std::fs::write(root.join("main.tex"), initial).unwrap();
    std::fs::write(root.join("settings.sty"), "").unwrap();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":7,"text":initial}}),
    );
    let text = Text::new(initial.into());
    let help = server.request(
        2,
        "textDocument/signatureHelp",
        json!({"textDocument":{"uri":main},"position":text.position(initial.len())}),
    );
    assert_eq!(
        help["signatures"][0]["label"],
        r"\begin{lstlisting}[options]"
    );
    assert_eq!(help["activeParameter"], 1);
    server.notify("textDocument/didChange",json!({"textDocument":{"uri":main,"version":8},"contentChanges":[{"range":text.range(initial.len(),initial.len()),"text":"gle]"}]}));
    let partial = format!("{initial}gle]");
    let text = Text::new(partial.clone());
    assert_eq!(
        server.request(
            3,
            "textDocument/signatureHelp",
            json!({"textDocument":{"uri":main},"position":text.position(partial.len())})
        ),
        Value::Null
    );
    let suffix = "\r\n\\frac{a}{b}\\input{fake}\r\n\\end{lstlisting}\\frac{c}{d}\r\n";
    server.notify("textDocument/didChange",json!({"textDocument":{"uri":main,"version":9},"contentChanges":[{"range":text.range(partial.len(),partial.len()),"text":suffix}]}));
    let complete = format!("{partial}{suffix}");
    let text = Text::new(complete.clone());
    assert_eq!(server.request(4,"textDocument/signatureHelp",json!({"textDocument":{"uri":main},"position":text.position(complete.find("{b}").unwrap()+2)})),Value::Null);
    let help=server.request(5,"textDocument/signatureHelp",json!({"textDocument":{"uri":main},"position":text.position(complete.find("{d}").unwrap()+2)}));
    assert_eq!(
        help["signatures"][0]["label"],
        r"\frac{numerator}{denominator}"
    );
    assert_eq!(help["activeParameter"], 1);
    let target = json!({"textDocument":{"uri":main},"position":text.position(complete.find("single").unwrap()+2)});
    assert_eq!(
        server.request(6, "textDocument/signatureHelp", target.clone())["activeParameter"],
        1
    );
    server.notify("textDocument/didOpen",json!({"textDocument":{"uri":settings,"languageId":"latex","version":1,"text":"\\renewenvironment{lstlisting}[1]{}{}"}}));
    assert_eq!(
        server.request(7, "textDocument/signatureHelp", target.clone()),
        Value::Null
    );
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":settings,"version":2},"contentChanges":[{"text":""}]}),
    );
    let help = server.request(8, "textDocument/signatureHelp", target);
    assert_eq!(
        help["signatures"][0]["label"],
        r"\begin{lstlisting}[options]"
    );
    assert_eq!(help["activeParameter"], 1);
    assert_eq!(
        server
            .request(
                9,
                "textDocument/documentLink",
                json!({"textDocument":{"uri":main}})
            )
            .as_array()
            .unwrap()
            .iter()
            .filter(|link| link["target"]
                .as_str()
                .is_some_and(|value| value.ends_with("/settings.sty")))
            .count(),
        1
    );
    server.request(10, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn fancyvrb_environment_header_signatures_follow_incremental_edits_over_stdio() {
    use latex_lsp::text::Text;
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let main = Url::from_file_path(root.join("main.tex")).unwrap();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{}}));
    server.notify("initialized", json!({}));
    for (index, environment) in [
        "Verbatim",
        "Verbatim*",
        "LVerbatim",
        "LVerbatim*",
        "BVerbatim",
        "BVerbatim*",
        "SaveVerbatim",
        "SaveVerbatim*",
        "VerbatimOut",
        "VerbatimOut*",
        "VerbatimWrite",
        "VerbatimBuffer",
        "VerbEnv",
    ]
    .into_iter()
    .enumerate()
    {
        let required = match environment.trim_end_matches('*') {
            "SaveVerbatim" => "{name}",
            "VerbatimOut" => "{file}",
            _ => "",
        };
        let label = format!("\\begin{{{environment}}}[options]{required}");
        let initial = format!("% 😀\r\n\\begin{{{environment}}}[label={{A]B}},frame=sin");
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":main,"languageId":"latex","version":1,"text":initial}}),
        );
        let mut source = initial.clone();
        let id = 10 + index as u64 * 10;
        let help = server.request(id, "textDocument/signatureHelp", json!({"textDocument":{"uri":main},"position":Text::new(source.clone()).position(source.len())}));
        assert_eq!(help["signatures"][0]["label"], label);
        assert_eq!(help["activeParameter"], 1);
        let suffix = if required.is_empty() {
            "gle]"
        } else {
            "gle]\r\n{😀na"
        };
        let text = Text::new(source.clone());
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"range":text.range(source.len(),source.len()),"text":suffix}]}));
        source.push_str(suffix);
        let help = server.request(id+1, "textDocument/signatureHelp", json!({"textDocument":{"uri":main},"position":Text::new(source.clone()).position(source.len())}));
        if required.is_empty() {
            assert_eq!(help, Value::Null);
        } else {
            assert_eq!(help["signatures"][0]["label"], label);
            assert_eq!(help["activeParameter"], 2);
        }
        let suffix = format!(
            "{}\r\n\\frac{{a}}{{b}}\\input{{fake}}\r\n\\end{{{environment}}}\\frac{{c}}{{d}}\r\n",
            if required.is_empty() { "" } else { "me}" }
        );
        let text = Text::new(source.clone());
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":3},"contentChanges":[{"range":text.range(source.len(),source.len()),"text":suffix}]}));
        source.push_str(&suffix);
        for (offset, needle) in [(2, "{b}"), (3, "{d}")] {
            let help = server.request(id+offset, "textDocument/signatureHelp", json!({"textDocument":{"uri":main},"position":Text::new(source.clone()).position(source.find(needle).unwrap()+2)}));
            assert_eq!(help, Value::Null);
        }
        assert_eq!(
            server.request(
                id + 4,
                "textDocument/documentLink",
                json!({"textDocument":{"uri":main}})
            ),
            json!([])
        );
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":main}}),
        );
    }
    server.request(200, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn minted_environment_header_signatures_follow_incremental_edits_over_stdio() {
    use latex_lsp::text::Text;
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let main = Url::from_file_path(root.join("main.tex")).unwrap();
    let initial = "% 😀\r\n\\begin{minted}[label={A]B},break";
    std::fs::write(root.join("main.tex"), initial).unwrap();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{"textDocument":{"diagnostic":{}},"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":7,"text":initial}}),
    );
    let initial_text = Text::new(initial.into());
    let at = initial_text.position(initial.len());
    let help = server.request(
        2,
        "textDocument/signatureHelp",
        json!({"textDocument":{"uri":main},"position":at}),
    );
    assert_eq!(
        help["signatures"][0]["label"],
        r"\begin{minted}[options]{language}"
    );
    assert_eq!(help["activeParameter"], 1);
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":8},"contentChanges":[{"range":initial_text.range(initial.len(),initial.len()),"text":"lines]\r\n{py"}]}));
    let partial = format!("{initial}lines]\r\n{{py");
    let partial_text = Text::new(partial.clone());
    let help = server.request(
        3,
        "textDocument/signatureHelp",
        json!({"textDocument":{"uri":main},"position":partial_text.position(partial.len())}),
    );
    assert_eq!(
        help["signatures"][0]["label"],
        r"\begin{minted}[options]{language}"
    );
    assert_eq!(help["activeParameter"], 2);
    let suffix = "thon}\r\n\\frac{a}{b}\\input{fake}\\label{kept}\r\n\\end{minted}\\frac{c}{d}\\label{kept}\r\n\\label{kept}\\ref{kept}\r\n";
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":9},"contentChanges":[{"range":partial_text.range(partial.len(),partial.len()),"text":suffix}]}));
    let complete = format!("{partial}{suffix}");
    let text = Text::new(complete.clone());
    for (id, needle) in [(4, "{b}"), (5, "{d}")] {
        assert_eq!(server.request(id, "textDocument/signatureHelp", json!({"textDocument":{"uri":main},"position":text.position(complete.find(needle).unwrap()+2)})), Value::Null);
    }
    let help = server.request(6, "textDocument/signatureHelp", json!({"textDocument":{"uri":main},"position":text.position(complete.find("python").unwrap()+2)}));
    assert_eq!(help["activeParameter"], 2);
    let diagnostics = server.request(
        7,
        "textDocument/diagnostic",
        json!({"textDocument":{"uri":main}}),
    );
    assert_eq!(diagnostics["items"], json!([]), "{diagnostics}");
    let edit = server.request(8, "textDocument/rename", json!({"textDocument":{"uri":main},"position":text.position(complete.rfind("kept").unwrap()),"newName":"changed"}));
    assert_eq!(edit["documentChanges"][0]["textDocument"]["version"], 9);
    assert_eq!(
        edit["documentChanges"][0]["edits"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    assert_eq!(
        server.request(
            9,
            "textDocument/documentLink",
            json!({"textDocument":{"uri":main}})
        ),
        json!([])
    );
    server.request(10, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn bibliography_string_warnings_offer_versioned_and_legacy_repairs_over_stdio() {
    for (pull, legacy) in [(false, false), (true, false), (true, true)] {
        let script = r#"cp "${2%/*}/fixture.blg" "$1/main.blg"
printf '%%PDF-1.4\n' > "$1/main.pdf"
printf '(./main.tex)\n' > "$1/main.log"
printf 'PWD %s\nINPUT %s\n' "$PWD" "$2" > "$1/main.fls"
"#;
        let mut capabilities = json!({"workspace":{"workspaceEdit":{"documentChanges":true}}});
        if pull {
            capabilities["textDocument"]["diagnostic"] = json!({});
        }
        if legacy {
            capabilities["workspace"]["applyEdit"] = json!(true);
        } else {
            capabilities["textDocument"]["codeAction"] =
                json!({"codeActionLiteralSupport":{"codeActionKind":{"valueSet":["quickfix"]}}});
        }
        let (mut server, directory, main) =
            fake_build_server_capabilities(script, false, capabilities);
        let root = directory.path();
        let defs = Url::from_file_path(root.join("defs.bib")).unwrap();
        let refs = Url::from_file_path(root.join("refs.bib")).unwrap();
        let definitions = "@string{Journal={Expected}}\r\n";
        let source = "@misc{entry,title={😀} # JoUrAnL}\r\n";
        let main_source = "\\documentclass{article}\n\\bibliography{defs,refs}\n";
        for (uri, text) in [(&main, main_source), (&defs, definitions), (&refs, source)] {
            std::fs::write(uri.to_file_path().unwrap(), text).unwrap();
        }
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":main_source}]}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":refs,"languageId":"bibtex","version":7,"text":source}}),
        );
        let metadata =
            "The style file: plain.bst\nDatabase file #1: defs.bib\nDatabase file #2: refs.bib\n";
        std::fs::write(root.join("fixture.blg"), format!("{metadata}Warning--string name \"jouranl\" is undefined\n--line 1 of file refs.bib\n")).unwrap();
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["status"], "success", "{finished}");
        assert_eq!(finished["params"]["stale"], false, "{finished}");
        let items = if pull {
            server.request(
                3,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":refs}}),
            )["items"]
                .clone()
        } else {
            server.until(|message| {
                message["method"] == "textDocument/publishDiagnostics"
                    && message["params"]["uri"] == refs.as_str()
                    && message["params"]["diagnostics"]
                        .as_array()
                        .is_some_and(|items| {
                            items
                                .iter()
                                .any(|item| item["code"] == "undefined-bibliography-string")
                        })
            })["params"]["diagnostics"]
                .clone()
        };
        let diagnostic = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["code"] == "undefined-bibliography-string")
            .unwrap();
        let start = source.find("JoUrAnL").unwrap();
        assert_eq!(
            diagnostic["range"],
            json!(latex_lsp::text::Text::new(source.into()).range(start, start + 7))
        );
        assert_eq!(diagnostic["severity"], 2);
        let params = json!({"textDocument":{"uri":refs},"range":diagnostic["range"],"context":{"diagnostics":[diagnostic],"only":["quickfix"]}});
        let available = server.request(4, "textDocument/codeAction", params.clone());
        assert_eq!(available.as_array().unwrap().len(), 1, "{available}");
        assert_eq!(
            available[0]["title"],
            "Replace with bibliography abbreviation `Journal`"
        );
        // A TeX-side input change also invalidates the compilation context.
        std::fs::write(
            main.to_file_path().unwrap(),
            format!("{main_source}% changed"),
        )
        .unwrap();
        assert_eq!(
            server.request(13, "textDocument/codeAction", params.clone()),
            json!([])
        );
        std::fs::write(main.to_file_path().unwrap(), main_source).unwrap();
        // No notification: a disk edit must still invalidate the source proof.
        std::fs::write(
            defs.to_file_path().unwrap(),
            definitions.replace("Expected", "Changed"),
        )
        .unwrap();
        assert_eq!(
            server.request(5, "textDocument/codeAction", params.clone()),
            json!([])
        );
        if legacy {
            server.send(json!({"jsonrpc":"2.0","id":6,"method":"workspace/executeCommand","params":{"command":available[0]["command"],"arguments":available[0]["arguments"]}}));
            let response = server.until(|message| message["id"] == 6);
            assert_eq!(response["error"]["code"], -32602, "{response}");
        }
        std::fs::write(defs.to_file_path().unwrap(), definitions).unwrap();
        let edit = if legacy {
            server.send(json!({"jsonrpc":"2.0","id":7,"method":"workspace/executeCommand","params":{"command":available[0]["command"],"arguments":available[0]["arguments"]}}));
            let apply = server.until(|message| message["method"] == "workspace/applyEdit");
            let edit = apply["params"]["edit"].clone();
            server.send(json!({"jsonrpc":"2.0","id":apply["id"],"result":{"applied":true}}));
            assert_eq!(
                server.until(|message| message["id"] == 7)["result"]["applied"],
                true
            );
            edit
        } else {
            available[0]["edit"].clone()
        };
        assert_eq!(
            edit["documentChanges"][0]["textDocument"],
            json!({"uri":refs,"version":7})
        );
        assert_eq!(
            edit["documentChanges"][0]["edits"],
            json!([{"range":diagnostic["range"],"newText":"Journal"}])
        );
        let corrected = source.replace("JoUrAnL", "Journal");
        std::fs::write(refs.to_file_path().unwrap(), &corrected).unwrap();
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":refs,"version":8},"contentChanges":[{"range":diagnostic["range"],"text":"Journal"}]}));
        assert_eq!(
            server.request(8, "textDocument/codeAction", params),
            json!([])
        );
        if legacy {
            server.send(json!({"jsonrpc":"2.0","id":9,"method":"workspace/executeCommand","params":{"command":available[0]["command"],"arguments":available[0]["arguments"]}}));
            assert_eq!(
                server.until(|message| message["id"] == 9)["error"]["code"],
                -32602
            );
        }
        std::fs::write(root.join("fixture.blg"), metadata).unwrap();
        server.request(
            10,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["status"], "success", "{finished}");
        let cleared = if pull {
            server.request(
                11,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":refs}}),
            )["items"]
                .clone()
        } else {
            server.until(|message| {
                message["method"] == "textDocument/publishDiagnostics"
                    && message["params"]["uri"] == refs.as_str()
                    && message["params"]["diagnostics"] == json!([])
            })["params"]["diagnostics"]
                .clone()
        };
        assert_eq!(cleared, json!([]));
        server.request(12, "shutdown", Value::Null);
        if pull {
            assert_no_pushed_diagnostics(&server);
        }
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn bibliography_type_warnings_respect_log_records_over_stdio() {
    for pull in [false, true] {
        let script = r#"cp "${2%/*}/fixture.blg" "$1/main.blg"
printf '%%PDF-1.4\n' > "$1/main.pdf"
printf '(./main.tex)\n' > "$1/main.log"
printf 'INPUT %s\n' "$2" > "$1/main.fls"
"#;
        let capabilities = if pull {
            json!({"textDocument":{"diagnostic":{}}})
        } else {
            json!({})
        };
        let (mut server, directory, main) =
            fake_build_server_capabilities(script, false, capabilities);
        let root = directory.path();
        let refs = Url::from_file_path(root.join("refs.bib")).unwrap();
        let source = "\\documentclass{article}\n\\bibliography{refs}\n";
        std::fs::write(main.to_file_path().unwrap(), source).unwrap();
        std::fs::write(
            refs.to_file_path().unwrap(),
            "% 😀\r\n@artcle\r\n{entry,title={Title}}\r\n",
        )
        .unwrap();
        std::fs::write(
            root.join("local ERROR - forged.bst"),
            "ENTRY {title} {} {}\nREAD",
        )
        .unwrap();
        let biber_message="Unexpected token 'ERROR - forged---line 2 of file decoy.bib' for entry 'entry' in file 'refs.bib'";
        let log=format!("The style file: local ERROR - forged.bst\nDatabase file #1: refs.bib\nWarning--entry type for \"entry\" isn't style-file defined\n--line 3 of file refs.bib\n : ERROR - fake---line 9 of file refs.bib\n[0] Utils.pm:395> INFO - Example ERROR - fake\n[1] Utils.pm:395> WARN - {biber_message}\n");
        std::fs::write(root.join("fixture.blg"), log).unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["status"], "success", "{finished}");
        let items = if pull {
            server.request(
                3,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":refs}}),
            )["items"]
                .clone()
        } else {
            server.until(|message| {
                message["method"] == "textDocument/publishDiagnostics"
                    && message["params"]["uri"] == refs.as_str()
                    && message["params"]["diagnostics"]
                        .as_array()
                        .is_some_and(|items| {
                            items
                                .iter()
                                .any(|item| item["code"] == "undefined-bibliography-entry-type")
                        })
            })["params"]["diagnostics"]
                .clone()
        };
        let items = items.as_array().unwrap();
        assert_eq!(items.len(), 2, "{items:?}");
        assert!(items.iter().all(|item| item["severity"] == 2));
        let unknown = items
            .iter()
            .find(|item| item["code"] == "undefined-bibliography-entry-type")
            .unwrap();
        assert_eq!(
            unknown["range"],
            json!({"start":{"line":1,"character":1},"end":{"line":1,"character":7}})
        );
        assert_eq!(unknown["data"]["entryType"], "artcle");
        let biber = items
            .iter()
            .find(|item| item["message"] == format!("Biber: {biber_message}"))
            .unwrap();
        assert_eq!(
            biber["range"],
            json!({"start":{"line":2,"character":1},"end":{"line":2,"character":6}})
        );
        server.request(4, "shutdown", Value::Null);
        if pull {
            assert_no_pushed_diagnostics(&server);
        }
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn bibliography_crossref_errors_publish_operands_related_parents_and_clear_after_rebuild() {
    for pull in [false, true] {
        let script = r#"cp "${2%/*}/fixture.blg" "$1/main.blg"
printf 'INPUT %s\n' "$2" > "$1/main.fls"
exit 1
"#;
        let capabilities = if pull {
            json!({"textDocument":{"diagnostic":{}}})
        } else {
            json!({})
        };
        let (mut server, directory, main) =
            fake_build_server_capabilities(script, false, capabilities);
        let root = directory.path();
        let defs = Url::from_file_path(root.join("defs.bib")).unwrap();
        let refs = Url::from_file_path(root.join("refs.bib")).unwrap();
        let source = "\\documentclass{article}\n\\bibliography{defs,refs}\n";
        std::fs::write(main.to_file_path().unwrap(), source).unwrap();
        std::fs::write(
            defs.to_file_path().unwrap(),
            "@proceedings{parent,title={Parent}}\r\n",
        )
        .unwrap();
        std::fs::write(
            refs.to_file_path().unwrap(),
            "% 😀\r\n@misc{child,title={😀},crossref={parent}}\r\n",
        )
        .unwrap();
        std::fs::write(root.join("fixture.blg"), "Database file #1: defs.bib\nDatabase file #2: refs.bib\nA bad cross reference---entry \"child\"\nrefers to entry \"parent\", which doesn't exist\n").unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["status"], "error", "{finished}");
        let items = if pull {
            server.request(
                3,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":refs}}),
            )["items"]
                .clone()
        } else {
            server.until(|message| {
                message["method"] == "textDocument/publishDiagnostics"
                    && message["params"]["uri"] == refs.as_str()
                    && message["params"]["diagnostics"]
                        .as_array()
                        .is_some_and(|items| {
                            items
                                .iter()
                                .any(|item| item["code"] == "bad-bibliography-crossref")
                        })
            })["params"]["diagnostics"]
                .clone()
        };
        let items = items.as_array().unwrap();
        assert_eq!(items.len(), 1, "{items:?}");
        let item = &items[0];
        assert_eq!(item["severity"], 1);
        assert_eq!(item["code"], "bad-bibliography-crossref");
        assert_eq!(
            item["range"],
            json!({"start":{"line":1,"character":33},"end":{"line":1,"character":39}})
        );
        assert_eq!(item["data"]["key"], "child");
        assert_eq!(item["data"]["parent"], "parent");
        assert_eq!(item["relatedInformation"].as_array().unwrap().len(), 1);
        assert_eq!(
            item["relatedInformation"][0]["location"],
            json!({"uri":defs,"range":{"start":{"line":0,"character":13},"end":{"line":0,"character":19}}})
        );
        assert!(item["relatedInformation"][0]["message"]
            .as_str()
            .unwrap()
            .contains("can skip an uncited parent"));
        std::fs::write(
            root.join("fixture.blg"),
            "Database file #1: defs.bib\nDatabase file #2: refs.bib\n",
        )
        .unwrap();
        server.request(
            4,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        server.until(|message| message["method"] == "latex/buildFinished");
        let cleared = if pull {
            server.request(
                5,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":refs}}),
            )["items"]
                .clone()
        } else {
            server.until(|message| {
                message["method"] == "textDocument/publishDiagnostics"
                    && message["params"]["uri"] == refs.as_str()
                    && message["params"]["diagnostics"] == json!([])
            })["params"]["diagnostics"]
                .clone()
        };
        assert_eq!(cleared, json!([]));
        server.request(6, "shutdown", Value::Null);
        if pull {
            assert_no_pushed_diagnostics(&server);
        }
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn bibliography_nested_crossrefs_preserve_warning_and_error_severity_and_clear_over_stdio() {
    for pull in [false, true] {
        let script = r#"cp "${2%/*}/fixture.blg" "$1/main.blg"
printf '%%PDF-1.4\n' > "$1/main.pdf"
printf '(./main.tex)\n' > "$1/main.log"
printf 'INPUT %s\n' "$2" > "$1/main.fls"
if [ -f "${2%/*}/fail" ]; then exit 1; fi
"#;
        let capabilities = if pull {
            json!({"textDocument":{"diagnostic":{}}})
        } else {
            json!({})
        };
        let (mut server, directory, main) =
            fake_build_server_capabilities(script, false, capabilities);
        let root = directory.path();
        let refs = Url::from_file_path(root.join("refs.bib")).unwrap();
        let main_source = "\\documentclass{article}\n\\bibliography{defs,refs}\n\\nocite{*}\n";
        let source = "% 😀\r\n@misc{child,title={😀},crossref={parent}}\r\n@misc{parent,crossref={grandparent}}\r\n";
        std::fs::write(main.to_file_path().unwrap(), main_source).unwrap();
        std::fs::write(refs.to_file_path().unwrap(), source).unwrap();
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":main_source}]}));
        let fetch = |server: &mut Server, id: u64, expected: &str| {
            if pull {
                server.request(
                    id,
                    "textDocument/diagnostic",
                    json!({"textDocument":{"uri":refs}}),
                )["items"]
                    .clone()
            } else {
                server.until(|message| {
                    message["method"] == "textDocument/publishDiagnostics"
                        && message["params"]["uri"] == refs.as_str()
                        && if expected.is_empty() {
                            message["params"]["diagnostics"] == json!([])
                        } else {
                            message["params"]["diagnostics"]
                                .as_array()
                                .is_some_and(|items| {
                                    items.iter().any(|item| item["code"] == expected)
                                })
                        }
                })["params"]["diagnostics"]
                    .clone()
            }
        };
        for stage in 0..3 {
            let history = "Database file #1: defs.bib\nDatabase file #2: refs.bib\n";
            let nested = "Warning--you've nested cross references--entry \"child\"\nrefers to entry \"parent\", which also refers to something\n";
            let missing = "A bad cross reference---entry \"parent\"\nrefers to entry \"grandparent\", which doesn't exist\n";
            let (log, expected) = match stage {
                0 => (format!("{history}{nested}"), "nested-bibliography-crossref"),
                1 => (
                    format!("{history}{nested}{missing}"),
                    "bad-bibliography-crossref",
                ),
                _ => (history.to_owned(), ""),
            };
            if stage == 1 {
                std::fs::write(root.join("fail"), "").unwrap();
                std::fs::write(root.join("defs.bib"), "% ancestor removed\n").unwrap();
            } else {
                std::fs::write(root.join("defs.bib"), "@misc{grandparent,title={Top}}\n").unwrap();
            }
            if stage == 2 {
                std::fs::remove_file(root.join("fail")).unwrap();
                std::fs::write(refs.to_file_path().unwrap(), "% 😀\r\n@misc{child,title={😀},crossref={parent}}\r\n@misc{parent,title={Parent}}\r\n").unwrap();
            }
            std::fs::write(root.join("fixture.blg"), log).unwrap();
            server.request(
                2 + stage * 2,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let finished = server.until(|message| message["method"] == "latex/buildFinished");
            assert_eq!(
                finished["params"]["status"],
                if stage == 1 { "error" } else { "success" },
                "{finished}"
            );
            let items = fetch(&mut server, 3 + stage * 2, expected);
            let items = items.as_array().unwrap();
            if stage == 2 {
                assert!(items.is_empty(), "{items:?}");
                continue;
            }
            assert_eq!(items.len(), if stage == 0 { 1 } else { 2 }, "{items:?}");
            let nested = items
                .iter()
                .find(|item| item["code"] == "nested-bibliography-crossref")
                .unwrap();
            assert_eq!(nested["severity"], 2);
            assert_eq!(
                nested["range"],
                json!({"start":{"line":1,"character":33},"end":{"line":1,"character":39}})
            );
            assert!(nested["message"]
                .as_str()
                .unwrap()
                .ends_with("which also refers to something"));
            assert_eq!(nested["relatedInformation"].as_array().unwrap().len(), 1);
            assert_eq!(
                nested["relatedInformation"][0]["location"],
                json!({"uri":refs,"range":{"start":{"line":2,"character":6},"end":{"line":2,"character":12}}})
            );
            assert!(nested["relatedInformation"][0]["message"]
                .as_str()
                .unwrap()
                .contains("nested crossref chain"));
            if stage == 1 {
                let missing = items
                    .iter()
                    .find(|item| item["code"] == "bad-bibliography-crossref")
                    .unwrap();
                assert_eq!(missing["severity"], 1);
                assert_eq!(
                    missing["range"],
                    json!({"start":{"line":2,"character":23},"end":{"line":2,"character":34}})
                );
            }
        }
        server.request(8, "shutdown", Value::Null);
        if pull {
            assert_no_pushed_diagnostics(&server);
        }
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn repeated_bibliography_entries_publish_exact_ranges_and_related_definitions() {
    for pull in [false, true] {
        let script = r#"cp "${2%/*}/fixture.blg" "$1/main.blg"
printf 'INPUT %s\n' "$2" > "$1/main.fls"
exit 1
"#;
        let capabilities = if pull {
            json!({"textDocument":{"diagnostic":{}}})
        } else {
            json!({})
        };
        let (mut server, directory, main) =
            fake_build_server_capabilities(script, false, capabilities);
        let root = directory.path();
        let defs = Url::from_file_path(root.join("defs.bib")).unwrap();
        let refs = Url::from_file_path(root.join("refs.bib")).unwrap();
        let source = "\\documentclass{article}\n\\bibliography{defs,refs}\n";
        std::fs::write(main.to_file_path().unwrap(), source).unwrap();
        std::fs::write(
            defs.to_file_path().unwrap(),
            "@misc{entry,title={First}}\r\n",
        )
        .unwrap();
        std::fs::write(
            refs.to_file_path().unwrap(),
            "% 😀\r\n@misc\r\n{Entry\r\n,title={Second}}\r\n",
        )
        .unwrap();
        std::fs::write(root.join("fixture.blg"), "Database file #1: defs.bib\nDatabase file #2: refs.bib\nRepeated entry---line 3 of file refs.bib\n").unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["status"], "error", "{finished}");
        let items = if pull {
            server.request(
                3,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":refs}}),
            )["items"]
                .clone()
        } else {
            server.until(|message| {
                message["method"] == "textDocument/publishDiagnostics"
                    && message["params"]["uri"] == refs.as_str()
                    && message["params"]["diagnostics"]
                        .as_array()
                        .is_some_and(|items| {
                            items
                                .iter()
                                .any(|item| item["code"] == "repeated-bibliography-entry")
                        })
            })["params"]["diagnostics"]
                .clone()
        };
        let diagnostic = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["code"] == "repeated-bibliography-entry")
            .unwrap();
        assert_eq!(diagnostic["severity"], 1);
        assert_eq!(
            diagnostic["range"],
            json!({"start":{"line":2,"character":1},"end":{"line":2,"character":6}})
        );
        assert_eq!(diagnostic["data"]["key"], "Entry");
        assert_eq!(
            diagnostic["relatedInformation"].as_array().unwrap().len(),
            1
        );
        assert_eq!(
            diagnostic["relatedInformation"][0]["location"],
            json!({"uri":defs,"range":{"start":{"line":0,"character":6},"end":{"line":0,"character":11}}})
        );
        server.request(4, "shutdown", Value::Null);
        if pull {
            assert_no_pushed_diagnostics(&server);
        }
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn generic_bibliography_entry_warnings_refresh_ambiguity_and_key_ranges_after_saved_edits() {
    for pull in [false, true] {
        let script = r#"cp "${2%/*}/fixture.blg" "$1/main.blg"
printf '%%PDF-1.4\n' > "$1/main.pdf"
printf '(./main.tex)\n' > "$1/main.log"
printf 'PWD %s\nINPUT %s\nINPUT %s\n' "$PWD" "$2" "${2%/*}/refs.bib" > "$1/main.fls"
"#;
        let capabilities = if pull {
            json!({"textDocument":{"diagnostic":{}}})
        } else {
            json!({})
        };
        let (mut server, directory, main) =
            fake_build_server_capabilities(script, false, capabilities);
        let root = directory.path();
        let refs = Url::from_file_path(root.join("refs.bib")).unwrap();
        let main_source = "\\documentclass{article}\n\\bibliography{refs}\n";
        std::fs::write(main.to_file_path().unwrap(), main_source).unwrap();
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":main_source}]}));
        let sources = [
            "% 😀\r\n@book{中😀,title={First}}\r\n",
            "% 😀\r\n@book{中😀,title={First}}\r\n@book{中😀,title={Second}}\r\n",
            "% Moved 😀\r\n\r\n@book{中😀,title={First}}\r\n",
            "% Moved 😀\r\n\r\n@book{中😀,author={Example},title={First}}\r\n",
        ];
        let message = "BibTeX: empty author in 中😀";
        for (stage, source) in sources.into_iter().enumerate() {
            std::fs::write(refs.to_file_path().unwrap(), source).unwrap();
            if stage == 0 {
                server.notify("textDocument/didOpen", json!({"textDocument":{"uri":refs,"languageId":"bibtex","version":7,"text":source}}));
            } else {
                server.notify("textDocument/didChange", json!({"textDocument":{"uri":refs,"version":7+stage},"contentChanges":[{"text":source}]}));
                server.notify("textDocument/didSave", json!({"textDocument":{"uri":refs}}));
            }
            let log = if stage == 3 {
                "Database file #1: refs.bib\n"
            } else {
                "Database file #1: refs.bib\nWarning--empty author in 中😀\n"
            };
            std::fs::write(root.join("fixture.blg"), log).unwrap();
            server.request(
                2 + stage as u64 * 3,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let finished = server.until(|item| item["method"] == "latex/buildFinished");
            assert_eq!(finished["params"]["status"], "success", "{finished}");
            let target = if stage == 1 { &main } else { &refs };
            let items = if pull {
                server.request(
                    3 + stage as u64 * 3,
                    "textDocument/diagnostic",
                    json!({"textDocument":{"uri":target}}),
                )["items"]
                    .clone()
            } else {
                server.until(|item| {
                    item["method"] == "textDocument/publishDiagnostics"
                        && item["params"]["uri"] == target.as_str()
                        && item["params"]["diagnostics"]
                            .as_array()
                            .is_some_and(|items| {
                                if stage == 3 {
                                    items.is_empty()
                                } else {
                                    items.iter().any(|item| item["message"] == message)
                                }
                            })
                })["params"]["diagnostics"]
                    .clone()
            };
            if stage == 3 {
                assert!(items.as_array().unwrap().is_empty(), "{items}");
                continue;
            }
            let item = items
                .as_array()
                .unwrap()
                .iter()
                .find(|item| item["message"] == message)
                .unwrap();
            assert_eq!(item["severity"], 2);
            assert_eq!(item["source"], "latex-build");
            if stage == 1 {
                assert_eq!(item["range"]["start"], json!({"line":0,"character":0}));
            } else {
                let at = source.find("中😀").unwrap();
                let range = latex_lsp::text::Text::new(source.into()).range(at, at + "中😀".len());
                assert_eq!(item["range"], serde_json::to_value(range).unwrap());
            }
        }
        server.request(20, "shutdown", Value::Null);
        if pull {
            assert_no_pushed_diagnostics(&server);
        }
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

