#[test]
fn string_predicates_keep_literal_tokens_and_versioned_branch_renames_over_stdio() {
    let directory = tempfile::tempdir().unwrap();
    let root = Url::from_directory_path(directory.path()).unwrap();
    let main = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    let definitions = Url::from_file_path(directory.path().join("definitions.tex")).unwrap();
    let source = "\\documentclass{article}\\input{definitions}\r\n\\ifstrequal{\\ifbool{draft}}{X}{\\booltrue{draft}}{\\boolfalse{draft}}\r\n\\notblank{\\newbool{ghost}}{Yes}{No}\r\n";
    std::fs::write(main.to_file_path().unwrap(), source).unwrap();
    std::fs::write(
        definitions.to_file_path().unwrap(),
        "\\newbool{draft}\\newtoggle{draft}\n",
    )
    .unwrap();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":root,"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":9,"text":source}}),
    );
    server.until(|message| {
        message["method"] == "textDocument/publishDiagnostics"
            && message["params"]["uri"] == main.as_str()
    });
    let text = latex_lsp::text::Text::new(source.into());
    let literal = text.position(source.find("draft").unwrap() + 2);
    let literal_target = json!({"textDocument":{"uri":main},"position":literal});
    assert_eq!(
        server.request(2, "textDocument/definition", literal_target.clone()),
        json!([])
    );
    assert_eq!(
        server.request(3, "textDocument/prepareRename", literal_target.clone()),
        Value::Null
    );
    assert_eq!(
        server.request(4, "textDocument/completion", literal_target.clone()),
        json!([])
    );
    let help = server.request(5, "textDocument/signatureHelp", literal_target);
    assert_eq!(
        help["signatures"][0]["label"],
        r"\ifstrequal{string}{string}{then}{else}"
    );
    assert_eq!(help["activeParameter"], 0);
    assert_eq!(
        server.request(6, "workspace/symbol", json!({"query":"ghost"})),
        json!([])
    );
    let target = json!({"textDocument":{"uri":main},"position":text.position(source.find("\\booltrue{draft}").unwrap()+11)});
    let mut rename = target;
    rename["newName"] = json!("release");
    let edit = server.request(7, "textDocument/rename", rename);
    let documents = edit["documentChanges"].as_array().unwrap();
    assert_eq!(documents.len(), 2);
    for (uri, version, count) in [(&main, json!(9), 2), (&definitions, Value::Null, 1)] {
        let document = documents
            .iter()
            .find(|document| document["textDocument"]["uri"] == uri.as_str())
            .unwrap();
        assert_eq!(document["textDocument"]["version"], version);
        let edits = document["edits"].as_array().unwrap();
        assert_eq!(edits.len(), count);
        assert!(edits.iter().all(|edit| edit["newText"] == "release"));
        if uri == &main {
            let literal_end = source.find("}{X}").unwrap();
            assert!(edits.iter().all(
                |edit| serde_json::from_value::<tower_lsp::lsp_types::Range>(edit["range"].clone())
                    .unwrap()
                    .start
                    > text.position(literal_end)
            ));
        }
    }
    let changed = source.replace(r"\ifbool{draft}", r"\label{phantom}\input{ghost}");
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":main,"version":10},"contentChanges":[{"text":changed}]}),
    );
    server.until(|message| {
        message["method"] == "textDocument/publishDiagnostics"
            && message["params"]["uri"] == main.as_str()
            && message["params"]["version"] == 10
    });
    assert_eq!(
        server.request(8, "workspace/symbol", json!({"query":"phantom"})),
        json!([])
    );
    server.request(9, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn commented_expression_keywords_return_versioned_cross_file_renames_over_stdio() {
    let directory = tempfile::tempdir().unwrap();
    let root = Url::from_directory_path(directory.path()).unwrap();
    let main = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    let definitions = Url::from_file_path(directory.path().join("definitions.tex")).unwrap();
    let source = "\\documentclass{article}\\input{definitions}\r\n\\ifboolexpr{bo% boolean\r\n  ol{draft} and to% toggle\r\n gl{draft}}{Y}{N}\r\n";
    std::fs::write(main.to_file_path().unwrap(), source).unwrap();
    std::fs::write(
        definitions.to_file_path().unwrap(),
        "\\newbool{draft}\\newtoggle{draft}\n",
    )
    .unwrap();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":root,"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":9,"text":source}}),
    );
    server.until(|message| {
        message["method"] == "textDocument/publishDiagnostics"
            && message["params"]["uri"] == main.as_str()
    });
    for (line, character) in [(2, 5), (3, 4)] {
        let range = json!({"start":{"line":line,"character":character},"end":{"line":line,"character":character+5}});
        let target =
            json!({"textDocument":{"uri":main},"position":{"line":line,"character":character+1}});
        let prepared = server.request(2, "textDocument/prepareRename", target.clone());
        assert_eq!(prepared["placeholder"], "draft");
        assert_eq!(prepared["range"], range);
        let locations = server.request(3, "textDocument/definition", target.clone());
        assert_eq!(locations.as_array().unwrap().len(), 1);
        assert_eq!(locations[0]["uri"], definitions.as_str());
        let mut references = target.clone();
        references["context"] = json!({"includeDeclaration":true});
        assert_eq!(
            server
                .request(4, "textDocument/references", references)
                .as_array()
                .unwrap()
                .len(),
            2
        );
        let mut params = target;
        params["newName"] = json!("release");
        let edit = server.request(5, "textDocument/rename", params);
        let documents = edit["documentChanges"].as_array().unwrap();
        assert_eq!(documents.len(), 2);
        for (uri, version) in [(&main, json!(9)), (&definitions, Value::Null)] {
            let document = documents
                .iter()
                .find(|document| document["textDocument"]["uri"] == uri.as_str())
                .unwrap();
            assert_eq!(document["textDocument"]["version"], version);
            let edits = document["edits"].as_array().unwrap();
            assert_eq!(edits.len(), 1);
            assert_eq!(edits[0]["newText"], "release");
            if uri == &main {
                assert_eq!(edits[0]["range"], range);
            }
        }
    }
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn expression_fixes_recheck_cross_file_tests_without_a_main_version_change() {
    for literals in [false, true] {
        let capabilities = json!({
            "workspace":{"applyEdit":true,"workspaceEdit":{"documentChanges":true}},
            "textDocument": if literals {
                json!({"codeAction":{"codeActionLiteralSupport":{"codeActionKind":{"valueSet":["quickfix"]}}}})
            } else { json!({}) }
        });
        let (mut server, directory, main) = fake_build_server_capabilities(
            "cat \"${2%/*}/fixture.log\" > \"$1/main.log\"\nexit 1\n",
            false,
            capabilities,
        );
        let source = "\\documentclass{article}\n\\input{definitions}\n\\ifboolexpr{bool {darft} and test {\\ifstrequal{A}{A}}}\n";
        let definitions = Url::from_file_path(directory.path().join("definitions.tex")).unwrap();
        std::fs::write(main.to_file_path().unwrap(), source).unwrap();
        std::fs::write(definitions.to_file_path().unwrap(), "\\newbool{draft}\n").unwrap();
        std::fs::write(directory.path().join("fixture.log"), "(./main.tex\n(./definitions.tex)\n./main.tex:3: Package etoolbox Error: Invalid boolean expression.\n\nSee the etoolbox package documentation for explanation.\nType  H <return>  for immediate help.\n ...\n\nl.3 \\ifboolexpr{bool {darft} and test {\\ifstrequal{A}{A}}}\n    {Yes}{No}\nBoolean 'darft' undefined.\n\n)\n").unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":9},"contentChanges":[{"text":source}]}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["status"], "error", "{finished}");
        let published = server.until(|message| {
            message["method"] == "textDocument/publishDiagnostics"
                && message["params"]["uri"] == json!(main)
                && message["params"]["diagnostics"]
                    .as_array()
                    .is_some_and(|items| {
                        items.iter().any(|item| item["code"] == "undefined-boolean")
                    })
        });
        assert_eq!(published["params"]["version"], 9);
        let diagnostic = published["params"]["diagnostics"]
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["code"] == "undefined-boolean")
            .unwrap();
        assert_eq!(diagnostic["data"]["boolean"], "darft");
        assert_eq!(
            diagnostic["range"],
            json!({"start":{"line":2,"character":18},"end":{"line":2,"character":23}})
        );
        let params = json!({"textDocument":{"uri":main},"range":diagnostic["range"],"context":{"diagnostics":[diagnostic],"only":["quickfix"]}});
        let actions = server.request(3, "textDocument/codeAction", params.clone());
        assert_eq!(actions.as_array().unwrap().len(), 1, "{actions}");
        assert_eq!(actions[0]["title"], r"Replace with boolean `draft`");
        if literals {
            let edit = &actions[0]["edit"]["documentChanges"][0];
            assert_eq!(edit["textDocument"]["version"], 9);
            assert_eq!(edit["textDocument"]["uri"], json!(main));
            assert_eq!(edit["edits"][0]["newText"], "draft");
            assert_eq!(edit["edits"][0]["range"], diagnostic["range"]);
        }
        std::fs::write(
            definitions.to_file_path().unwrap(),
            "\\newbool{draft}\\renewcommand{\\ifstrequal}[2]{}\n",
        )
        .unwrap();
        server.notify(
            "workspace/didChangeWatchedFiles",
            json!({"changes":[{"uri":definitions,"type":2}]}),
        );
        assert_eq!(
            server.request(4, "textDocument/codeAction", params),
            json!([])
        );
        if !literals {
            server.send(json!({"jsonrpc":"2.0","id":5,"method":"workspace/executeCommand","params":{"command":actions[0]["command"],"arguments":actions[0]["arguments"]}}));
            let rejected = server.until(|message| message["id"] == 5);
            assert_eq!(rejected["error"]["code"], -32602, "{rejected}");
        }
        server.request(6, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

