#[test]
#[cfg(unix)]
fn oversized_float_analysis_uses_final_logs_classifies_child_warnings_and_clears() {
    let script = r#"cat <<'EARLY'
LaTeX Warning: Float too large for page by 999.0pt on input line 1.
EARLY
printf '%%PDF-1.4\n' > "$1/main.pdf"
cat "${2%/*}/fixture.log" > "$1/main.log"
"#;
    let (mut server, directory, main) = fake_build_server(script, false);
    let source = "\\documentclass{article}\n\\input{child}\n";
    std::fs::write(main.to_file_path().unwrap(), source).unwrap();
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
    );
    let child = Url::from_file_path(directory.path().join("child.tex")).unwrap();
    std::fs::write(child.to_file_path().unwrap(), "First\nSecond\nThird\n").unwrap();
    for (id, warnings, expected, count) in [
        (2, "LaTeX Warning: Float too large for page by 12.5pt on input line 2.\n\nLaTeX Warning: Float too large for page by 19.25pt on input line 3.\n",json!({"count":2,"maxExcessPt":"19.25"}),2),
        (5, "LaTeX Warning: Float too large for page by 12.5pt on input line 2.\n",json!({"count":1,"maxExcessPt":"12.5"}),1),
        (8, "",json!({"count":0,"maxExcessPt":null}),0),
    ] {
        std::fs::write(directory.path().join("fixture.log"),format!("(./main.tex\n(./child.tex\n{warnings}\n)\nOutput written on main.pdf (1 page).\n)\n")).unwrap();
        let started = server.request(id,"workspace/executeCommand",json!({"command":"latex.build","arguments":[main]}));
        let finished = server.until(|message|message["method"]=="latex/buildFinished"&&message["params"]["buildId"]==started["buildId"]);
        let result = &finished["params"];
        assert_eq!(result["status"],"success","{finished}");
        assert_eq!(result["warningsCount"],count);
        assert_eq!(result["errorsCount"],0);
        assert_eq!(result["analysis"]["oversizedFloats"],expected);
        assert_eq!(result["analysis"]["boxWarnings"],json!([]));
        assert_eq!(result["analysis"]["rerunRequired"],false);
        assert_eq!(result["analysis"]["truncated"],false);
        let published = server.until(|message|message["method"]=="textDocument/publishDiagnostics"&&message["params"]["uri"]==child.as_str()&&message["params"]["diagnostics"].as_array().is_some_and(|items|items.iter().filter(|item|item["code"]=="oversized-float").count()==count));
        for item in published["params"]["diagnostics"].as_array().unwrap().iter().filter(|item|item["code"]=="oversized-float") {
            assert_eq!(item["severity"],2);
            assert!(item["data"]["excessPt"].as_str().is_some());
        }
        let saved = server.request(id+1,"workspace/executeCommand",json!({"command":"latex.buildStatus","arguments":[main]}));
        assert_eq!(&saved,result);
        let pulled = server.request(id+2,"textDocument/diagnostic",json!({"textDocument":{"uri":child}}));
        assert_eq!(pulled["items"].as_array().unwrap().iter().filter(|item|item["code"]=="oversized-float").count(),count);
    }
    server.request(11, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn unchanged_pdf_older_than_an_included_source_is_rejected_but_fresh_noop_builds_succeed() {
    let (mut server, directory, uri) = fake_build_server("exit 0\n", false);
    let source = "\\documentclass{article}\n\\input{chapter}\n";
    std::fs::write(uri.to_file_path().unwrap(), source).unwrap();
    std::fs::write(directory.path().join("chapter.tex"), "Chapter\n").unwrap();
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"text":source}]}),
    );
    let output = directory.path().join("build/latex-lsp");
    std::fs::create_dir_all(&output).unwrap();
    let pdf = output.join("main.pdf");
    std::fs::write(&pdf, "%PDF-1.4\n").unwrap();
    let now = std::time::SystemTime::now();
    std::fs::File::open(uri.to_file_path().unwrap())
        .unwrap()
        .set_times(std::fs::FileTimes::new().set_modified(now - Duration::from_secs(120)))
        .unwrap();
    std::fs::File::open(&pdf)
        .unwrap()
        .set_times(std::fs::FileTimes::new().set_modified(now - Duration::from_secs(60)))
        .unwrap();
    server.request(
        2,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[uri]}),
    );
    let outdated = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(outdated["params"]["status"], "error", "{outdated}");
    assert_eq!(outdated["params"]["stale"], false);
    assert!(outdated["params"]["pdfUri"].is_null());
    assert!(outdated["params"]["message"]
        .as_str()
        .unwrap()
        .contains("chapter.tex"));
    let diagnostic = server.until(|message| {
        message["method"] == "textDocument/publishDiagnostics"
            && message["params"]["diagnostics"]
                .as_array()
                .is_some_and(|items| {
                    items.iter().any(|item| {
                        item["message"]
                            .as_str()
                            .is_some_and(|message| message.contains("outdated PDF"))
                    })
                })
    });
    assert_eq!(diagnostic["params"]["version"], 2);
    std::fs::write(&pdf, "%PDF-1.4\nFresh\n").unwrap();
    server.request(
        3,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[uri]}),
    );
    let fresh = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(fresh["params"]["status"], "success", "{fresh}");
    assert_eq!(fresh["params"]["stale"], false);
    assert_eq!(fresh["params"]["diagnosticsCount"], 0);
    server.request(4, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn unchanged_input_contents_allow_noop_builds_after_repeated_saves() {
    for on_save in [false, true] {
        let script = "if [ ! -f \"$1/main.pdf\" ]; then\nprintf '%%PDF-1.4\\n' > \"$1/main.pdf\"\nprintf 'INPUT %s\\nINPUT chapter.tex\\nINPUT plot.png\\n' \"$2\" > \"$1/main.fls\"\nfi\n";
        let (mut server, directory, main) = fake_build_server(script, on_save);
        let source = "\\documentclass{article}\n\\input{chapter}\n\\includegraphics{plot.png}\n\\bibliography{refs}\n\\bibliographystyle{local}\n";
        let main_path = main.to_file_path().unwrap();
        std::fs::write(&main_path, source).unwrap();
        for (name, contents) in [
            ("chapter.tex", b"Chapter\n".as_slice()),
            ("plot.png", &[0, 255, 1]),
            ("refs.bib", b"@book{book,title={Title}}\n"),
            ("local.bst", b"Style\n"),
        ] {
            std::fs::write(directory.path().join(name), contents).unwrap();
        }
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let first = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(first["params"]["status"], "success", "{first}");
        let pdf = directory.path().join("build/latex-lsp/main.pdf");
        let pdf_before = std::fs::read(&pdf).unwrap();
        let pdf_modified = std::fs::metadata(&pdf).unwrap().modified().unwrap();
        for (index, name) in [
            "main.tex",
            "chapter.tex",
            "plot.png",
            "refs.bib",
            "local.bst",
        ]
        .into_iter()
        .enumerate()
        {
            let input = directory.path().join(name);
            let contents = std::fs::read(&input).unwrap();
            std::fs::write(&input, contents).unwrap();
            std::fs::File::open(&input)
                .unwrap()
                .set_times(
                    std::fs::FileTimes::new().set_modified(pdf_modified + Duration::from_secs(1)),
                )
                .unwrap();
            if on_save {
                server.notify("textDocument/didSave", json!({"textDocument":{"uri":main}}));
            } else {
                server.request(
                    3 + index as u64,
                    "workspace/executeCommand",
                    json!({"command":"latex.build","arguments":[main]}),
                );
            }
            let noop = server.until(|message| message["method"] == "latex/buildFinished");
            assert_eq!(noop["params"]["status"], "success", "{name}: {noop}");
            assert_eq!(noop["params"]["stale"], false, "{noop}");
            assert_eq!(noop["params"]["diagnosticsCount"], 0, "{noop}");
            assert_eq!(noop["params"]["pdfUri"], first["params"]["pdfUri"]);
            assert_eq!(std::fs::read(&pdf).unwrap(), pdf_before);
            assert_eq!(
                std::fs::metadata(&pdf).unwrap().modified().unwrap(),
                pdf_modified
            );
        }
        // The accepted no-ops must retain the original content history.
        std::fs::write(&main_path, source.replace("article", "minimal")).unwrap();
        std::fs::File::open(&main_path)
            .unwrap()
            .set_times(std::fs::FileTimes::new().set_modified(pdf_modified))
            .unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":3},"contentChanges":[{"text":source.replace("article", "minimal")}]}),
        );
        server.request(
            10,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let outdated = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(outdated["params"]["status"], "error", "{outdated}");
        assert!(outdated["params"]["pdfUri"].is_null());
        assert!(
            outdated["params"]["message"]
                .as_str()
                .is_some_and(|message| message.contains("input content changed")),
            "{outdated}"
        );
        server.request(11, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn first_latexmk_build_refreshes_existing_artifacts_for_newer_root_or_child_inputs() {
    use std::os::unix::fs::PermissionsExt;

    for touched in ["main.tex", "chapter.tex"] {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        let main_path = root.join("main.tex");
        let main = Url::from_file_path(&main_path).unwrap();
        let source = "\\documentclass{article}\n\\input{chapter}\n";
        std::fs::write(&main_path, source).unwrap();
        std::fs::write(root.join("chapter.tex"), "Chapter\n").unwrap();
        let output = root.join("build/latex-lsp");
        std::fs::create_dir_all(&output).unwrap();
        let pdf = output.join("main.pdf");
        std::fs::write(&pdf, "%PDF-1.4\nExisting\n").unwrap();
        let now = std::time::SystemTime::now();
        for (path, age) in [
            (main_path.clone(), 180),
            (root.join("chapter.tex"), 180),
            (pdf.clone(), 120),
            (root.join(touched), 60),
        ] {
            std::fs::File::open(path)
                .unwrap()
                .set_modified(now - Duration::from_secs(age))
                .unwrap();
        }
        let compiler = root.join("latexmk");
        std::fs::write(
            &compiler,
            r#"#!/bin/sh
force=false
for arg do
  printf '%s\n' "$arg" >> compiler-arguments
  case "$arg" in
    -g) force=true ;;
    -outdir=*) out=${arg#-outdir=} ;;
  esac
done
if "$force"; then
  printf '%%PDF-1.4\nRefreshed\n' > "$out/main.pdf"
  printf 'INPUT main.tex\nINPUT chapter.tex\n' > "$out/main.fls"
else
  printf 'Nothing to do\n'
fi
"#,
        )
        .unwrap();
        std::fs::set_permissions(&compiler, std::fs::Permissions::from_mode(0o755)).unwrap();
        let mut server = Server::start();
        server.request(
            1,
            "initialize",
            json!({
                "processId":null,
                "rootUri":Url::from_directory_path(root).unwrap(),
                "capabilities":{},
                "initializationOptions":{"build":{"executable":compiler}}
            }),
        );
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({
                "textDocument":{"uri":main,"languageId":"latex","version":1,"text":source}
            }),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({
                "command":"latex.build","arguments":[main]
            }),
        );
        let first = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(first["params"]["status"], "success", "{touched}: {first}");
        assert_eq!(first["params"]["stale"], false, "{first}");
        assert_eq!(first["params"]["diagnosticsCount"], 0, "{first}");
        assert!(std::fs::read_to_string(&pdf).unwrap().contains("Refreshed"));
        let pdf_modified = std::fs::metadata(&pdf).unwrap().modified().unwrap();
        std::fs::File::open(root.join(touched))
            .unwrap()
            .set_modified(pdf_modified + Duration::from_secs(1))
            .unwrap();
        server.request(
            3,
            "workspace/executeCommand",
            json!({
                "command":"latex.build","arguments":[main]
            }),
        );
        let noop = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(noop["params"]["status"], "success", "{touched}: {noop}");
        assert_eq!(noop["params"]["stale"], false, "{noop}");
        assert!(noop["params"]["output"]
            .as_str()
            .unwrap()
            .contains("Nothing to do"));
        assert_eq!(
            std::fs::metadata(&pdf).unwrap().modified().unwrap(),
            pdf_modified
        );
        assert_eq!(
            std::fs::read_to_string(root.join("compiler-arguments"))
                .unwrap()
                .lines()
                .filter(|argument| *argument == "-g")
                .count(),
            1
        );
        server.request(4, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
#[ignore = "requires latexmk and a TeX installation"]
fn real_latexmk_refreshes_preexisting_pdf_then_reuses_it_after_identical_saves() {
    let directory = tempfile::tempdir().unwrap();
    let main_path = directory.path().join("main.tex");
    let main = Url::from_file_path(&main_path).unwrap();
    let source = "\\documentclass{article}\n\\begin{document}\nHello, world.\n\\end{document}\n";
    std::fs::write(&main_path, source).unwrap();
    let initial = latex_lsp::build::run(&main_path, &Default::default(), &Default::default());
    assert_eq!(initial.status, "success", "{}", initial.output);
    let existing_pdf = initial.pdf.unwrap();
    let modified = std::fs::metadata(existing_pdf).unwrap().modified().unwrap();
    std::fs::File::open(&main_path)
        .unwrap()
        .set_modified(modified + Duration::from_secs(1))
        .unwrap();
    let mut server = Server::start();
    server.request(
        1,
        "initialize",
        json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"capabilities":{},"initializationOptions":{"build":{"onSave":true}}}),
    );
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":1,"text":source}}),
    );
    server.notify("textDocument/didSave", json!({"textDocument":{"uri":main}}));
    let first = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(first["params"]["status"], "success", "{first}");
    assert!(
        first["params"]["output"]
            .as_str()
            .unwrap()
            .contains("applying rule"),
        "{first}"
    );
    let pdf = directory.path().join("build/latex-lsp/main.pdf");
    let pdf_before = std::fs::read(&pdf).unwrap();
    let pdf_modified = std::fs::metadata(&pdf).unwrap().modified().unwrap();
    for _ in 0..2 {
        std::fs::write(&main_path, source).unwrap();
        std::fs::File::open(&main_path)
            .unwrap()
            .set_times(
                std::fs::FileTimes::new().set_modified(pdf_modified + Duration::from_secs(1)),
            )
            .unwrap();
        server.notify("textDocument/didSave", json!({"textDocument":{"uri":main}}));
        let noop = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(noop["params"]["status"], "success", "{noop}");
        assert_eq!(noop["params"]["stale"], false, "{noop}");
        assert_eq!(noop["params"]["diagnosticsCount"], 0, "{noop}");
        assert!(
            noop["params"]["output"]
                .as_str()
                .is_some_and(|output| output.contains("Nothing to do")),
            "{noop}"
        );
        assert_eq!(std::fs::read(&pdf).unwrap(), pdf_before);
        assert_eq!(
            std::fs::metadata(&pdf).unwrap().modified().unwrap(),
            pdf_modified
        );
    }
    server.request(2, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

