#[test]
fn futurelet_targets_return_versioned_cross_file_renames_over_stdio() {
    for declaration in [
        r"\futurelet\lookahead\relax A",
        r"\expandafter\futurelet\csname lookahead\endcsname\relax A",
    ] {
        let directory = tempfile::tempdir().unwrap();
        let root = Url::from_directory_path(directory.path()).unwrap();
        let definitions = Url::from_file_path(directory.path().join("definitions.tex")).unwrap();
        std::fs::write(definitions.to_file_path().unwrap(), declaration).unwrap();
        let main = Url::from_file_path(directory.path().join("main.tex")).unwrap();
        let source = "\\documentclass{article}\n\\begin{document}\\input{definitions}\n😀 \\lookahead\\csname lookahead\\endcsname\n\\end{document}\n";
        std::fs::write(main.to_file_path().unwrap(), source).unwrap();
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":root,"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":main,"languageId":"latex","version":9,"text":source}}),
        );
        server.until(|message| {
            message["method"] == "textDocument/publishDiagnostics"
                && message["params"]["uri"] == main.as_str()
        });
        let target = json!({"textDocument":{"uri":main},"position":{"line":2,"character":5}});
        let prepared = server.request(2, "textDocument/prepareRename", target.clone());
        assert_eq!(prepared["placeholder"], "lookahead");
        assert_eq!(
            prepared["range"],
            json!({"start":{"line":2,"character":4},"end":{"line":2,"character":13}})
        );
        let locations = server.request(3, "textDocument/definition", target.clone());
        assert_eq!(locations[0]["uri"], definitions.as_str());
        let mut params = target;
        params["newName"] = json!("renamedlookahead");
        let edit = server.request(4, "textDocument/rename", params);
        let documents = edit["documentChanges"].as_array().unwrap();
        assert_eq!(documents.len(), 2);
        for (uri, version, count) in [(&main, json!(9), 2), (&definitions, Value::Null, 1)] {
            let document = documents
                .iter()
                .find(|document| document["textDocument"]["uri"] == uri.as_str())
                .unwrap();
            assert_eq!(document["textDocument"]["version"], version);
            let edits = document["edits"].as_array().unwrap();
            assert_eq!(edits.len(), count);
            assert!(edits.iter().all(|edit| edit["newText"]
                .as_str()
                .unwrap()
                .ends_with("renamedlookahead")));
        }
        server.request(5, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn rename_prepares_ranges_and_returns_versioned_cross_file_edits() {
    let directory = tempfile::tempdir().unwrap();
    let root = Url::from_directory_path(directory.path()).unwrap();
    let chapter = Url::from_file_path(directory.path().join("chapter.tex")).unwrap();
    std::fs::write(chapter.to_file_path().unwrap(), r"\label{old}").unwrap();
    let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    let mut server = Server::start();
    let init = server.request(1, "initialize", json!({"processId":null,"rootUri":root,"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
    assert_eq!(
        init["capabilities"]["renameProvider"]["prepareProvider"],
        true
    );
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":9,"text":"\\ref{old}"}}),
    );
    server.until(|message| message["method"] == "textDocument/publishDiagnostics");
    let params = json!({"textDocument":{"uri":uri},"position":{"line":0,"character":6}});
    let prepared = server.request(2, "textDocument/prepareRename", params.clone());
    assert_eq!(prepared["placeholder"], "old");
    assert_eq!(prepared["range"]["start"]["character"], 5);
    let mut params = params;
    params["newName"] = json!("sec:new");
    let edit = server.request(3, "textDocument/rename", params);
    let documents = edit["documentChanges"].as_array().unwrap();
    assert_eq!(documents.len(), 2);
    let open = documents
        .iter()
        .find(|edit| edit["textDocument"]["uri"] == uri.as_str())
        .unwrap();
    assert_eq!(open["textDocument"]["version"], 9);
    assert_eq!(open["edits"][0]["newText"], "sec:new");
    let closed = documents
        .iter()
        .find(|edit| edit["textDocument"]["uri"] == chapter.as_str())
        .unwrap();
    assert!(closed["textDocument"]["version"].is_null());
    server.request(4, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn file_rename_requests_update_references_and_preserve_open_document_versions() {
    let directory = tempfile::tempdir().unwrap();
    let root = Url::from_directory_path(directory.path()).unwrap();
    let main = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    let child = Url::from_file_path(directory.path().join("child.tex")).unwrap();
    let renamed = Url::from_file_path(directory.path().join("renamed.tex")).unwrap();
    let source = "\\documentclass{article}\n\\input{child}\n\\ref{sec:x}\n";
    std::fs::write(main.to_file_path().unwrap(), source).unwrap();
    std::fs::write(child.to_file_path().unwrap(), "\\label{sec:x}").unwrap();
    let mut server = Server::start();
    let init = server.request(1,"initialize",json!({"processId":null,"rootUri":root,"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true},"fileOperations":{"willRename":true,"didRename":true}}}}));
    assert_eq!(
        init["capabilities"]["workspace"]["fileOperations"]["willRename"]["filters"][0]["scheme"],
        "file"
    );
    server.notify("initialized", json!({}));
    for (uri, source, version) in [(&main, source, 1), (&child, "\\label{sec:x}", 4)] {
        server.notify("textDocument/didOpen",json!({"textDocument":{"uri":uri,"languageId":"latex","version":version,"text":source}}));
        server.until(|message| {
            message["method"] == "textDocument/publishDiagnostics"
                && message["params"]["uri"] == uri.as_str()
        });
    }
    let files = json!({"files":[{"oldUri":child,"newUri":renamed}]});
    let edit = server.request(2, "workspace/willRenameFiles", files.clone());
    assert_eq!(
        edit["documentChanges"][0]["textDocument"]["uri"],
        main.as_str()
    );
    assert_eq!(edit["documentChanges"][0]["textDocument"]["version"], 1);
    assert_eq!(edit["documentChanges"][0]["edits"][0]["newText"], "renamed");
    let source = source.replace("{child}", "{renamed}");
    std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
    );
    std::fs::rename(
        child.to_file_path().unwrap(),
        renamed.to_file_path().unwrap(),
    )
    .unwrap();
    server.notify("workspace/didRenameFiles", files);
    let symbols = server.request(3, "workspace/symbol", json!({"query":"sec:x"}));
    assert_eq!(symbols[0]["location"]["uri"], renamed.as_str());
    let rename = server.request(4,"textDocument/rename",json!({"textDocument":{"uri":renamed},"position":{"line":0,"character":9},"newName":"sec:new"}));
    let documents = rename["documentChanges"].as_array().unwrap();
    assert_eq!(
        documents
            .iter()
            .find(|doc| doc["textDocument"]["uri"] == renamed.as_str())
            .unwrap()["textDocument"]["version"],
        4
    );
    let definition = server.request(
        5,
        "textDocument/definition",
        json!({"textDocument":{"uri":main},"position":{"line":2,"character":8}}),
    );
    assert_eq!(definition[0]["uri"], renamed.as_str());
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn source_filename_renames_validate_tex_whitespace_and_keep_versioned_navigation() {
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let main = Url::from_file_path(root.join("main.tex")).unwrap();
    let chapter = Url::from_file_path(root.join("chapter.tex")).unwrap();
    let mut source = "\\documentclass{article}\n\\input{chapter}\n\\ref{sec:x}\n".to_string();
    std::fs::write(root.join("main.tex"), &source).unwrap();
    std::fs::write(root.join("chapter.tex"), "\\label{sec:x}").unwrap();
    let mut server = Server::start();
    server.request(
        1,
        "initialize",
        json!({"processId":null,
        "rootUri":Url::from_directory_path(root).unwrap(),
        "capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true},
            "fileOperations":{"willRename":true,"didRename":true}}}}),
    );
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{
        "uri":main,"languageId":"latex","version":7,"text":source}}),
    );
    server.until(|message| {
        message["method"] == "textDocument/publishDiagnostics"
            && message["params"]["uri"] == main.as_str()
    });
    let invalid = Url::from_file_path(root.join("two  spaces.tex")).unwrap();
    server.send(
        json!({"jsonrpc":"2.0","id":2,"method":"workspace/willRenameFiles",
        "params":{"files":[{"oldUri":chapter,"newUri":invalid}]}}),
    );
    let rejected = server.until(|message| message["id"] == 2);
    assert_eq!(rejected["error"]["code"], -32602, "{rejected}");
    let mut old = chapter;
    for (id, version, filename, expected) in [
        (3, 7, " leading.tex", "./ leading"),
        (5, 8, "chapter .tex", "./chapter .tex"),
    ] {
        let new = Url::from_file_path(root.join(filename)).unwrap();
        let files = json!({"files":[{"oldUri":old,"newUri":new}]});
        let result = server.request(id, "workspace/willRenameFiles", files.clone());
        let documents = result["documentChanges"].as_array().unwrap();
        assert_eq!(documents.len(), 1, "{result}");
        assert_eq!(documents[0]["textDocument"]["uri"], main.as_str());
        assert_eq!(documents[0]["textDocument"]["version"], version);
        let edits: Vec<tower_lsp::lsp_types::TextEdit> =
            serde_json::from_value(documents[0]["edits"].clone()).unwrap();
        assert_eq!(edits.len(), 1);
        assert_eq!(edits[0].new_text, expected);
        source = latex_lsp::text::Text::new(source)
            .changed(
                edits
                    .into_iter()
                    .map(
                        |edit| tower_lsp::lsp_types::TextDocumentContentChangeEvent {
                            range: Some(edit.range),
                            range_length: None,
                            text: edit.new_text,
                        },
                    )
                    .collect(),
            )
            .unwrap()
            .source;
        std::fs::write(root.join("main.tex"), &source).unwrap();
        server.notify("textDocument/didChange",json!({"textDocument":{"uri":main,"version":version+1},"contentChanges":[{"text":source}]}));
        std::fs::rename(old.to_file_path().unwrap(), new.to_file_path().unwrap()).unwrap();
        server.notify("workspace/didRenameFiles", files);
        let definition = server.request(
            id + 1,
            "textDocument/definition",
            json!({
            "textDocument":{"uri":main},"position":{"line":2,"character":8}}),
        );
        assert_eq!(definition[0]["uri"], new.as_str(), "{definition}");
        old = new;
    }
    server.request(7, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn file_url_rename_requests_preserve_destinations_in_versioned_edits() {
    let directory = tempfile::tempdir().unwrap();
    let root = Url::from_directory_path(directory.path()).unwrap();
    let main = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    let old = Url::from_file_path(directory.path().join("manual.pdf")).unwrap();
    let new = Url::from_file_path(directory.path().join("new manual.pdf")).unwrap();
    std::fs::write(old.to_file_path().unwrap(), "pdf").unwrap();
    let source = format!(
        "\\href{{{old}?download=1#page=3}}{{Manual}}\n\
         \\hyperref{{{old}?download=1}}{{chapter}}{{intro}}{{Chapter}}\n\
         % \\url{{{old}#page=3}}\n"
    );
    let mut server = Server::start();
    server.request(
        1,
        "initialize",
        json!({
            "processId":null,"rootUri":root,
            "capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true},
                "fileOperations":{"willRename":true,"didRename":true}}}
        }),
    );
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{
            "uri":main,"languageId":"latex","version":17,"text":source
        }}),
    );
    server.until(|message| message["method"] == "textDocument/publishDiagnostics");
    let files = json!({"files":[{"oldUri":old,"newUri":new}]});
    let result = server.request(2, "workspace/willRenameFiles", files.clone());
    let documents = result["documentChanges"].as_array().unwrap();
    assert_eq!(documents.len(), 1);
    assert_eq!(documents[0]["textDocument"]["uri"], main.as_str());
    assert_eq!(documents[0]["textDocument"]["version"], 17);
    let edits = documents[0]["edits"].as_array().unwrap();
    assert_eq!(edits.len(), 2);
    for (line, expected) in [
        (0, format!("{new}?download=1#page=3")),
        (1, format!("{new}?download=1")),
    ] {
        let edit = edits
            .iter()
            .find(|edit| edit["range"]["start"]["line"] == line)
            .unwrap();
        assert_eq!(edit["newText"], expected);
    }
    let mut updated = source.clone();
    let mut edits: Vec<tower_lsp::lsp_types::TextEdit> =
        serde_json::from_value(documents[0]["edits"].clone()).unwrap();
    edits.sort_by_key(|edit| std::cmp::Reverse(edit.range.start));
    for edit in edits {
        let text = latex_lsp::text::Text::new(source.clone());
        updated.replace_range(
            text.offset(edit.range.start).unwrap()..text.offset(edit.range.end).unwrap(),
            &edit.new_text,
        );
    }
    server.notify(
        "textDocument/didChange",
        json!({
            "textDocument":{"uri":main,"version":18},"contentChanges":[{"text":updated}]
        }),
    );
    std::fs::rename(old.to_file_path().unwrap(), new.to_file_path().unwrap()).unwrap();
    server.notify("workspace/didRenameFiles", files);
    let links = server.request(
        3,
        "textDocument/documentLink",
        json!({"textDocument":{"uri":main}}),
    );
    let links = links.as_array().unwrap();
    assert_eq!(links.len(), 2);
    assert_eq!(links[0]["target"], format!("{new}?download=1#page=3"));
    assert_eq!(
        links[1]["target"],
        format!("{new}?download=1#chapter.intro")
    );
    server.request(4, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn command_only_code_actions_request_client_edits_and_reject_stale_versions() {
    let mut server = Server::start();
    let uri = Url::parse("file:///editing-protocol/legacy.tex").unwrap();
    server.request(
        1,
        "initialize",
        json!({"processId":null,"capabilities":{"workspace":{"applyEdit":true}}}),
    );
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":1,"text":"{broken"}}),
    );
    let diagnostics =
        server.until(|message| message["method"] == "textDocument/publishDiagnostics");
    let diagnostic = diagnostics["params"]["diagnostics"][0].clone();
    let actions = server.request(2, "textDocument/codeAction", json!({"textDocument":{"uri":uri},"range":diagnostic["range"],"context":{"diagnostics":[diagnostic]}}));
    assert_eq!(actions[0]["command"], "latex.applyQuickFix");
    server.send(json!({"jsonrpc":"2.0","id":3,"method":"workspace/executeCommand","params":{"command":actions[0]["command"],"arguments":actions[0]["arguments"]}}));
    let apply = server.until(|message| message["method"] == "workspace/applyEdit");
    assert_eq!(
        apply["params"]["edit"]["changes"][uri.as_str()][0]["newText"],
        "}"
    );
    server.send(json!({"jsonrpc":"2.0","id":apply["id"],"result":{"applied":true}}));
    let response = server.until(|message| message["id"] == 3);
    assert_eq!(response["result"]["applied"], true);
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"text":"{still broken"}]}),
    );
    server.send(json!({"jsonrpc":"2.0","id":4,"method":"workspace/executeCommand","params":{"command":actions[0]["command"],"arguments":actions[0]["arguments"]}}));
    let response = server.until(|message| message["id"] == 4);
    assert_eq!(response["error"]["code"], -32602);
    assert!(response["error"]["message"]
        .as_str()
        .unwrap()
        .contains("outdated"));
    server.request(5, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn quick_fixes_highlights_and_selection_ranges_work_over_stdio() {
    let mut server = Server::start();
    let uri = Url::parse("file:///editing-protocol/main.tex").unwrap();
    let init = server.request(1, "initialize", json!({"processId":null,"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true}},"textDocument":{"codeAction":{"codeActionLiteralSupport":{"codeActionKind":{"valueSet":["quickfix"]}}}}}}));
    assert_eq!(
        init["capabilities"]["codeActionProvider"]["codeActionKinds"][0],
        "quickfix"
    );
    assert_eq!(init["capabilities"]["selectionRangeProvider"], true);
    assert_eq!(init["capabilities"]["documentHighlightProvider"], true);
    server.notify("initialized", json!({}));
    let source = "\\label{x}\n\\ref{x}\n\\begin{equation}\nx=1\n";
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":3,"text":source}}),
    );
    let diagnostics =
        server.until(|message| message["method"] == "textDocument/publishDiagnostics");
    let diagnostic = diagnostics["params"]["diagnostics"][0].clone();
    let actions = server.request(2, "textDocument/codeAction", json!({"textDocument":{"uri":uri},"range":diagnostic["range"],"context":{"diagnostics":[diagnostic],"only":["quickfix"]}}));
    assert_eq!(actions.as_array().unwrap().len(), 1);
    assert_eq!(actions[0]["title"], "Close environment `equation`");
    assert_eq!(
        actions[0]["edit"]["documentChanges"][0]["textDocument"]["version"],
        3
    );
    let highlights = server.request(
        3,
        "textDocument/documentHighlight",
        json!({"textDocument":{"uri":uri},"position":{"line":1,"character":6}}),
    );
    assert_eq!(highlights.as_array().unwrap().len(), 2);
    let selections = server.request(4, "textDocument/selectionRange", json!({"textDocument":{"uri":uri},"positions":[{"line":1,"character":6},{"line":3,"character":1}]}));
    assert_eq!(selections.as_array().unwrap().len(), 2);
    assert!(selections[0]["parent"].is_object());
    let repaired = format!("{source}\\end{{equation}}\n");
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":uri,"version":4},"contentChanges":[{"text":repaired}]}),
    );
    server.until(|message| {
        message["method"] == "textDocument/publishDiagnostics" && message["params"]["version"] == 4
    });
    let actions = server.request(5, "textDocument/codeAction", json!({"textDocument":{"uri":uri},"range":diagnostic["range"],"context":{"diagnostics":[diagnostic]}}));
    assert!(actions.as_array().unwrap().is_empty());
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn bibliography_type_and_field_completion_negotiate_snippets_and_refresh_over_stdio() {
    let directory = tempfile::tempdir().unwrap();
    let uri = Url::from_file_path(directory.path().join("refs.bib")).unwrap();
    for snippets in [false, true] {
        let mut server = Server::start();
        let initialized = server.request(1, "initialize", json!({"processId":null,"capabilities":{"textDocument":{"completion":{"completionItem":{"snippetSupport":snippets}}}}}));
        assert!(
            initialized["capabilities"]["completionProvider"]["triggerCharacters"]
                .as_array()
                .unwrap()
                .contains(&json!("@"))
        );
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":uri,"languageId":"bibtex","version":1,"text":"@ArTBAD"}}),
        );
        let items = server.request(
            2,
            "textDocument/completion",
            json!({"textDocument":{"uri":uri},"position":{"line":0,"character":4}}),
        );
        let article = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["label"] == "article")
            .unwrap();
        assert_eq!(
            article["textEdit"]["range"],
            json!({"start":{"line":0,"character":1},"end":{"line":0,"character":7}})
        );
        assert_eq!(article["insertTextFormat"], if snippets { 2 } else { 1 });
        if snippets {
            assert!(article["textEdit"]["newText"]
                .as_str()
                .unwrap()
                .contains("author = {${2:}}"));
        } else {
            assert_eq!(article["textEdit"]["newText"], "article");
        }
        let source = "@book{😀,\r\n  authBAD = {Writer},\r\n  ti\r\n}";
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"text":source}]}),
        );
        let items = server.request(
            3,
            "textDocument/completion",
            json!({"textDocument":{"uri":uri},"position":{"line":1,"character":6}}),
        );
        let author = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["label"] == "author")
            .unwrap();
        assert_eq!(author["insertTextFormat"], 1);
        assert_eq!(author["textEdit"]["newText"], "author");
        assert_eq!(
            author["textEdit"]["range"],
            json!({"start":{"line":1,"character":2},"end":{"line":1,"character":9}})
        );
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":uri,"version":3},"contentChanges":[{"range":author["textEdit"]["range"],"text":"author"}]}));
        let hover = server.request(
            4,
            "textDocument/hover",
            json!({"textDocument":{"uri":uri},"position":{"line":1,"character":4}}),
        );
        assert!(hover["contents"]["value"]
            .as_str()
            .unwrap()
            .contains("Authors"));
        let items = server.request(
            5,
            "textDocument/completion",
            json!({"textDocument":{"uri":uri},"position":{"line":2,"character":4}}),
        );
        let title = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["label"] == "title")
            .unwrap();
        assert_eq!(
            title["textEdit"]["newText"],
            if snippets {
                "title = {${1:}},"
            } else {
                "title"
            }
        );
        let source = "@book{😀,\r\n  author = {Writer},\r\n  title = {Text @art},\r\n  \r\n}";
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":uri,"version":4},"contentChanges":[{"text":source}]}),
        );
        let items = server.request(
            6,
            "textDocument/completion",
            json!({"textDocument":{"uri":uri},"position":{"line":3,"character":2}}),
        );
        assert!(!items
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["label"] == "author" || item["label"] == "title"));
        assert!(items
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["label"] == "publisher"));
        let at = source.find("@art").unwrap() + 4;
        let empty = server.request(7, "textDocument/completion", json!({"textDocument":{"uri":uri},"position":latex_lsp::text::Text::new(source.into()).position(at)}));
        assert_eq!(empty, json!([]));
        server.request(8, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn bibliography_links_refresh_unsaved_fields_and_restore_current_disk_content_over_stdio() {
    let directory = tempfile::tempdir().unwrap();
    let uri = Url::from_file_path(directory.path().join("中文 references.bib")).unwrap();
    let disk = "@book{key,url={https://example.org/disk},doi={10.1234/disk}}";
    std::fs::write(uri.to_file_path().unwrap(), disk).unwrap();
    let mut server = Server::start();
    let initialized = server.request(
        1,
        "initialize",
        json!({
            "processId": null,
            "rootUri": Url::from_directory_path(directory.path()).unwrap(),
            "capabilities": {}
        }),
    );
    assert!(initialized["capabilities"]["documentLinkProvider"].is_object());
    server.notify("initialized", json!({}));
    let request = json!({"textDocument": {"uri": uri}});
    let disk_links = server.request(2, "textDocument/documentLink", request.clone());
    assert_eq!(disk_links.as_array().unwrap().len(), 2);
    assert_eq!(disk_links[0]["target"], "https://example.org/disk");
    let source = "@book{😀,url={https://example.org/buffer},doi={10.1234/a?b#c}}\r\n";
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument": {
            "uri": uri, "languageId": "bibtex", "version": 10, "text": source
        }}),
    );
    let links = server.request(3, "textDocument/documentLink", request.clone());
    assert_eq!(links[0]["target"], "https://example.org/buffer");
    assert_eq!(links[0]["range"]["start"]["character"], 14);
    assert_eq!(links[1]["target"], "https://doi.org/10.1234/a%3Fb%23c");
    let tokens = server.request(30, "textDocument/semanticTokens/full", request.clone());
    assert_eq!(tokens["data"].as_array().unwrap().len(), 60);
    let text = latex_lsp::text::Text::new(source.into());
    let start = source.find("10.1234/").unwrap();
    let end = source[start..].find('}').unwrap() + start;
    server.notify(
        "textDocument/didChange",
        json!({
            "textDocument": {"uri": uri, "version": 11},
            "contentChanges": [{"range": text.range(start, end), "text": "10.5678/changed"}]
        }),
    );
    let links = server.request(4, "textDocument/documentLink", request.clone());
    assert_eq!(links[1]["target"], "https://doi.org/10.5678/changed");
    let source = source.replace("10.1234/a?b#c", "10.5678/changed");
    let text = latex_lsp::text::Text::new(source.clone());
    let start = source.find("{https://").unwrap();
    let end = source[start..].find('}').unwrap() + start + 1;
    server.notify(
        "textDocument/didChange",
        json!({
            "textDocument": {"uri": uri, "version": 12},
            "contentChanges": [{"range": text.range(start, end), "text": "baseurl"}]
        }),
    );
    let links = server.request(5, "textDocument/documentLink", request.clone());
    assert_eq!(links.as_array().unwrap().len(), 1);
    assert_eq!(links[0]["target"], "https://doi.org/10.5678/changed");
    let tokens = server.request(31, "textDocument/semanticTokens/full", request.clone());
    // The URL abbreviation is a variable reference; the DOI stays a string.
    assert_eq!(
        tokens["data"],
        json!([
            0, 1, 4, 2, 0, 0, 5, 2, 3, 1, 0, 3, 3, 6, 0, 0, 3, 1, 8, 0, 0, 1, 7, 1, 0, 0, 8, 3, 6,
            0, 0, 3, 1, 8, 0, 0, 1, 1, 4, 0, 0, 1, 15, 4, 0, 0, 15, 1, 4, 0
        ])
    );
    std::fs::write(
        uri.to_file_path().unwrap(),
        "@book{key,url={https://example.org/updated-disk}}",
    )
    .unwrap();
    server.notify(
        "workspace/didChangeWatchedFiles",
        json!({"changes": [{"uri": uri,"type":2}]}),
    );
    assert_eq!(
        server.request(6, "textDocument/documentLink", request.clone()),
        links
    );
    server.notify(
        "textDocument/didClose",
        json!({"textDocument": {"uri": uri}}),
    );
    let links = server.request(7, "textDocument/documentLink", request.clone());
    assert_eq!(links.as_array().unwrap().len(), 1);
    assert_eq!(links[0]["target"], "https://example.org/updated-disk");
    std::fs::write(
        uri.to_file_path().unwrap(),
        "@book{key,url={https://example.org/reloaded}}",
    )
    .unwrap();
    server.notify(
        "workspace/didChangeWatchedFiles",
        json!({"changes": [{"uri": uri,"type":2}]}),
    );
    let links = server.request(8, "textDocument/documentLink", request);
    assert_eq!(links[0]["target"], "https://example.org/reloaded");
    server.request(9, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn custom_bibliography_field_completions_refresh_project_resources_and_negotiate_snippets() {
    for snippets in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        std::fs::write(
            root.join("main.tex"),
            r"\documentclass{article}\bibliography{shared,query}",
        )
        .unwrap();
        let shared = Url::from_file_path(root.join("shared.bib")).unwrap();
        let query = Url::from_file_path(root.join("query.bib")).unwrap();
        let disk = "@book{old,Cost$Field={Disk}}";
        std::fs::write(shared.to_file_path().unwrap(), disk).unwrap();
        let source = "@book{😀, coBAD}";
        std::fs::write(query.to_file_path().unwrap(), source).unwrap();
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{"textDocument":{"completion":{"completionItem":{"snippetSupport":snippets}}}}}));
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":query,"languageId":"bibtex","version":1,"text":source}}),
        );
        let request = json!({"textDocument":{"uri":query},"position":{"line":0,"character":12}});
        let items = server.request(2, "textDocument/completion", request.clone());
        let cost = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["label"] == "Cost$Field")
            .unwrap();
        assert_eq!(
            cost["textEdit"]["range"],
            json!({"start":{"line":0,"character":10},"end":{"line":0,"character":15}})
        );
        assert_eq!(cost["insertTextFormat"], if snippets { 2 } else { 1 });
        assert_eq!(
            cost["textEdit"]["newText"],
            if snippets {
                r"Cost\$Field = {${1:}},"
            } else {
                "Cost$Field"
            }
        );
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":shared,"languageId":"bibtex","version":7,"text":disk}}),
        );
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":shared,"version":8},"contentChanges":[{"range":{"start":{"line":0,"character":10},"end":{"line":0,"character":20}},"text":"Code\\Field"}]}));
        let items = server.request(3, "textDocument/completion", request.clone());
        let code = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["label"] == "Code\\Field")
            .unwrap();
        assert_eq!(
            code["textEdit"]["newText"],
            if snippets {
                r"Code\\Field = {${1:}},"
            } else {
                r"Code\Field"
            }
        );
        assert!(!items
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["label"] == "Cost$Field"));
        std::fs::write(
            shared.to_file_path().unwrap(),
            "@book{old,Counter:Field={Watched}}",
        )
        .unwrap();
        server.notify(
            "workspace/didChangeWatchedFiles",
            json!({"changes":[{"uri":shared,"type":2}]}),
        );
        let items = server.request(4, "textDocument/completion", request.clone());
        assert!(items
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["label"] == "Code\\Field"));
        assert!(!items
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["label"] == "Counter:Field"));
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":shared}}),
        );
        let items = server.request(5, "textDocument/completion", request.clone());
        assert!(items
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["label"] == "Counter:Field"));
        assert!(!items
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["label"] == "Cost$Field" || item["label"] == "Code\\Field"));
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":query,"version":2},"contentChanges":[{"range":{"start":{"line":0,"character":15},"end":{"line":0,"character":15}},"text":" % keep\r\n = {Keep}"}]}));
        let items = server.request(6, "textDocument/completion", request);
        let counter = items
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["label"] == "Counter:Field")
            .unwrap();
        assert_eq!(counter["insertTextFormat"], 1);
        assert_eq!(counter["textEdit"]["newText"], "Counter:Field");
        server.request(7, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn folding_negotiates_columns_labels_and_refreshes_unsaved_tex_and_bibtex_over_stdio() {
    let directory = tempfile::tempdir().unwrap();
    let tex = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    let bib = Url::from_file_path(directory.path().join("refs.bib")).unwrap();
    for line_only in [false, true] {
        let mut server = Server::start();
        let init = server.request(
            1,
            "initialize",
            json!({
                "processId": null,
                "capabilities": {"textDocument": {"foldingRange": {
                    "lineFoldingOnly": line_only,
                    "rangeLimit": 8,
                    "foldingRange": {"collapsedText": true}
                }}}
            }),
        );
        assert_eq!(init["capabilities"]["foldingRangeProvider"], true);
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument": {
                "uri": tex, "languageId": "latex", "version": 1,
                "text": "前😀 \\[\r\nx\r\n\\] 尾\r\n"
            }}),
        );
        let folds = server.request(
            2,
            "textDocument/foldingRange",
            json!({"textDocument": {"uri": tex}}),
        );
        assert_eq!(folds.as_array().unwrap().len(), 1);
        assert_eq!(folds[0]["startLine"], 0);
        assert_eq!(folds[0]["endLine"], 2);
        assert_eq!(folds[0]["collapsedText"], "\\[ …");
        if line_only {
            assert!(folds[0].get("startCharacter").is_none());
            assert!(folds[0].get("endCharacter").is_none());
        } else {
            assert_eq!(folds[0]["startCharacter"], 4);
            assert_eq!(folds[0]["endCharacter"], 2);
        }
        server.notify("textDocument/didChange", json!({
            "textDocument": {"uri": tex, "version": 2},
            "contentChanges": [{"range": {"start": {"line": 2, "character": 0}, "end": {"line": 2, "character": 2}}, "text": ""}]
        }));
        assert_eq!(
            server.request(
                3,
                "textDocument/foldingRange",
                json!({"textDocument": {"uri": tex}})
            ),
            json!([])
        );
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument": {
                "uri": bib, "languageId": "bibtex", "version": 5,
                "text": "@article(中文😀,\r\n title = \"A ) title\"\r\n)\r\n"
            }}),
        );
        let folds = server.request(
            4,
            "textDocument/foldingRange",
            json!({"textDocument": {"uri": bib}}),
        );
        assert_eq!(folds.as_array().unwrap().len(), 1);
        assert_eq!(folds[0]["endLine"], 2);
        assert_eq!(folds[0]["collapsedText"], "@article(中文😀, …");
        server.notify("textDocument/didChange", json!({
            "textDocument": {"uri": bib, "version": 6},
            "contentChanges": [{"range": {"start": {"line": 2, "character": 0}, "end": {"line": 2, "character": 1}}, "text": ""}]
        }));
        assert_eq!(
            server.request(
                5,
                "textDocument/foldingRange",
                json!({"textDocument": {"uri": bib}})
            ),
            json!([])
        );
        server.request(6, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn navigation_capabilities_and_requests_work_over_stdio() {
    let directory = tempfile::tempdir().unwrap();
    let root = Url::from_directory_path(directory.path()).unwrap();
    let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    std::fs::write(directory.path().join("child.tex"), "\\label{sec:child}").unwrap();
    let source = "\\section{Main}\n\\input{child}\n\\begin{itemize}\n\\item text\n\\end{itemize}\n";
    std::fs::write(directory.path().join("main.tex"), source).unwrap();
    let mut server = Server::start();
    let init = server.request(1, "initialize", json!({"processId":null,"rootUri":root,"capabilities":{"textDocument":{"foldingRange":{"rangeLimit":1,"lineFoldingOnly":true}}}}));
    assert_eq!(init["capabilities"]["workspaceSymbolProvider"], true);
    assert_eq!(init["capabilities"]["foldingRangeProvider"], true);
    assert!(init["capabilities"]["documentLinkProvider"].is_object());
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":1,"text":source}}),
    );
    server.until(|message| message["method"] == "textDocument/publishDiagnostics");
    let symbols = server.request(2, "workspace/symbol", json!({"query":"sch"}));
    assert_eq!(symbols[0]["name"], "sec:child");
    let folds = server.request(
        3,
        "textDocument/foldingRange",
        json!({"textDocument":{"uri":uri}}),
    );
    assert_eq!(folds.as_array().unwrap().len(), 1);
    assert_eq!(folds[0]["startLine"], 0);
    assert!(folds[0].get("startCharacter").is_none());
    assert!(folds[0].get("endCharacter").is_none());
    assert!(folds[0].get("collapsedText").is_none());
    let links = server.request(
        4,
        "textDocument/documentLink",
        json!({"textDocument":{"uri":uri}}),
    );
    assert!(links[0]["target"].as_str().unwrap().ends_with("child.tex"));
    let completions = server.request(
        5,
        "textDocument/completion",
        json!({"textDocument":{"uri":uri},"position":{"line":1,"character":9}}),
    );
    let item = completions
        .as_array()
        .unwrap()
        .iter()
        .find(|item| item["label"] == "child.tex")
        .unwrap();
    assert_eq!(item["textEdit"]["newText"], "child");
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn document_symbols_follow_the_clients_hierarchy_capability() {
    let directory = tempfile::tempdir().unwrap();
    let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    for hierarchy in [false, true] {
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"capabilities":{"textDocument":{"documentSymbol":{"hierarchicalDocumentSymbolSupport":hierarchy}}}}));
        server.notify("initialized", json!({}));
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":uri,"languageId":"latex","version":1,"text":"\\section{Main}\n\\subsection{Child}\n\\label{sec:child}"}}));
        server.until(|message| message["method"] == "textDocument/publishDiagnostics");
        let symbols = server.request(
            2,
            "textDocument/documentSymbol",
            json!({"textDocument":{"uri":uri}}),
        );
        if hierarchy {
            assert_eq!(symbols.as_array().unwrap().len(), 1);
            assert_eq!(symbols[0]["children"][0]["name"], "Child");
            assert_eq!(
                symbols[0]["children"][0]["children"][0]["name"],
                "sec:child"
            );
            assert!(symbols[0].get("location").is_none());
        } else {
            assert_eq!(symbols.as_array().unwrap().len(), 3);
            assert_eq!(symbols[0]["location"]["uri"], uri.as_str());
            assert_eq!(symbols[1]["containerName"], "Main");
            assert_eq!(symbols[2]["containerName"], "Child");
        }
        server.request(3, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn stdio_lifecycle_incremental_edits_navigation_and_diagnostics() {
    let directory = tempfile::tempdir().unwrap();
    let root = Url::from_directory_path(directory.path()).unwrap();
    std::fs::write(directory.path().join("chapter.tex"), "\\label{sec:intro}").unwrap();
    let uri = Url::from_file_path(directory.path().join("main.tex")).unwrap();
    let mut server = Server::start();
    let initialized = server.request(
        1,
        "initialize",
        json!({"processId":null,"rootUri":root,"capabilities":{}}),
    );
    assert!(initialized["capabilities"]
        .get("diagnosticProvider")
        .is_none());
    assert_eq!(initialized["capabilities"]["positionEncoding"], "utf-16");
    assert_eq!(initialized["capabilities"]["textDocumentSync"]["change"], 2);
    server.notify("initialized", json!({}));
    server.notify("textDocument/didOpen", json!({"textDocument":{"uri":uri,"languageId":"latex","version":1,"text":"😀 \\ref{sec:intro}\n\\section{中文}\n}"}}));
    let diagnostics =
        server.until(|message| message["method"] == "textDocument/publishDiagnostics");
    assert_eq!(
        diagnostics["params"]["diagnostics"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert_eq!(
        diagnostics["params"]["diagnostics"][0]["range"]["start"]["line"],
        2
    );
    let definition = server.request(
        2,
        "textDocument/definition",
        json!({"textDocument":{"uri":uri},"position":{"line":0,"character":12}}),
    );
    assert!(definition[0]["uri"]
        .as_str()
        .unwrap()
        .ends_with("chapter.tex"));
    let hover = server.request(
        3,
        "textDocument/hover",
        json!({"textDocument":{"uri":uri},"position":{"line":1,"character":4}}),
    );
    assert!(hover["contents"]["value"]
        .as_str()
        .unwrap()
        .contains("section"));
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"range":{"start":{"line":2,"character":0},"end":{"line":2,"character":1}},"text":"\\sec"}]}));
    let diagnostics =
        server.until(|message| message["method"] == "textDocument/publishDiagnostics");
    assert_eq!(diagnostics["params"]["version"], 2);
    assert!(diagnostics["params"]["diagnostics"]
        .as_array()
        .unwrap()
        .is_empty());
    // An edit inside a UTF-16 surrogate pair must not corrupt the document.
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":uri,"version":3},"contentChanges":[{"range":{"start":{"line":0,"character":1},"end":{"line":0,"character":2}},"text":"bad"}]}));
    // Stale versions must not replace newer text.
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":uri,"version":1},"contentChanges":[{"text":"stale"}]}),
    );
    let completions = server.request(
        4,
        "textDocument/completion",
        json!({"textDocument":{"uri":uri},"position":{"line":2,"character":4}}),
    );
    assert!(completions
        .as_array()
        .unwrap()
        .iter()
        .any(|item| item["label"] == "section"));
    let symbols = server.request(
        5,
        "textDocument/documentSymbol",
        json!({"textDocument":{"uri":uri}}),
    );
    assert_eq!(symbols[0]["name"], "中文");
    server.notify("textDocument/didClose", json!({"textDocument":{"uri":uri}}));
    let cleared = server.until(|message| message["method"] == "textDocument/publishDiagnostics");
    assert!(cleared["params"]["diagnostics"]
        .as_array()
        .unwrap()
        .is_empty());
    assert!(server.request(6, "shutdown", Value::Null).is_null());
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn recorded_images_remain_binary_and_invalidate_unchanged_pdf_artifacts() {
    let script = "if [ ! -f \"$1/main.pdf\" ]; then\n printf '%%PDF-1.4\\n' > \"$1/main.pdf\"\n printf 'PWD %s\\nINPUT main.tex\\nINPUT assets/plot.png\\n' \"$PWD\" > \"$1/main.fls\"\nfi\n";
    let (mut server, directory, main) = fake_build_server(script, false);
    std::fs::create_dir(directory.path().join("assets")).unwrap();
    let image = directory.path().join("assets/plot.png");
    // Even an ASCII image containing TeX-looking text must stay outside the index.
    std::fs::write(&image, "\\label{image:should-not-be-indexed}").unwrap();
    server.request(
        2,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[main]}),
    );
    let first = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(first["params"]["status"], "success", "{first}");
    assert_eq!(first["params"]["dependenciesCount"], 2);
    assert_eq!(
        server.request(
            3,
            "workspace/symbol",
            json!({"query":"image:should-not-be-indexed"})
        ),
        json!([])
    );
    let pdf = directory.path().join("build/latex-lsp/main.pdf");
    let old_pdf = std::fs::read(&pdf).unwrap();
    let newer = std::fs::metadata(&pdf).unwrap().modified().unwrap() + Duration::from_secs(1);
    std::fs::File::open(&image)
        .unwrap()
        .set_times(std::fs::FileTimes::new().set_modified(newer))
        .unwrap();
    server.request(
        40,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[main]}),
    );
    let touched = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(touched["params"]["status"], "success", "{touched}");
    assert_eq!(std::fs::read(&pdf).unwrap(), old_pdf);
    std::fs::write(&image, "\\label{image:changed-but-not-indexed}").unwrap();
    std::fs::File::open(&image)
        .unwrap()
        .set_times(std::fs::FileTimes::new().set_modified(newer))
        .unwrap();
    server.request(
        4,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[main]}),
    );
    let changed = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(changed["params"]["status"], "error", "{changed}");
    assert_eq!(changed["params"]["stale"], false);
    assert!(changed["params"]["message"]
        .as_str()
        .unwrap()
        .contains("plot.png"));
    assert!(changed["params"]["pdfUri"].is_null());
    assert_eq!(std::fs::read(&pdf).unwrap(), old_pdf);
    std::fs::remove_file(&image).unwrap();
    server.request(
        5,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[main]}),
    );
    let deleted = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(deleted["params"]["status"], "error", "{deleted}");
    assert_eq!(deleted["params"]["stale"], false);
    assert!(deleted["params"]["pdfUri"].is_null());
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn static_graphicspath_images_changed_during_build_discard_diagnostics_without_a_recorder() {
    let script = "touch \"$1/ready\"\nwhile [ ! -f \"$1/release\" ]; do sleep 0.02; done\nprintf '%%PDF-1.4\\n' > \"$1/main.pdf\"\nprintf '%s:2: LaTeX Warning: old image.\\n' \"$2\" > \"$1/main.log\"\n";
    let (mut server, directory, main) = fake_build_server(script, false);
    std::fs::create_dir(directory.path().join("assets")).unwrap();
    let image = directory.path().join("assets/plot.png");
    std::fs::write(&image, [0, 255, 1]).unwrap();
    let source = "\\documentclass{article}\n\\graphicspath{{assets/}}\n\\includegraphics{plot}\n";
    std::fs::write(main.to_file_path().unwrap(), source).unwrap();
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
    );
    server.request(
        2,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[main]}),
    );
    let output = directory.path().join("build/latex-lsp");
    wait_for_file(&output.join("ready"));
    let modified = std::fs::metadata(&image).unwrap().modified().unwrap();
    std::fs::write(&image, [0, 255, 1, 2, 3, 4]).unwrap();
    // Fingerprints detect length changes even when a tool preserves timestamps.
    std::fs::File::open(&image)
        .unwrap()
        .set_times(std::fs::FileTimes::new().set_modified(modified))
        .unwrap();
    std::fs::write(output.join("release"), "").unwrap();
    let finished = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(finished["params"]["status"], "success", "{finished}");
    assert_eq!(finished["params"]["stale"], true, "{finished}");
    assert_eq!(finished["params"]["dependenciesCount"], 2);
    assert!(finished["params"]["message"]
        .as_str()
        .unwrap()
        .contains("diagnostics discarded"));
    server.request(3, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn conditional_files_changed_during_build_discard_diagnostics_without_file_events() {
    for (command, name, existed) in [
        ("IfFileExists", "optional.bin", false),
        ("IfFileExists", "optional.bin", true),
        ("InputIfFileExists", "optional.tex", false),
    ] {
        let script = "touch \"$1/ready\"\nwhile [ ! -f \"$1/release\" ]; do sleep 0.02; done\nprintf '%%PDF-1.4\\n' > \"$1/main.pdf\"\nprintf '%s:2: LaTeX Warning: previous file condition.\\n' \"$2\" > \"$1/main.log\"\n";
        let (mut server, directory, main) = fake_build_server(script, false);
        let target = directory.path().join(name);
        if existed {
            std::fs::write(&target, "Data.").unwrap();
        }
        let source =
            format!("\\documentclass{{article}}\n\\{command}{{{name}}}{{Found.}}{{Missing.}}\n");
        std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let output = directory.path().join("build/latex-lsp");
        wait_for_file(&output.join("ready"));
        if existed {
            std::fs::remove_file(&target).unwrap();
        } else {
            std::fs::write(&target, "New data.").unwrap();
        }
        std::fs::write(output.join("release"), "").unwrap();
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["status"], "success", "{finished}");
        assert_eq!(
            finished["params"]["stale"], true,
            "{command}, {existed}: {finished}"
        );
        server.request(3, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn conditional_first_stale_pdf_cannot_be_accepted_by_a_later_noop_build() {
    let script = "if [ ! -f \"$1/main.pdf\" ]; then\ntouch \"$1/ready\"\nwhile [ ! -f \"$1/release\" ]; do sleep 0.02; done\nprintf '%%PDF-1.4\\n' > \"$1/main.pdf\"\nfi\n";
    let (mut server, directory, main) = fake_build_server(script, false);
    let source = "\\documentclass{article}\n\\IfFileExists{optional.bin}{Found.}{Missing.}\n";
    std::fs::write(main.to_file_path().unwrap(), source).unwrap();
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
    );
    server.request(
        2,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[main]}),
    );
    let output = directory.path().join("build/latex-lsp");
    wait_for_file(&output.join("ready"));
    std::fs::write(directory.path().join("optional.bin"), "Created.").unwrap();
    std::fs::write(output.join("release"), "").unwrap();
    let stale = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(stale["params"]["status"], "success", "{stale}");
    assert_eq!(stale["params"]["stale"], true, "{stale}");
    server.request(
        3,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[main]}),
    );
    let noop = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(noop["params"]["status"], "error", "{noop}");
    assert!(
        noop["params"]["message"]
            .as_str()
            .unwrap()
            .contains("file condition changed"),
        "{noop}"
    );
    assert!(noop["params"]["pdfUri"].is_null());
    server.request(4, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn missing_include_creation_invalidates_results_and_old_pdfs_unless_the_chapter_is_excluded() {
    for (selection, stale) in [
        ("", true),
        ("\\includeonly{chapter}\n", true),
        ("\\includeonly{chapter.tex}\n", true),
        ("\\includeonly{ chapter.tex, other }\n", true),
        ("\\includeonly{other}\n", false),
        ("\\includeonly{}\n", false),
        ("\\includeonly{\\selected}\n", false),
        (
            "\\includeonly{% head, other, }\r\n chapter% tail\r\n}\r\n",
            true,
        ),
        ("\\includeonly{% chapter, }\n other% tail\n}\n", false),
        ("\\includeonly{% comment\n chapter,\\selected}\n", false),
        ("\\includeonly{% chapter\n}\n", false),
        ("\\includeonly{other}\n\\includeonly{chapter}\n", false),
    ] {
        let script = "if [ ! -f \"$1/main.pdf\" ]; then\ntouch \"$1/ready\"\nwhile [ ! -f \"$1/release\" ]; do sleep 0.02; done\nprintf '%%PDF-1.4\\n' > \"$1/main.pdf\"\nfi\n";
        let (mut server, directory, main) = fake_build_server(script, false);
        let source = format!("\\documentclass{{article}}\n{selection}\\include{{chapter}}\n");
        std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let output = directory.path().join("build/latex-lsp");
        wait_for_file(&output.join("ready"));
        std::fs::write(directory.path().join("chapter.tex"), "New chapter.").unwrap();
        std::fs::write(output.join("release"), "").unwrap();
        let first = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(first["params"]["status"], "success", "{first}");
        assert_eq!(first["params"]["stale"], stale, "{selection}: {first}");
        server.request(
            3,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let noop = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(
            noop["params"]["status"],
            if stale { "error" } else { "success" },
            "{selection}: {noop}"
        );
        if stale {
            assert!(noop["params"]["pdfUri"].is_null());
            assert!(
                noop["params"]["message"]
                    .as_str()
                    .unwrap()
                    .contains("file condition changed"),
                "{noop}"
            );
        }
        server.request(4, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

