#[test]
#[cfg(unix)]
fn bibliography_and_tex_bindings_keep_independent_scopes_and_reject_unrerun_tool_results() {
    for omit_tex in [true, false] {
        let (mut server, directory, main) = fake_synctex_server(
            "printf 'SyncTeX result begin\\nPage:1\\nx:10\\ny:20\\nSyncTeX result end\\n'\n",
        );
        let inputs = directory.path().join(".inputs");
        std::fs::create_dir(&inputs).unwrap();
        let tex_first = inputs.join("first.tex");
        let tex_second = inputs.join("second.tex");
        let tex_alias = inputs.join("chapter.tex");
        let bib_first = inputs.join("first.bib");
        let bib_second = inputs.join("second.bib");
        let bib_alias = inputs.join("refs.bib");
        for path in [&tex_first, &tex_second] {
            std::fs::write(path, "Chapter.\n").unwrap();
        }
        for path in [&bib_first, &bib_second] {
            std::fs::write(path, "@book{entry,title={Title}}\n").unwrap();
        }
        std::os::unix::fs::symlink(&tex_first, &tex_alias).unwrap();
        std::os::unix::fs::symlink(&bib_first, &bib_alias).unwrap();
        let compiler = directory.path().join("compiler.sh");
        std::fs::write(&compiler, "printf '%%PDF-1.4\\nCOMPILED\\n' > \"$1/main.pdf\"\nprintf 'SyncTeX data\\n' > \"$1/main.synctex\"\nif [ ! -f \"$1/keep-tex\" ]; then printf 'INPUT %s\\n' \"$2\" > \"$1/main.fls\"; if [ ! -f \"$1/omit-tex\" ]; then printf 'INPUT .inputs/chapter.tex\\n' >> \"$1/main.fls\"; fi; fi\nif [ ! -f \"$1/keep-bib\" ]; then printf 'BibTeX completed\\n' > \"$1/main.blg\"; if [ ! -f \"$1/omit-bib\" ]; then printf 'Database file #1: .inputs/refs.bib\\n' >> \"$1/main.blg\"; fi; fi\n").unwrap();
        server.notify(
            "workspace/didChangeConfiguration",
            json!({"settings":{"build":{"executable":"/bin/sh","arguments":[compiler,"%o","%f"]}}}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let first = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(first["params"]["status"], "success", "{first}");
        assert_eq!(first["params"]["dependenciesCount"], 3, "{first}");
        let output = directory.path().join("build/latex-lsp");
        let (
            omit,
            keep,
            removed_alias,
            removed_original,
            removed_new,
            retained_alias,
            retained_original,
            retained_new,
        ) = if omit_tex {
            (
                "omit-tex",
                "keep-bib",
                &tex_alias,
                &tex_first,
                &tex_second,
                &bib_alias,
                &bib_first,
                &bib_second,
            )
        } else {
            (
                "omit-bib",
                "keep-tex",
                &bib_alias,
                &bib_first,
                &bib_second,
                &tex_alias,
                &tex_first,
                &tex_second,
            )
        };
        std::fs::write(output.join(omit), "").unwrap();
        std::fs::write(output.join(keep), "").unwrap();
        server.request(
            3,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let reduced = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(reduced["params"]["status"], "success", "{reduced}");
        assert_eq!(reduced["params"]["stale"], false, "{reduced}");
        std::fs::remove_file(removed_alias).unwrap();
        std::os::unix::fs::symlink(removed_new, removed_alias).unwrap();
        std::fs::write(removed_original, "Unrelated old input changed.\n").unwrap();
        let forward = json!({"command":"latex.forwardSearch","arguments":[{"uri":main,"position":{"line":1,"character":0}}]});
        let valid = server.request(4, "workspace/executeCommand", forward.clone());
        assert_eq!(valid["locations"][0]["page"], 1, "{valid}");
        std::fs::remove_file(retained_alias).unwrap();
        std::os::unix::fs::symlink(retained_new, retained_alias).unwrap();
        server.request(
            5,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let stale = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(stale["params"]["status"], "success", "{stale}");
        assert_eq!(stale["params"]["stale"], true, "{stale}");
        std::fs::remove_file(retained_alias).unwrap();
        std::os::unix::fs::symlink(retained_original, retained_alias).unwrap();
        server.send(
            json!({"jsonrpc":"2.0","id":6,"method":"workspace/executeCommand","params":forward}),
        );
        let uncertain = server.until(|m| m["id"] == 6);
        assert!(
            uncertain["error"]["message"]
                .as_str()
                .is_some_and(|s| s.contains("File conditions changed")),
            "{uncertain}"
        );
        std::fs::remove_file(output.join(keep)).unwrap();
        server.request(
            7,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let rebuilt = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(rebuilt["params"]["status"], "success", "{rebuilt}");
        assert_eq!(rebuilt["params"]["stale"], false, "{rebuilt}");
        assert_eq!(
            server.request(8, "workspace/executeCommand", forward)["locations"][0]["page"],
            1
        );
        server.request(9, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn tex_only_builds_do_not_adopt_changed_bibliography_contents_or_partial_tool_logs() {
    for extension in ["bib", "bst"] {
        for partial in [false, true] {
            let (mut server, directory, main) = fake_synctex_server(
                "printf 'SyncTeX result begin\\nPage:1\\nx:10\\ny:20\\nSyncTeX result end\\n'\n",
            );
            let inputs = directory.path().join(".inputs");
            std::fs::create_dir(&inputs).unwrap();
            let bibliography = inputs.join(format!("refs.{extension}"));
            let original = "@book{entry,title={OLD}}\n";
            let replacement = "@book{entry,title={NEW}}\n";
            std::fs::write(&bibliography, original).unwrap();
            let modified = std::fs::metadata(&bibliography)
                .unwrap()
                .modified()
                .unwrap();
            let record = if extension == "bib" {
                "Database file #1:"
            } else {
                "The style file:"
            };
            let compiler = directory.path().join("compiler.sh");
            std::fs::write(&compiler, format!(
                "if [ -f \"$1/noop\" ]; then exit 0; fi\nprintf '%%PDF-1.4\\nCOMPILED\\n' > \"$1/main.pdf\"\nprintf 'SyncTeX data\\n' > \"$1/main.synctex\"\nprintf 'INPUT %s\\n' \"$2\" > \"$1/main.fls\"\nif [ ! -f \"$1/keep-bib\" ]; then printf '{record} .inputs/refs.{extension}\\n' > \"$1/main.blg\"; elif [ -f \"$1/partial\" ]; then cp \"${{2%/*}}/partial-template\" \"$1/main.blg\"; fi\nprintf '%s:2: LaTeX Warning: bibliography warning.\\n' \"$2\" > \"$1/main.log\"\n"
            )).unwrap();
            server.notify("workspace/didChangeConfiguration", json!({"settings":{"build":{"executable":"/bin/sh","arguments":[compiler,"%o","%f"]}}}));
            server.request(
                2,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let first = server.until(|m| m["method"] == "latex/buildFinished");
            assert_eq!(first["params"]["status"], "success", "{first}");
            assert_eq!(first["params"]["stale"], false, "{first}");
            let old = server.request(
                3,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":main}}),
            );
            assert!(
                old["items"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|d| d["source"] == "latex-build"),
                "{old}"
            );
            let output = directory.path().join("build/latex-lsp");
            std::fs::write(output.join("keep-bib"), "").unwrap();
            if partial {
                std::fs::write(
                    directory.path().join("partial-template"),
                    format!(
                        "{record} .inputs/refs.{extension}\n{}\n",
                        " ".repeat(9 * 1024 * 1024)
                    ),
                )
                .unwrap();
                std::fs::write(output.join("partial"), "").unwrap();
            }
            std::fs::write(&bibliography, replacement).unwrap();
            std::fs::File::open(&bibliography)
                .unwrap()
                .set_times(std::fs::FileTimes::new().set_modified(modified))
                .unwrap();
            server.request(
                4,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let reused = server.until(|m| m["method"] == "latex/buildFinished");
            assert_eq!(
                reused["params"]["status"], "success",
                "{extension}, partial={partial}: {reused}"
            );
            assert_eq!(
                reused["params"]["stale"], true,
                "{extension}, partial={partial}: {reused}"
            );
            assert_eq!(
                reused["params"]["diagnosticsTruncated"], partial,
                "{reused}"
            );
            let cleared = server.request(
                5,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":main},"previousResultId":old["resultId"]}),
            );
            assert_eq!(cleared["kind"], "full", "{cleared}");
            assert_eq!(cleared["items"], json!([]), "{cleared}");
            // Restoring the data cannot establish which contents produced this
            // new PDF; only a complete bibliography rerun can replace history.
            std::fs::write(&bibliography, original).unwrap();
            std::fs::File::open(&bibliography)
                .unwrap()
                .set_times(std::fs::FileTimes::new().set_modified(modified))
                .unwrap();
            let forward = json!({"command":"latex.forwardSearch","arguments":[{"uri":main,"position":{"line":1,"character":0}}]});
            server.send(json!({"jsonrpc":"2.0","id":6,"method":"workspace/executeCommand","params":forward}));
            let uncertain = server.until(|m| m["id"] == 6);
            assert!(
                uncertain["error"]["message"]
                    .as_str()
                    .is_some_and(|message| message.contains("File conditions changed")),
                "{uncertain}"
            );
            std::fs::write(output.join("noop"), "").unwrap();
            for id in [7, 8] {
                server.request(
                    id,
                    "workspace/executeCommand",
                    json!({"command":"latex.build","arguments":[main]}),
                );
                let noop = server.until(|m| m["method"] == "latex/buildFinished");
                assert_eq!(noop["params"]["status"], "error", "{noop}");
                assert!(noop["params"]["pdfUri"].is_null(), "{noop}");
            }
            std::fs::write(&bibliography, replacement).unwrap();
            std::fs::remove_file(output.join("noop")).unwrap();
            std::fs::remove_file(output.join("keep-bib")).unwrap();
            if partial {
                std::fs::remove_file(output.join("partial")).unwrap();
            }
            server.request(
                9,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let rebuilt = server.until(|m| m["method"] == "latex/buildFinished");
            assert_eq!(rebuilt["params"]["status"], "success", "{rebuilt}");
            assert_eq!(rebuilt["params"]["stale"], false, "{rebuilt}");
            let valid = server.request(10, "workspace/executeCommand", forward);
            assert_eq!(valid["locations"][0]["page"], 1, "{valid}");
            server.request(11, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
#[cfg(unix)]
fn known_external_bindings_track_unindexed_target_contents_and_active_retargets() {
    for extension in ["tex", "bib"] {
        for notify in [false, true] {
            let external = tempfile::tempdir().unwrap();
            let first = external.path().join(format!("first.{extension}"));
            let second = external.path().join(format!("second.{extension}"));
            let third = external.path().join(format!("third.{extension}"));
            let alias = external.path().join(format!("alias.{extension}"));
            let original = if extension == "tex" {
                "OLD \\label{old-entry}\n"
            } else {
                "@book{old-entry,title={OLD}}\n"
            };
            let replacement = if extension == "tex" {
                "NEW \\label{unindexed-entry}\n"
            } else {
                "@book{unindexed-entry,title={NEW}}\n"
            };
            std::fs::write(&first, original).unwrap();
            std::fs::write(&second, replacement).unwrap();
            std::fs::write(
                &third,
                replacement.replace("unindexed-entry", "third-entry"),
            )
            .unwrap();
            std::os::unix::fs::symlink(&first, &alias).unwrap();
            let (mut server, directory, main) = fake_synctex_server("touch queried\nprintf 'SyncTeX result begin\\nPage:1\\nx:10\\ny:20\\nSyncTeX result end\\n'\n");
            let command = if extension == "tex" {
                "input"
            } else {
                "bibliography"
            };
            let source = format!(
                "\\documentclass{{article}}\n\\def\\selected{{{}}}\\{command}{{\\selected}}\n",
                alias.display()
            );
            std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
            server.notify(
                "textDocument/didChange",
                json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
            );
            let first_uri = Url::from_file_path(&first).unwrap();
            server.notify("textDocument/didOpen", json!({"textDocument":{"uri":first_uri,"languageId":if extension=="tex" {"latex"} else {"bibtex"},"version":1,"text":original}}));
            server.request(
                0,
                "textDocument/documentSymbol",
                json!({"textDocument":{"uri":first_uri}}),
            );
            let record = if extension == "tex" {
                format!("printf 'INPUT {}\\n' >> \"$1/main.fls\"\n", alias.display())
            } else {
                format!(
                    "printf 'Database file #1: {}\\n' > \"$1/main.blg\"\n",
                    alias.display()
                )
            };
            let compiler = directory.path().join("compiler.sh");
            std::fs::write(&compiler, format!("if [ -f \"$1/noop\" ]; then exit 0; fi\nprintf '%%PDF-1.4\\nCOMPILED\\n' > \"$1/main.pdf\"\nprintf 'SyncTeX data\\n' > \"$1/main.synctex\"\nprintf 'INPUT %s\\n' \"$2\" > \"$1/main.fls\"\n{record}printf '%s:2: LaTeX Warning: dependency warning.\\n' \"$2\" > \"$1/main.log\"\nif [ -f \"$1/hold\" ]; then touch \"$1/ready\"; while [ ! -f \"$1/release\" ]; do sleep 0.02; done; fi\n")).unwrap();
            server.notify("workspace/didChangeConfiguration", json!({"settings":{"build":{"executable":"/bin/sh","arguments":[compiler,"%o","%f"]}}}));
            server.request(
                2,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let first_build = server.until(|m| m["method"] == "latex/buildFinished");
            assert_eq!(first_build["params"]["status"], "success", "{first_build}");
            std::fs::remove_file(&alias).unwrap();
            std::os::unix::fs::symlink(&second, &alias).unwrap();
            server.request(
                3,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let selected = server.until(|m| m["method"] == "latex/buildFinished");
            assert_eq!(
                selected["params"]["status"], "success",
                "{extension}: {selected}"
            );
            assert_eq!(selected["params"]["stale"], false, "{selected}");
            let symbols = server.request(4, "workspace/symbol", json!({"query":"unindexed-entry"}));
            assert_eq!(symbols, json!([]), "{symbols}");
            let forward = json!({"command":"latex.forwardSearch","arguments":[{"uri":main,"position":{"line":1,"character":0}}]});
            assert_eq!(
                server.request(5, "workspace/executeCommand", forward.clone())["locations"][0]
                    ["page"],
                1
            );
            std::fs::remove_file(directory.path().join("queried")).unwrap();
            let modified = std::fs::metadata(&second).unwrap().modified().unwrap();
            std::fs::write(&second, replacement.replace("NEW", "ALT")).unwrap();
            std::fs::File::open(&second)
                .unwrap()
                .set_times(std::fs::FileTimes::new().set_modified(modified))
                .unwrap();
            server.send(json!({"jsonrpc":"2.0","id":6,"method":"workspace/executeCommand","params":forward}));
            let rejected = server.until(|m| m["id"] == 6);
            assert!(
                rejected["error"]["message"]
                    .as_str()
                    .is_some_and(|message| message.contains("Input contents changed")),
                "{rejected}"
            );
            assert!(!directory.path().join("queried").exists());
            let output = directory.path().join("build/latex-lsp");
            std::fs::write(output.join("noop"), "").unwrap();
            for id in [7, 8] {
                server.request(
                    id,
                    "workspace/executeCommand",
                    json!({"command":"latex.build","arguments":[main]}),
                );
                let noop = server.until(|m| m["method"] == "latex/buildFinished");
                assert_eq!(noop["params"]["status"], "error", "{noop}");
                assert!(noop["params"]["pdfUri"].is_null(), "{noop}");
            }
            std::fs::write(&second, replacement).unwrap();
            std::fs::File::open(&second)
                .unwrap()
                .set_times(std::fs::FileTimes::new().set_modified(modified))
                .unwrap();
            server.request(
                91,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let restored = server.until(|m| m["method"] == "latex/buildFinished");
            assert_eq!(restored["params"]["status"], "success", "{restored}");
            assert_eq!(
                server.request(9, "workspace/executeCommand", forward.clone())["locations"][0]
                    ["page"],
                1
            );
            std::fs::remove_file(output.join("noop")).unwrap();
            // Resolve the known raw name at launch, rather than snapshotting
            // its previous target. The new target remains outside the index.
            std::fs::remove_file(&alias).unwrap();
            std::os::unix::fs::symlink(&third, &alias).unwrap();
            std::fs::write(output.join("hold"), "").unwrap();
            server.request(
                10,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            wait_for_file(&output.join("ready"));
            let modified = std::fs::metadata(&third).unwrap().modified().unwrap();
            std::fs::write(
                &third,
                replacement
                    .replace("unindexed-entry", "third-entry")
                    .replace("NEW", "ALT"),
            )
            .unwrap();
            std::fs::File::open(&third)
                .unwrap()
                .set_times(std::fs::FileTimes::new().set_modified(modified))
                .unwrap();
            if notify {
                server.notify(
                    "workspace/didChangeWatchedFiles",
                    json!({"changes":[{"uri":Url::from_file_path(&third).unwrap(),"type":2}]}),
                );
            } else {
                std::fs::write(output.join("release"), "").unwrap();
            }
            let changed = server.until(|m| m["method"] == "latex/buildFinished");
            assert_eq!(
                changed["params"]["status"],
                if notify { "cancelled" } else { "success" },
                "{changed}"
            );
            if !notify {
                assert_eq!(changed["params"]["stale"], true, "{changed}");
            }
            std::fs::write(output.join("release"), "").unwrap();
            std::fs::remove_file(output.join("hold")).unwrap();
            server.request(
                11,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let rebuilt = server.until(|m| m["method"] == "latex/buildFinished");
            assert_eq!(rebuilt["params"]["status"], "success", "{rebuilt}");
            assert_eq!(rebuilt["params"]["stale"], false, "{rebuilt}");
            let old = server.request(
                12,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":main}}),
            );
            assert!(
                old["items"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|d| d["source"] == "latex-build"),
                "{old}"
            );
            std::fs::write(
                &third,
                replacement.replace("unindexed-entry", "third-entry"),
            )
            .unwrap();
            std::fs::File::open(&third)
                .unwrap()
                .set_times(std::fs::FileTimes::new().set_modified(modified))
                .unwrap();
            server.notify(
                "workspace/didChangeWatchedFiles",
                json!({"changes":[{"uri":Url::from_file_path(&third).unwrap(),"type":2}]}),
            );
            let cleared = server.request(
                13,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":main},"previousResultId":old["resultId"]}),
            );
            assert_eq!(cleared["kind"], "full", "{cleared}");
            assert_eq!(cleared["items"], json!([]), "{cleared}");
            server.request(14, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
#[cfg(unix)]
fn compiler_input_roles_survive_open_edits_close_and_versioned_cross_file_rename() {
    for (database, extension) in [
        (true, "payload"),
        (true, "tex"),
        (true, "csv"),
        (true, "png"),
        (true, "bst"),
        (false, "bib"),
        (false, "bst"),
        (false, "png"),
    ] {
        let (mut server, directory, main) = fake_build_server_capabilities(
            "exit 1\n",
            false,
            json!({"workspace":{"workspaceEdit":{"documentChanges":true}}}),
        );
        let inputs = directory.path().join(".inputs");
        std::fs::create_dir(&inputs).unwrap();
        let physical = inputs.join(format!("physical.{extension}"));
        let alias = inputs.join(if database { "alias.bib" } else { "alias.sty" });
        let contents = if database {
            "@book{entry,title={OLD}}\n"
        } else {
            "\\newcommand{\\fromalias}{OLD}\n"
        };
        std::fs::write(&physical, contents).unwrap();
        std::os::unix::fs::symlink(&physical, &alias).unwrap();
        let data_uri = Url::from_file_path(&physical).unwrap();
        let source = if database {
            "\\documentclass{article}\n\\def\\selected{.inputs/alias}\\bibliography{\\selected}\\cite{entry}\n"
        } else {
            "\\documentclass{article}\n\\def\\selected{.inputs/alias}\\usepackage{\\selected}\\fromalias\n"
        };
        let at = latex_lsp::text::Text::new(source.into()).position(if database {
            source.find("cite{entry}").unwrap() + 6
        } else {
            source.find("\\fromalias").unwrap() + 3
        });
        std::fs::write(main.to_file_path().unwrap(), source).unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        let extra = if database {
            "printf 'Database file #1: .inputs/alias.bib\\n' > \"$1/main.blg\"\n"
        } else {
            "printf 'INPUT .inputs/alias.sty\\n' >> \"$1/main.fls\"\n"
        };
        std::fs::write(directory.path().join("compiler.sh"), format!("printf '%%PDF-1.4\\n' > \"$1/main.pdf\"\nprintf 'INPUT %s\\n' \"$2\" > \"$1/main.fls\"\n{extra}")).unwrap();
        assert_eq!(
            server.request(
                2,
                "textDocument/definition",
                json!({"textDocument":{"uri":main},"position":at})
            ),
            json!([])
        );
        server.request(
            3,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let built = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(
            built["params"]["status"], "success",
            "{database}/{extension}: {built}"
        );
        let definitions = server.request(
            4,
            "textDocument/definition",
            json!({"textDocument":{"uri":main},"position":at}),
        );
        assert_eq!(definitions[0]["uri"], data_uri.as_str(), "{definitions}");
        let references = server.request(5, "textDocument/references", json!({"textDocument":{"uri":main},"position":at,"context":{"includeDeclaration":true}}));
        assert_eq!(references.as_array().unwrap().len(), 2, "{references}");
        if database {
            let completion = server.request(
                6,
                "textDocument/completion",
                json!({"textDocument":{"uri":main},"position":at}),
            );
            assert!(
                completion
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|item| item["label"] == "entry"),
                "{completion}"
            );
        }
        // The confirmed input role wins over the physical extension and stays
        // attached to the editor buffer through full and incremental updates.
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":data_uri,"languageId":"plaintext","version":1,"text":contents}}));
        let changed = contents.replace("OLD", "NEW");
        std::fs::write(&physical, &changed).unwrap();
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":data_uri,"version":2},"contentChanges":[{"text":changed}]}));
        let new_name = if database {
            "renamedentry"
        } else {
            "renamedalias"
        };
        let renamed = server.request(
            7,
            "textDocument/rename",
            json!({"textDocument":{"uri":main},"position":at,"newName":new_name}),
        );
        let edits = renamed["documentChanges"].as_array().unwrap();
        assert_eq!(edits.len(), 2, "{renamed}");
        assert!(
            edits
                .iter()
                .any(|edit| edit["textDocument"]["uri"] == data_uri.as_str()
                    && edit["textDocument"]["version"] == 2),
            "{renamed}"
        );
        for edit in edits {
            let uri: Url = serde_json::from_value(edit["textDocument"]["uri"].clone()).unwrap();
            let path = uri.to_file_path().unwrap();
            let changes: Vec<tower_lsp::lsp_types::TextEdit> =
                serde_json::from_value(edit["edits"].clone()).unwrap();
            let text = latex_lsp::text::Text::new(std::fs::read_to_string(&path).unwrap())
                .changed(
                    changes
                        .into_iter()
                        .map(
                            |edit| tower_lsp::lsp_types::TextDocumentContentChangeEvent {
                                range: Some(edit.range),
                                range_length: None,
                                text: edit.new_text,
                            },
                        )
                        .collect(),
                )
                .unwrap()
                .source;
            std::fs::write(&path, &text).unwrap();
            server.notify(
                "textDocument/didChange",
                json!({"textDocument":{"uri":uri,"version":3},"contentChanges":[{"text":text}]}),
            );
        }
        let definitions = server.request(
            8,
            "textDocument/definition",
            json!({"textDocument":{"uri":main},"position":at}),
        );
        assert_eq!(definitions[0]["uri"], data_uri.as_str(), "{definitions}");
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":data_uri}}),
        );
        server.notify(
            "workspace/didChangeWatchedFiles",
            json!({"changes":[{"uri":data_uri,"type":2}]}),
        );
        let closed = server.request(
            9,
            "textDocument/definition",
            json!({"textDocument":{"uri":main},"position":at}),
        );
        assert_eq!(closed[0]["uri"], data_uri.as_str(), "{closed}");
        server.request(10, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn bibliography_alias_data_suffixes_do_not_bypass_external_source_index_scope() {
    for extension in ["csv", "png"] {
        let external = tempfile::tempdir().unwrap();
        let physical = external.path().join(format!("database.{extension}"));
        let alias = external.path().join("refs.bib");
        let contents = "@book{external-entry,title={Book}}\n";
        std::fs::write(&physical, contents).unwrap();
        std::os::unix::fs::symlink(&physical, &alias).unwrap();
        let (mut server, directory, main) = fake_build_server("exit 1\n", false);
        let source = format!("\\documentclass{{article}}\n\\def\\selected{{{}}}\\bibliography{{\\selected}}\\cite{{external-entry}}\n", alias.display());
        std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        std::fs::write(directory.path().join("compiler.sh"), format!("printf '%%PDF-1.4\\n' > \"$1/main.pdf\"\nprintf 'INPUT %s\\n' \"$2\" > \"$1/main.fls\"\nprintf 'Database file #1: {}\\n' > \"$1/main.blg\"\n", alias.display())).unwrap();
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let built = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(built["params"]["status"], "success", "{built}");
        assert_eq!(built["params"]["dependenciesCount"], 1, "{built}");
        assert_eq!(
            server.request(3, "workspace/symbol", json!({"query":"external-entry"})),
            json!([])
        );
        let physical_uri = Url::from_file_path(&physical).unwrap();
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":physical_uri,"languageId":"bibtex","version":1,"text":contents}}));
        server.request(
            4,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let opened = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(opened["params"]["status"], "success", "{opened}");
        assert_eq!(opened["params"]["dependenciesCount"], 2, "{opened}");
        let at = latex_lsp::text::Text::new(source.clone())
            .position(source.find("cite{external-entry}").unwrap() + 7);
        let definitions = server.request(
            5,
            "textDocument/definition",
            json!({"textDocument":{"uri":main},"position":at}),
        );
        assert_eq!(
            definitions[0]["uri"],
            physical_uri.as_str(),
            "{definitions}"
        );
        server.request(6, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn static_bibliography_alias_roles_protect_old_pdfs_without_bibliography_logs() {
    for style in [false, true] {
        let (mut server, directory, main) = fake_synctex_server(
            "printf 'SyncTeX result begin\\nPage:1\\nx:10\\ny:20\\nSyncTeX result end\\n'\n",
        );
        let database = directory.path().join("database.payload");
        let stylesheet = directory.path().join("style.tex");
        std::fs::write(&database, "@book{entry,title={OLD}}\n").unwrap();
        std::fs::write(&stylesheet, "OLD STYLE\n").unwrap();
        std::os::unix::fs::symlink(&database, directory.path().join("refs.bib")).unwrap();
        std::os::unix::fs::symlink(&stylesheet, directory.path().join("chosen.bst")).unwrap();
        let source = "\\documentclass{article}\n\\bibliographystyle{chosen}\\bibliography{refs}\\cite{entry}\n";
        std::fs::write(main.to_file_path().unwrap(), source).unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        let compiler = directory.path().join("compiler.sh");
        std::fs::write(&compiler, "if [ -f \"$1/noop\" ]; then exit 0; fi\nprintf '%%PDF-1.4\\nCOMPILED\\n' > \"$1/main.pdf\"\nprintf 'SyncTeX data\\n' > \"$1/main.synctex\"\nprintf 'INPUT %s\\n' \"$2\" > \"$1/main.fls\"\n").unwrap();
        server.notify(
            "workspace/didChangeConfiguration",
            json!({"settings":{"build":{"executable":"/bin/sh","arguments":[compiler,"%o","%f"]}}}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let built = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(built["params"]["status"], "success", "{built}");
        let input = if style { &stylesheet } else { &database };
        let original = std::fs::read_to_string(input).unwrap();
        let modified = std::fs::metadata(input).unwrap().modified().unwrap();
        std::fs::write(input, original.replace("OLD", "NEW")).unwrap();
        std::fs::File::open(input)
            .unwrap()
            .set_times(std::fs::FileTimes::new().set_modified(modified))
            .unwrap();
        let forward = json!({"command":"latex.forwardSearch","arguments":[{"uri":main,"position":{"line":1,"character":0}}]});
        server.send(
            json!({"jsonrpc":"2.0","id":3,"method":"workspace/executeCommand","params":forward}),
        );
        let rejected = server.until(|m| m["id"] == 3);
        assert!(
            rejected["error"]["message"]
                .as_str()
                .is_some_and(|message| message.contains("Input contents changed")),
            "{rejected}"
        );
        std::fs::write(directory.path().join("build/latex-lsp/noop"), "").unwrap();
        server.request(
            4,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let noop = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(noop["params"]["status"], "error", "{noop}");
        assert!(noop["params"]["pdfUri"].is_null(), "{noop}");
        server.request(5, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
fn environment_linked_editing_tracks_incremental_changes_and_validates_positions_over_stdio() {
    use latex_lsp::text::Text;
    let mut server = Server::start();
    let uri = Url::parse("file:///linked-editing-protocol/main.tex").unwrap();
    let alias = "file:///linked-editing-protocol/%6dain.tex";
    let initialized = server.request(1, "initialize", json!({"processId":null,"capabilities":{"textDocument":{"linkedEditingRange":{"dynamicRegistration":false}}}}));
    assert_eq!(
        initialized["capabilities"]["linkedEditingRangeProvider"],
        true
    );
    server.notify("initialized", json!({}));
    let source = "😀 \\begin{quote}\r\n\\begin{quote}Inner\\end{quote}\r\n\\end{quote}\r\n";
    let text = Text::new(source.into());
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":7,"text":source}}),
    );
    let begin = source.find("\n\\begin{quote}").unwrap() + 1 + "\\begin{".len();
    let end = source.find("\\end{quote}").unwrap() + "\\end{".len();
    let ranges = [text.range(begin, begin + 5), text.range(end, end + 5)];
    let result = server.request(
        2,
        "textDocument/linkedEditingRange",
        json!({"textDocument":{"uri":alias},"position":text.position(begin + 2)}),
    );
    assert_eq!(result["ranges"], json!(ranges));
    assert!(result["wordPattern"].as_str().is_some());
    server.notify("textDocument/didChange", json!({"textDocument":{"uri":alias,"version":8},"contentChanges":[{"range":ranges[1],"text":"center"},{"range":ranges[0],"text":"center"}]}));
    let changed = text
        .changed(vec![
            tower_lsp::lsp_types::TextDocumentContentChangeEvent {
                range: Some(ranges[1]),
                range_length: None,
                text: "center".into(),
            },
            tower_lsp::lsp_types::TextDocumentContentChangeEvent {
                range: Some(ranges[0]),
                range_length: None,
                text: "center".into(),
            },
        ])
        .unwrap();
    let begin = changed.source.find("\\begin{center}").unwrap() + "\\begin{".len();
    let end = changed.source.find("\\end{center}").unwrap() + "\\end{".len();
    let updated = server.request(
        3,
        "textDocument/linkedEditingRange",
        json!({"textDocument":{"uri":uri},"position":changed.position(end + 2)}),
    );
    assert_eq!(
        updated["ranges"],
        json!([changed.range(begin, begin + 6), changed.range(end, end + 6)])
    );
    let missing = server.request(4, "textDocument/linkedEditingRange", json!({"textDocument":{"uri":"file:///linked-editing-protocol/missing.tex"},"position":{"line":0,"character":0}}));
    assert!(missing.is_null());
    server.send(json!({"jsonrpc":"2.0","id":5,"method":"textDocument/linkedEditingRange","params":{"textDocument":{"uri":uri},"position":{"line":0,"character":1}}}));
    let invalid = server.until(|message| message["id"] == 5);
    assert_eq!(invalid["error"]["code"], -32602);
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn environment_linked_editing_tracks_project_aliases_macro_data_and_input_changes() {
    use latex_lsp::text::Text;
    let directory = tempfile::tempdir().unwrap();
    let root = directory.path();
    let main = Url::from_file_path(root.join("main.tex")).unwrap();
    let defs = Url::from_file_path(root.join("aliases.sty")).unwrap();
    let child = Url::from_file_path(root.join("child.tex")).unwrap();
    let aliases = r"\def\start{\begin}\def\finish{\end}\newcommand{\ignore}[1]{}";
    let source = "\\documentclass{article}\\usepackage{aliases}\\begin{document}😀 \\csuse{start}{% before\r\nquote% after\r\n}\\input{child}\\csname finish\\endcsname{quote}\\ignore{\\begin{panel}Fake\\end{panel}}\\end{document}";
    for (name, text) in [
        ("main.tex", source),
        ("aliases.sty", aliases),
        ("child.tex", "Body"),
    ] {
        std::fs::write(root.join(name), text).unwrap();
    }
    let text = Text::new(source.into());
    let ranges: Vec<_> = source
        .match_indices("quote")
        .map(|(at, _)| text.range(at, at + 5))
        .collect();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":1,"text":source}}),
    );
    let request = json!({"textDocument":{"uri":main},"position":ranges[0].start});
    let linked = server.request(2, "textDocument/linkedEditingRange", request.clone());
    assert_eq!(linked["ranges"], json!(ranges));
    let fake = server.request(3, "textDocument/linkedEditingRange", json!({"textDocument":{"uri":main},"position":text.position(source.find("panel").unwrap())}));
    assert!(fake.is_null(), "{fake}");
    server.notify("textDocument/didOpen", json!({"textDocument":{"uri":defs,"languageId":"latex","version":1,"text":r"\newcommand{\start}[1]{#1}\newcommand{\finish}[1]{#1}\newcommand{\ignore}[1]{}"}}));
    assert!(server
        .request(4, "textDocument/linkedEditingRange", request.clone())
        .is_null());
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":defs,"version":2},"contentChanges":[{"text":aliases}]}),
    );
    assert_eq!(
        server.request(5, "textDocument/linkedEditingRange", request.clone())["ranges"],
        json!(ranges)
    );
    server.notify("textDocument/didOpen", json!({"textDocument":{"uri":child,"languageId":"latex","version":1,"text":r"\end{quote}\begin{quote}"}}));
    assert!(server
        .request(6, "textDocument/linkedEditingRange", request.clone())
        .is_null());
    server.notify(
        "textDocument/didClose",
        json!({"textDocument":{"uri":child}}),
    );
    assert_eq!(
        server.request(7, "textDocument/linkedEditingRange", request)["ranges"],
        json!(ranges)
    );
    server.request(8, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[ignore = "requires pdflatex and xelatex"]
fn linked_environment_alias_edits_compile_over_stdio_with_native_engines() {
    use latex_lsp::text::Text;
    use tower_lsp::lsp_types::{LinkedEditingRanges, TextDocumentContentChangeEvent};
    for engine in ["pdflatex", "xelatex"] {
        for (begin, end) in [
            (r"\start", r"\finish"),
            (r"\csuse{start}", r"\csname finish\endcsname"),
        ] {
            let directory = tempfile::tempdir().unwrap();
            let root = directory.path();
            let main = Url::from_file_path(root.join("main.tex")).unwrap();
            let source = format!("\\documentclass{{article}}\\usepackage{{etoolbox,aliases}}\\begin{{document}}{begin}{{% before\nquote% keep\n}}Native body.{end}{{quote}}\\end{{document}}\n");
            std::fs::write(root.join("main.tex"), &source).unwrap();
            std::fs::write(
                root.join("aliases.sty"),
                "\\def\\start{\\begin}\\def\\finish{\\end}\n",
            )
            .unwrap();
            let mut server = Server::start();
            server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(root).unwrap(),"capabilities":{},"initializationOptions":{"build":{"executable":engine,"arguments":["-interaction=nonstopmode","-halt-on-error","-recorder","-output-directory=%o","%f"]}}}));
            server.notify("initialized", json!({}));
            server.notify(
                "textDocument/didOpen",
                json!({"textDocument":{"uri":main,"languageId":"latex","version":1,"text":source}}),
            );
            let text = Text::new(source.clone());
            let found = server.request(2, "textDocument/linkedEditingRange", json!({"textDocument":{"uri":main},"position":text.position(source.find("quote").unwrap())}));
            let linked: LinkedEditingRanges = serde_json::from_value(found).unwrap();
            assert_eq!(linked.ranges.len(), 2);
            let changes: Vec<_> = linked
                .ranges
                .into_iter()
                .rev()
                .map(|range| TextDocumentContentChangeEvent {
                    range: Some(range),
                    range_length: None,
                    text: "center".into(),
                })
                .collect();
            let changed = text.changed(changes.clone()).unwrap();
            assert_eq!(changed.source, source.replace("quote", "center"));
            server.notify(
                "textDocument/didChange",
                json!({"textDocument":{"uri":main,"version":2},"contentChanges":changes}),
            );
            std::fs::write(root.join("main.tex"), &changed.source).unwrap();
            server.notify("textDocument/didSave", json!({"textDocument":{"uri":main}}));
            let started = server.request(
                3,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let finished = server.until(|message| {
                message["method"] == "latex/buildFinished"
                    && message["params"]["buildId"] == started["buildId"]
            });
            assert_eq!(
                finished["params"]["status"], "success",
                "{engine}/{begin}: {finished}"
            );
            assert_eq!(finished["params"]["errorsCount"], 0, "{finished}");
            assert_eq!(finished["params"]["stale"], false, "{finished}");
            assert!(root.join("build/latex-lsp/main.pdf").is_file());
            server.request(4, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
fn color_picker_edits_track_incremental_changes_and_validate_context_over_stdio() {
    use latex_lsp::text::Text;
    use tower_lsp::lsp_types::{ColorPresentation, TextDocumentContentChangeEvent};
    let mut server = Server::start();
    let uri = Url::parse("file:///color-protocol/main.tex").unwrap();
    let alias = "file:///color-protocol/%6dain.tex";
    let initialized = server.request(1, "initialize", json!({"processId":null,"capabilities":{"textDocument":{"colorProvider":{"dynamicRegistration":false}}}}));
    assert_eq!(initialized["capabilities"]["colorProvider"], true);
    server.notify("initialized", json!({}));
    let source = "😀 \\textcolor[gray]{ .5 }{Body}\r\n% \\color[rgb]{1,0,0}\r\n\\verb|\\color[rgb]{1,0,0}|\r\n";
    let text = Text::new(source.into());
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":7,"text":source}}),
    );
    let found = server.request(
        2,
        "textDocument/documentColor",
        json!({"textDocument":{"uri":alias}}),
    );
    let at = source.find(".5").unwrap();
    let range = text.range(at, at + 2);
    assert_eq!(
        found,
        json!([{"range":range,"color":{"red":0.5,"green":0.5,"blue":0.5,"alpha":1.0}}])
    );
    let green = json!({"red":0.0,"green":1.0,"blue":0.0,"alpha":1.0});
    let presented = server.request(
        3,
        "textDocument/colorPresentation",
        json!({"textDocument":{"uri":alias},"range":range,"color":green}),
    );
    let mut presentations: Vec<ColorPresentation> = serde_json::from_value(presented).unwrap();
    assert_eq!(presentations.len(), 1);
    let presentation = presentations.pop().unwrap();
    assert_eq!(presentation.text_edit.as_ref().unwrap().range, range);
    let mut edits = presentation.additional_text_edits.unwrap();
    assert_eq!(edits.len(), 1);
    edits.extend(presentation.text_edit);
    edits.sort_by_key(|edit| std::cmp::Reverse(edit.range.start));
    let changes: Vec<_> = edits
        .into_iter()
        .map(|edit| TextDocumentContentChangeEvent {
            range: Some(edit.range),
            range_length: None,
            text: edit.new_text,
        })
        .collect();
    let changed = text.changed(changes.clone()).unwrap();
    assert_eq!(
        changed.source,
        source.replace("[gray]{ .5 }", "[rgb]{ 0,1,0 }")
    );
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":alias,"version":8},"contentChanges":changes}),
    );
    let updated = server.request(
        4,
        "textDocument/documentColor",
        json!({"textDocument":{"uri":uri}}),
    );
    assert_eq!(updated.as_array().unwrap().len(), 1);
    assert_eq!(updated[0]["color"], green);
    let stale = server.request(
        5,
        "textDocument/colorPresentation",
        json!({"textDocument":{"uri":uri},"range":range,"color":green}),
    );
    assert_eq!(stale, json!([]));
    let transparent = server.request(6, "textDocument/colorPresentation", json!({"textDocument":{"uri":uri},"range":updated[0]["range"],"color":{"red":0,"green":1,"blue":0,"alpha":0.5}}));
    assert_eq!(transparent, json!([]));
    for (id, range) in [
        (
            7,
            json!({"start":{"line":0,"character":1},"end":{"line":0,"character":2}}),
        ),
        (
            8,
            json!({"start":{"line":99,"character":0},"end":{"line":99,"character":2}}),
        ),
        (
            9,
            json!({"start":{"line":0,"character":10},"end":{"line":0,"character":9}}),
        ),
    ] {
        server.send(json!({"jsonrpc":"2.0","id":id,"method":"textDocument/colorPresentation","params":{"textDocument":{"uri":uri},"range":range,"color":green}}));
        let invalid = server.until(|message| message["id"] == id);
        assert_eq!(invalid["error"]["code"], -32602, "{invalid}");
    }
    let missing = server.request(
        10,
        "textDocument/documentColor",
        json!({"textDocument":{"uri":"file:///color-protocol/missing.tex"}}),
    );
    assert_eq!(missing, json!([]));
    let missing = server.request(11, "textDocument/colorPresentation", json!({"textDocument":{"uri":"file:///color-protocol/missing.tex"},"range":range,"color":green}));
    assert_eq!(missing, json!([]));
    server.request(12, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn missing_bibliography_databases_use_confirmed_project_sources_and_versioned_corrections() {
    use latex_lsp::text::Text;
    for (name, uncertain, truncated) in [
        ("settings.tex", false, false),
        ("settings.sty", false, false),
        ("settings.cls", false, false),
        ("../shared/settings.tex", false, false),
        ("settings.tex", true, false),
        ("settings.tex", false, true),
    ] {
        for pull in [false, true] {
            let directory = tempfile::tempdir().unwrap();
            let project = directory.path().join("project");
            std::fs::create_dir(&project).unwrap();
            std::fs::create_dir(directory.path().join("shared")).unwrap();
            let main_path = project.join("main.tex");
            let settings_path = project.join(name);
            let system_path = directory.path().join("system.sty");
            let main = Url::from_file_path(&main_path).unwrap();
            let source = "\\bibliography{first,% 😀 before,\r\n re ffs.bib% after,\r\n,second}\r\n";
            std::fs::write(&settings_path, source).unwrap();
            let settings = Url::from_file_path(settings_path.canonicalize().unwrap()).unwrap();
            std::fs::write(project.join("unread.tex"), source).unwrap();
            std::fs::write(project.join("refs.bib"), "@book{one,title={Title}}\n").unwrap();
            // A system package implementation is not a user declaration;
            // local .sty/.cls sources and indexed external inputs still are.
            std::fs::write(
                &system_path,
                r"\renewcommand{\bibliography}[1]{}\bibliography{#1}",
            )
            .unwrap();
            let main_source = format!(
                "\\documentclass{{article}}\n\\input{{{name}}}\n{}",
                if uncertain {
                    r"\bibliography{\chosen}"
                } else {
                    ""
                }
            );
            std::fs::write(&main_path, &main_source).unwrap();
            let script = format!(
                r#"printf '(./main.tex\n(./{name})\n({system})\n)\n{trailer}' > "$1/main.log"
printf 'PWD {project}\nINPUT {main}\nINPUT {settings}\nINPUT {system}\n' > "$1/main.fls"
printf "I couldn't open database file reffs.bib\n---line 3 of file main.aux\n" > "$1/main.blg"
exit 1
"#,
                system = system_path.display(),
                project = project.display(),
                main = main_path.display(),
                settings = settings_path.display(),
                trailer = if truncated {
                    "[latex-lsp: middle of compiler output omitted]"
                } else {
                    ""
                }
            );
            let compiler = project.join("compiler.sh");
            std::fs::write(&compiler, script).unwrap();
            let mut server = Server::start();
            let mut capabilities = json!({"workspace":{"workspaceEdit":{"documentChanges":true}},"textDocument":{"codeAction":{"codeActionLiteralSupport":{"codeActionKind":{"valueSet":["quickfix"]}}}}});
            if pull {
                capabilities["textDocument"]["diagnostic"] = json!({});
            }
            server.request(1,"initialize",json!({"processId":null,"rootUri":Url::from_directory_path(&project).unwrap(),"capabilities":capabilities,"initializationOptions":{"build":{"executable":"/bin/sh","arguments":[compiler,"%o","%f"]}}}));
            server.notify("initialized", json!({}));
            for (uri, text) in [(&main, main_source.as_str()), (&settings, source)] {
                server.notify("textDocument/didOpen",json!({"textDocument":{"uri":uri,"languageId":"latex","version":7,"text":text}}));
            }
            server.request(
                2,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let finished = server.until(|message| message["method"] == "latex/buildFinished");
            assert_eq!(finished["params"]["status"], "error", "{finished}");
            assert_eq!(finished["params"]["diagnosticsTruncated"], truncated);
            let destination = if uncertain || truncated {
                &main
            } else {
                &settings
            };
            let diagnostics = if pull {
                server.request(
                    3,
                    "textDocument/diagnostic",
                    json!({"textDocument":{"uri":destination}}),
                )["items"]
                    .clone()
            } else {
                server.until(|message| {
                    message["method"] == "textDocument/publishDiagnostics"
                        && message["params"]["uri"] == destination.as_str()
                        && message["params"]["diagnostics"]
                            .as_array()
                            .is_some_and(|items| {
                                items
                                    .iter()
                                    .any(|item| item["code"] == "missing-bibliography-database")
                            })
                })["params"]["diagnostics"]
                    .clone()
            };
            let diagnostic = diagnostics
                .as_array()
                .unwrap()
                .iter()
                .find(|item| item["code"] == "missing-bibliography-database")
                .unwrap();
            if uncertain || truncated {
                assert_eq!(diagnostic["data"]["unresolvedSource"], true);
            } else {
                let start = source.find("re ffs.bib").unwrap();
                assert_eq!(
                    diagnostic["range"],
                    json!(Text::new(source.into()).range(start, start + "re ffs.bib".len()))
                );
                assert_eq!(
                    diagnostic["data"],
                    json!({"file":"reffs.bib","bibliographyCommand":"bibliography"})
                );
            }
            let params = json!({"textDocument":{"uri":destination},"range":diagnostic["range"],"context":{"diagnostics":[diagnostic],"only":["quickfix"]}});
            let actions = server.request(4, "textDocument/codeAction", params.clone());
            if uncertain || truncated {
                assert_eq!(actions, json!([]));
            } else {
                assert_eq!(
                    actions.as_array().unwrap().len(),
                    1,
                    "{name}, pull={pull}: {actions}"
                );
                assert_eq!(
                    actions[0]["edit"]["documentChanges"][0]["textDocument"],
                    json!({"uri":settings,"version":7})
                );
                assert_eq!(
                    actions[0]["edit"]["documentChanges"][0]["edits"],
                    json!([{"range":diagnostic["range"],"newText":"refs.bib"}])
                );
                server.notify("textDocument/didChange",json!({"textDocument":{"uri":settings,"version":8},"contentChanges":[{"text":source.replace("re ffs.bib","refs.bib")}]}));
                assert_eq!(
                    server.request(5, "textDocument/codeAction", params),
                    json!([])
                );
            }
            server.request(6, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
#[cfg(unix)]
fn default_latexmk_missing_database_warnings_offer_fixes_without_hiding_native_errors() {
    use std::os::unix::fs::PermissionsExt;
    for (program, native) in [
        ("latexmk", false),
        ("latexmk", true),
        ("other-driver", false),
    ] {
        for pull in [false, true] {
            let script = format!(
                r#"printf '%%PDF-1.4\n' > "$1/main.pdf"
printf '(./main.tex\n(./settings.tex)\n)\n' > "$1/main.log"
printf 'PWD %s\nINPUT %s/main.tex\nINPUT %s/settings.tex\n' "$PWD" "$PWD" "$PWD" > "$1/main.fls"
{native_log}
printf "Latexmk: Getting log file '%s/main.log'\nLatexmk: Found bibliography file(s):\n  first.bib\n  reffs.bib\nBib file(s) not found in search path:\n  reffs.bib\nLatexmk: All targets are up-to-date\n" "$1"
exit {exit}
"#,
                native_log = if native {
                    "printf \"I couldn't open database file reffs.bib\\n---line 3 of file main.aux\\n\" > \"$1/main.blg\""
                } else {
                    ""
                },
                exit = if native { 1 } else { 0 }
            );
            let mut capabilities = json!({"workspace":{"workspaceEdit":{"documentChanges":true}},"textDocument":{"codeAction":{"codeActionLiteralSupport":{"codeActionKind":{"valueSet":["quickfix"]}}}}});
            if pull {
                capabilities["textDocument"]["diagnostic"] = json!({});
            }
            let (mut server, directory, main) =
                fake_build_server_capabilities(&script, false, capabilities);
            let root = directory.path();
            let executable = root.join(program);
            std::fs::write(&executable, script).unwrap();
            std::fs::set_permissions(&executable, std::fs::Permissions::from_mode(0o755)).unwrap();
            // The configured executable is invoked directly.
            let bytes = std::fs::read(&executable).unwrap();
            std::fs::write(
                &executable,
                [b"#!/bin/sh\n".as_slice(), bytes.as_slice()].concat(),
            )
            .unwrap();
            std::fs::write(root.join("refs.bib"), "@book{one,title={Title}}\n").unwrap();
            let settings = Url::from_file_path(root.join("settings.tex")).unwrap();
            let source = "\\bibliography{first,% before\r\n re ffs.bib% after\r\n}\r\n";
            std::fs::write(settings.to_file_path().unwrap(), source).unwrap();
            let main_source = "\\documentclass{article}\n\\input{settings}\n";
            std::fs::write(main.to_file_path().unwrap(), main_source).unwrap();
            server.notify("textDocument/didChange",json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":main_source}]}));
            server.notify("textDocument/didOpen",json!({"textDocument":{"uri":settings,"languageId":"latex","version":7,"text":source}}));
            server.notify(
                "workspace/didChangeConfiguration",
                json!({"settings":{"build":{"executable":executable,"arguments":["%o","%f"]}}}),
            );
            server.request(
                2,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let finished = server.until(|message| message["method"] == "latex/buildFinished");
            assert_eq!(
                finished["params"]["status"],
                if native { "error" } else { "success" },
                "{finished}"
            );
            if program == "other-driver" {
                assert_eq!(finished["params"]["diagnosticsCount"], 0, "{finished}");
            } else {
                assert_eq!(finished["params"]["diagnosticsCount"], 1, "{finished}");
                assert_eq!(
                    finished["params"]["errorsCount"],
                    if native { 1 } else { 0 }
                );
                assert_eq!(
                    finished["params"]["warningsCount"],
                    if native { 0 } else { 1 }
                );
                let diagnostics = if pull {
                    server.request(
                        3,
                        "textDocument/diagnostic",
                        json!({"textDocument":{"uri":settings}}),
                    )["items"]
                        .clone()
                } else {
                    server.until(|message| {
                        message["method"] == "textDocument/publishDiagnostics"
                            && message["params"]["uri"] == settings.as_str()
                            && message["params"]["diagnostics"]
                                .as_array()
                                .is_some_and(|items| {
                                    items
                                        .iter()
                                        .any(|item| item["code"] == "missing-bibliography-database")
                                })
                    })["params"]["diagnostics"]
                        .clone()
                };
                let diagnostic = diagnostics
                    .as_array()
                    .unwrap()
                    .iter()
                    .find(|item| item["code"] == "missing-bibliography-database")
                    .unwrap();
                assert_eq!(diagnostic["severity"], if native { 1 } else { 2 });
                assert_eq!(
                    diagnostic["data"],
                    json!({"file":"reffs.bib","bibliographyCommand":"bibliography"})
                );
                let actions=server.request(4,"textDocument/codeAction",json!({"textDocument":{"uri":settings},"range":diagnostic["range"],"context":{"diagnostics":[diagnostic],"only":["quickfix"]}}));
                assert_eq!(actions.as_array().unwrap().len(), 1, "{actions}");
                assert_eq!(
                    actions[0]["edit"]["documentChanges"][0]["textDocument"],
                    json!({"uri":settings,"version":7})
                );
                assert_eq!(
                    actions[0]["edit"]["documentChanges"][0]["edits"][0]["newText"],
                    "refs.bib"
                );
            }
            server.request(5, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
#[cfg(unix)]
fn bibliography_files_created_during_compilation_discard_or_cancel_obsolete_missing_errors() {
    use std::os::unix::fs::symlink;
    for (command, extension, role) in [
        ("bibliography", "bib", "database"),
        ("nobibliography", "bib", "database"),
        ("bibliographystyle", "bst", "style"),
    ] {
        for explicit in [false, true] {
            for (event, alias) in [(false, false), (true, false), (false, true), (true, true)] {
                let stem = if alias { "alias/missing" } else { "db/missing" };
                let argument = format!(
                    "{stem}{}",
                    if explicit {
                        format!(".{extension}")
                    } else {
                        String::new()
                    }
                );
                let reported = if role == "style" {
                    format!("{argument}.bst")
                } else {
                    format!("{stem}.bib")
                };
                let script = format!(
                    r#"printf '(./main.tex\n)\n' > "$1/main.log"
printf 'PWD %s\nINPUT %s/main.tex\n' "$PWD" "$PWD" > "$1/main.fls"
printf "I couldn't open {role} file {reported}\n---line 2 of file main.aux\n" > "$1/main.blg"
touch "$1/ready"
while [ ! -f "$1/release" ]; do sleep 0.02; done
exit 1
"#
                );
                let (mut server, directory, main) = fake_build_server_capabilities(
                    &script,
                    false,
                    json!({"textDocument":{"diagnostic":{}}}),
                );
                let external = tempfile::tempdir().unwrap();
                let physical = if alias {
                    symlink(external.path(), directory.path().join("alias")).unwrap();
                    external.path().join(format!("missing.{extension}"))
                } else {
                    std::fs::create_dir(directory.path().join("db")).unwrap();
                    directory.path().join(format!("db/missing.{extension}"))
                };
                let source = format!("\\documentclass{{article}}\n\\{command}{{{argument}}}\n");
                std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
                server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}));
                server.request(
                    2,
                    "workspace/executeCommand",
                    json!({"command":"latex.build","arguments":[main]}),
                );
                let output = directory.path().join("build/latex-lsp");
                let deadline = std::time::Instant::now() + Duration::from_secs(5);
                while !output.join("ready").exists() {
                    assert!(
                        std::time::Instant::now() < deadline,
                        "compiler did not start"
                    );
                    std::thread::sleep(Duration::from_millis(10));
                }
                std::fs::write(
                    &physical,
                    if extension == "bib" {
                        "@book{one,title={Title}}\n"
                    } else {
                        "READ\n"
                    },
                )
                .unwrap();
                if event {
                    // Report the physical path outside the workspace when the
                    // declaration uses a directory alias inside the project.
                    server.notify("workspace/didChangeWatchedFiles", json!({"changes":[{"uri":Url::from_file_path(&physical).unwrap(),"type":1}]}));
                    server.request(
                        3,
                        "textDocument/documentSymbol",
                        json!({"textDocument":{"uri":main}}),
                    );
                }
                std::fs::write(output.join("release"), "").unwrap();
                let finished = server.until(|message| message["method"] == "latex/buildFinished");
                if event {
                    assert_eq!(
                        finished["params"]["status"], "cancelled",
                        "{command} explicit={explicit} alias={alias}: {finished}"
                    );
                } else {
                    assert_eq!(finished["params"]["status"], "error", "{finished}");
                    assert_eq!(
                        finished["params"]["stale"], true,
                        "{command} explicit={explicit} alias={alias}: {finished}"
                    );
                }
                let diagnostics = server.request(
                    4,
                    "textDocument/diagnostic",
                    json!({"textDocument":{"uri":main}}),
                );
                assert!(
                    !diagnostics["items"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .any(|item| item["code"] == "missing-bibliography-database"
                            || item["code"] == "missing-bibliography-style"),
                    "{diagnostics}"
                );
                server.request(5, "shutdown", Value::Null);
                server.notify("exit", Value::Null);
                server.wait_exit(0);
            }
        }
    }
}

#[test]
#[cfg(unix)]
fn first_static_bibliography_alias_retargets_invalidate_builds_without_prior_tool_history() {
    use std::os::unix::fs::symlink;
    for (command, extension) in [
        ("bibliography", "bib"),
        ("nobibliography", "bib"),
        ("bibliographystyle", "bst"),
    ] {
        for explicit in [false, true] {
            let argument = format!(
                "alias{}",
                if explicit {
                    format!(".{extension}")
                } else {
                    String::new()
                }
            );
            let metadata = if extension == "bib" {
                "Database file #1: alias.bib".to_string()
            } else {
                format!("The style file: {argument}.bst")
            };
            let script = format!(
                r#"printf '(./main.tex\n)\n' > "$1/main.log"
printf 'PWD %s\nINPUT %s/main.tex\n' "$PWD" "$PWD" > "$1/main.fls"
printf '%s\n' '{metadata}' > "$1/main.blg"
touch "$1/ready"
while [ ! -f "$1/release" ]; do sleep 0.02; done
printf '%%PDF-1.4\n' > "$1/main.pdf"
"#
            );
            let (mut server, directory, main) = fake_build_server(&script, false);
            let root = directory.path();
            for name in ["old", "new"] {
                std::fs::write(
                    root.join(format!("{name}.{extension}")),
                    if extension == "bib" {
                        format!("@book{{{name},title={{Title}}}}\n")
                    } else {
                        "READ\n".into()
                    },
                )
                .unwrap();
            }
            let alias = root.join(format!("alias.{extension}"));
            symlink(root.join(format!("old.{extension}")), &alias).unwrap();
            let source = format!("\\documentclass{{article}}\n\\{command}{{{argument}}}\n");
            std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
            server.notify(
                "textDocument/didChange",
                json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
            );
            server.request(
                2,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let output = root.join("build/latex-lsp");
            let deadline = std::time::Instant::now() + Duration::from_secs(5);
            while !output.join("ready").exists() {
                assert!(std::time::Instant::now() < deadline);
                std::thread::sleep(Duration::from_millis(10));
            }
            std::fs::remove_file(&alias).unwrap();
            symlink(root.join(format!("new.{extension}")), &alias).unwrap();
            std::fs::write(output.join("release"), "").unwrap();
            let finished = server.until(|message| message["method"] == "latex/buildFinished");
            assert_eq!(finished["params"]["status"], "success", "{finished}");
            assert_eq!(
                finished["params"]["stale"], true,
                "{command} explicit={explicit}: {finished}"
            );
            server.request(3, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
#[cfg(unix)]
fn loader_files_created_during_compilation_discard_or_cancel_obsolete_missing_errors() {
    use std::os::unix::fs::symlink;
    for (command, extension, code) in [
        ("usepackage", "sty", "missing-package"),
        ("RequirePackage", "sty", "missing-package"),
        ("RequirePackageWithOptions", "sty", "missing-package"),
        ("documentclass", "cls", "missing-class"),
        ("LoadClass", "cls", "missing-class"),
        ("LoadClassWithOptions", "cls", "missing-class"),
    ] {
        for explicit in [false, true] {
            for alias in [false, true] {
                for change in ["none", "silent", "event"] {
                    let stem = if alias {
                        "alias/missing"
                    } else {
                        "local/missing"
                    };
                    let argument = format!(
                        "{stem}{}",
                        if explicit {
                            format!(".{extension}")
                        } else {
                            String::new()
                        }
                    );
                    let reported = format!("{argument}.{extension}");
                    let script = r#"cp diagnostic.log "$1/main.log"
printf 'PWD %s\nINPUT %s/main.tex\n' "$PWD" "$PWD" > "$1/main.fls"
touch "$1/ready"
while [ ! -f "$1/release" ]; do sleep 0.02; done
exit 1
"#;
                    let (mut server, directory, main) = fake_build_server_capabilities(
                        script,
                        false,
                        json!({"textDocument":{"diagnostic":{}}}),
                    );
                    let external = tempfile::tempdir().unwrap();
                    let parent = if alias {
                        symlink(external.path(), directory.path().join("alias")).unwrap();
                        external.path().to_path_buf()
                    } else {
                        let parent = directory.path().join("local");
                        std::fs::create_dir(&parent).unwrap();
                        parent
                    };
                    let physical = parent.join(format!(
                        "missing{}.{extension}",
                        if explicit {
                            format!(".{extension}")
                        } else {
                            String::new()
                        }
                    ));
                    let prefix = if extension == "sty" {
                        "\\documentclass{article}\n"
                    } else {
                        ""
                    };
                    let line = if extension == "sty" { 2 } else { 1 };
                    let source = format!("{prefix}\\{command}{{{argument}}}\\begin{{document}}\nExpected.\\end{{document}}\n");
                    std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
                    std::fs::write(directory.path().join("diagnostic.log"), format!("(./main.tex\n! LaTeX Error: File `{reported}' not found.\n\nType X to quit or <RETURN> to proceed,\nor enter new name.\n\nEnter file name:\n! Emergency stop.\n<read *>\n\nl.{line} \\{command}{{{argument}}}\\begin\n")).unwrap();
                    server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}));
                    server.request(
                        2,
                        "workspace/executeCommand",
                        json!({"command":"latex.build","arguments":[main]}),
                    );
                    let output = directory.path().join("build/latex-lsp");
                    let deadline = std::time::Instant::now() + Duration::from_secs(5);
                    while !output.join("ready").exists() {
                        assert!(
                            std::time::Instant::now() < deadline,
                            "compiler did not start"
                        );
                        std::thread::sleep(Duration::from_millis(10));
                    }
                    if change != "none" {
                        std::fs::write(&physical, "\\endinput\n").unwrap();
                    }
                    if change == "event" {
                        server.notify("workspace/didChangeWatchedFiles", json!({"changes":[{"uri":Url::from_file_path(&physical).unwrap(),"type":1}]}));
                        server.request(
                            3,
                            "textDocument/documentSymbol",
                            json!({"textDocument":{"uri":main}}),
                        );
                    }
                    std::fs::write(output.join("release"), "").unwrap();
                    let finished =
                        server.until(|message| message["method"] == "latex/buildFinished");
                    if change == "event" {
                        assert_eq!(
                            finished["params"]["status"], "cancelled",
                            "{command} explicit={explicit} alias={alias}: {finished}"
                        );
                    } else {
                        assert_eq!(finished["params"]["status"], "error", "{finished}");
                        assert_eq!(
                            finished["params"]["stale"],
                            change == "silent",
                            "{command} explicit={explicit} alias={alias}: {finished}"
                        );
                    }
                    let diagnostics = server.request(
                        4,
                        "textDocument/diagnostic",
                        json!({"textDocument":{"uri":main}}),
                    );
                    let items = diagnostics["items"].as_array().unwrap();
                    if change == "none" {
                        assert!(
                            items.iter().any(|item| item["code"] == code),
                            "{command} explicit={explicit} alias={alias}: {diagnostics}"
                        );
                    } else {
                        assert!(
                            !items.iter().any(|item| item["source"] == "latex-build"),
                            "{command} explicit={explicit} alias={alias}: {diagnostics}"
                        );
                    }
                    server.request(5, "shutdown", Value::Null);
                    server.notify("exit", Value::Null);
                    server.wait_exit(0);
                }
            }
        }
    }
}

