#[test]
#[cfg(unix)]
fn graphic_files_created_during_compilation_discard_or_cancel_obsolete_missing_errors() {
    use std::os::unix::fs::symlink;
    for location in ["root", "nested", "search", "alias-search", "alias-path"] {
        for explicit in [false, true] {
            for change in ["none", "silent", "file-event", "directory-event"] {
                let script = r#"cp diagnostic.log "$1/main.log"
printf 'PWD %s\nINPUT %s/main.tex\n' "$PWD" "$PWD" > "$1/main.fls"
touch "$1/ready"
while [ ! -f "$1/release" ]; do sleep 0.02; done
exit 1
"#;
                let (mut server, directory, main) = fake_build_server_capabilities(
                    script,
                    false,
                    json!({"textDocument":{"diagnostic":{}}}),
                );
                let external = tempfile::tempdir().unwrap();
                let root = directory.path();
                if location.starts_with("alias-") {
                    symlink(external.path(), root.join("alias")).unwrap();
                }
                let suffix = if explicit { ".png" } else { "" };
                let (declaration, argument, parent) = match location {
                    "root" => ("", format!("图 片{suffix}"), root.to_path_buf()),
                    "nested" => ("", format!("nested/图 片{suffix}"), root.join("nested")),
                    "search" => (
                        "\\graphicspath{% before\n{assets/nested/}% after\n}\n",
                        format!("图 片{suffix}"),
                        root.join("assets/nested"),
                    ),
                    "alias-search" => (
                        "\\graphicspath{{alias/nested/}}\n",
                        format!("图 片{suffix}"),
                        external.path().join("nested"),
                    ),
                    _ => (
                        "",
                        format!("alias/nested/图 片{suffix}"),
                        external.path().join("nested"),
                    ),
                };
                let prefix = format!("\\documentclass{{article}}\n\\usepackage{{graphicx}}\n{declaration}\\begin{{document}}\n");
                let line = prefix.lines().count() + 1;
                let call = format!("\\includegraphics*[width=1cm]{{{argument}}}");
                let source = format!("{prefix}{call}\n\\end{{document}}\n");
                std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
                let (message, documentation) = if explicit {
                    (format!("Package pdftex.def Error: File `{argument}' not found: using draft setting."), "See the pdftex.def package documentation for explanation.")
                } else {
                    (
                        format!("LaTeX Error: File `{argument}' not found."),
                        "See the LaTeX manual or LaTeX Companion for explanation.",
                    )
                };
                std::fs::write(root.join("diagnostic.log"), format!("(./main.tex\n! {message}\n{documentation}\nType  H <return>  for immediate help.\n ...\nl.{line} {call}\n)\n")).unwrap();
                server.notify("textDocument/didChange", json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}));
                server.request(
                    2,
                    "workspace/executeCommand",
                    json!({"command":"latex.build","arguments":[main]}),
                );
                let output = root.join("build/latex-lsp");
                let deadline = std::time::Instant::now() + Duration::from_secs(5);
                while !output.join("ready").exists() {
                    assert!(
                        std::time::Instant::now() < deadline,
                        "compiler did not start"
                    );
                    std::thread::sleep(Duration::from_millis(10));
                }
                let physical = parent.join("图 片.png");
                if change != "none" {
                    std::fs::create_dir_all(&parent).unwrap();
                    std::fs::write(&physical, b"PNG existence fixture").unwrap();
                }
                if change.ends_with("event") {
                    let changed = if change == "directory-event" {
                        &parent
                    } else {
                        &physical
                    };
                    server.notify(
                        "workspace/didChangeWatchedFiles",
                        json!({"changes":[{"uri":Url::from_file_path(changed).unwrap(),"type":1}]}),
                    );
                    server.request(
                        3,
                        "textDocument/documentSymbol",
                        json!({"textDocument":{"uri":main}}),
                    );
                }
                std::fs::write(output.join("release"), "").unwrap();
                let finished = server.until(|message| message["method"] == "latex/buildFinished");
                if change.ends_with("event") {
                    assert_eq!(
                        finished["params"]["status"], "cancelled",
                        "{location} explicit={explicit}: {finished}"
                    );
                } else {
                    assert_eq!(finished["params"]["status"], "error", "{finished}");
                    assert_eq!(
                        finished["params"]["stale"],
                        change == "silent",
                        "{location} explicit={explicit}: {finished}"
                    );
                }
                let diagnostics = server.request(
                    4,
                    "textDocument/diagnostic",
                    json!({"textDocument":{"uri":main}}),
                );
                let items = diagnostics["items"].as_array().unwrap();
                if change == "none" {
                    assert!(
                        items.iter().any(|item| item["code"] == "missing-image"),
                        "{location} explicit={explicit}: {diagnostics}"
                    );
                } else {
                    assert!(
                        !items.iter().any(|item| item["source"] == "latex-build"),
                        "{location} explicit={explicit}: {diagnostics}"
                    );
                }
                server.request(5, "shutdown", Value::Null);
                server.notify("exit", Value::Null);
                server.wait_exit(0);
            }
        }
    }
}

#[test]
#[cfg(unix)]
fn first_static_graphic_alias_retargets_invalidate_builds_without_prior_recorder_history() {
    use std::os::unix::fs::symlink;
    for directory_alias in [false, true] {
        for explicit in [false, true] {
            let name = if directory_alias { "plot" } else { "alias" };
            let argument = format!("{name}{}", if explicit { ".png" } else { "" });
            let input = if directory_alias {
                "alias/plot.png"
            } else {
                "alias.png"
            };
            let script = format!(
                r#"printf '(./main.tex\n)\n' > "$1/main.log"
printf 'PWD %s\nINPUT %s/main.tex\nINPUT %s/{input}\n' "$PWD" "$PWD" "$PWD" > "$1/main.fls"
touch "$1/ready"
while [ ! -f "$1/release" ]; do sleep 0.02; done
printf '%%PDF-1.4\n' > "$1/main.pdf"
"#
            );
            let (mut server, directory, main) = fake_build_server(&script, false);
            let root = directory.path();
            for name in ["old", "new"] {
                std::fs::create_dir(root.join(name)).unwrap();
                std::fs::write(root.join(name).join("plot.png"), b"PNG existence fixture").unwrap();
            }
            let (alias, old, new) = if directory_alias {
                (root.join("alias"), root.join("old"), root.join("new"))
            } else {
                (
                    root.join("alias.png"),
                    root.join("old/plot.png"),
                    root.join("new/plot.png"),
                )
            };
            symlink(&old, &alias).unwrap();
            let declaration = if directory_alias {
                "\\graphicspath{{alias/}}\n"
            } else {
                ""
            };
            let source = format!("{declaration}\\includegraphics{{{argument}}}\n");
            std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
            server.notify(
                "textDocument/didChange",
                json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
            );
            server.request(
                2,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let output = root.join("build/latex-lsp");
            let deadline = std::time::Instant::now() + Duration::from_secs(5);
            while !output.join("ready").exists() {
                assert!(std::time::Instant::now() < deadline);
                std::thread::sleep(Duration::from_millis(10));
            }
            std::fs::remove_file(&alias).unwrap();
            symlink(&new, &alias).unwrap();
            std::fs::write(output.join("release"), "").unwrap();
            let finished = server.until(|message| message["method"] == "latex/buildFinished");
            assert_eq!(finished["params"]["status"], "success", "{finished}");
            assert_eq!(
                finished["params"]["stale"], true,
                "directory_alias={directory_alias} explicit={explicit}: {finished}"
            );
            server.request(3, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
fn cmyk_color_picker_preserves_separations_and_independent_frame_colors_over_stdio() {
    use latex_lsp::text::Text;
    use tower_lsp::lsp_types::{ColorPresentation, TextDocumentContentChangeEvent};
    let mut server = Server::start();
    let uri = Url::parse("file:///cmyk-protocol/main.tex").unwrap();
    let initialized = server.request(1, "initialize", json!({"processId":null,"capabilities":{}}));
    assert_eq!(initialized["capabilities"]["colorProvider"], true);
    server.notify("initialized", json!({}));
    let source = "% emoji😀\r\n\\fcolorbox[cmyk]{ .2,.4,.8,.1 }% keep\r\n{ .25,.5,.75,.125 }{Body}\r\n\\definecolor[named]{paint}[pre]{cmyk}{ 0,1,1,0 }\r\n";
    let mut text = Text::new(source.into());
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"latex","version":7,"text":source}}),
    );
    let found = server.request(
        2,
        "textDocument/documentColor",
        json!({"textDocument":{"uri":uri}}),
    );
    assert_eq!(found.as_array().unwrap().len(), 3);
    assert_eq!(
        found[1]["color"],
        json!({"red":0.625,"green":0.375,"blue":0.125,"alpha":1.0})
    );
    let no_op = server.request(
        3,
        "textDocument/colorPresentation",
        json!({"textDocument":{"uri":uri},"range":found[0]["range"],"color":found[0]["color"]}),
    );
    assert_eq!(no_op[0]["textEdit"]["newText"], "0.2,0.4,0.8,0.1");
    assert!(no_op[0]["additionalTextEdits"].is_null());
    let green = json!({"red":0.0,"green":1.0,"blue":0.0,"alpha":1.0});
    let presented = server.request(
        4,
        "textDocument/colorPresentation",
        json!({"textDocument":{"uri":uri},"range":found[0]["range"],"color":green}),
    );
    let presentations: Vec<ColorPresentation> = serde_json::from_value(presented).unwrap();
    assert_eq!(presentations.len(), 1);
    assert_eq!(presentations[0].label, "cmyk {1,0,1,0}");
    assert!(presentations[0].additional_text_edits.is_none());
    let edit = presentations[0].text_edit.clone().unwrap();
    let changes = vec![TextDocumentContentChangeEvent {
        range: Some(edit.range),
        range_length: None,
        text: edit.new_text,
    }];
    text = text.changed(changes.clone()).unwrap();
    assert_eq!(text.source, source.replace(".2,.4,.8,.1", "1,0,1,0"));
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":uri,"version":8},"contentChanges":changes}),
    );
    let updated = server.request(
        5,
        "textDocument/documentColor",
        json!({"textDocument":{"uri":uri}}),
    );
    assert_eq!(updated[0]["color"], green);
    assert_eq!(updated[1]["color"], found[1]["color"]);
    assert_eq!(updated[1]["range"], found[1]["range"]);
    assert_eq!(updated[2]["color"], found[2]["color"]);
    let blue = json!({"red":0.0,"green":0.0,"blue":1.0,"alpha":1.0});
    let stale = server.request(
        6,
        "textDocument/colorPresentation",
        json!({"textDocument":{"uri":uri},"range":found[0]["range"],"color":blue}),
    );
    assert_eq!(stale, json!([]));
    let presented = server.request(
        7,
        "textDocument/colorPresentation",
        json!({"textDocument":{"uri":uri},"range":updated[1]["range"],"color":blue}),
    );
    let presentations: Vec<ColorPresentation> = serde_json::from_value(presented).unwrap();
    assert_eq!(presentations.len(), 1);
    assert!(presentations[0].additional_text_edits.is_none());
    let edit = presentations[0].text_edit.clone().unwrap();
    let changes = vec![TextDocumentContentChangeEvent {
        range: Some(edit.range),
        range_length: None,
        text: edit.new_text,
    }];
    text = text.changed(changes.clone()).unwrap();
    assert_eq!(
        text.source,
        source
            .replace(".2,.4,.8,.1", "1,0,1,0")
            .replace(".25,.5,.75,.125", "1,1,0,0")
    );
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":uri,"version":9},"contentChanges":changes}),
    );
    let final_colors = server.request(
        8,
        "textDocument/documentColor",
        json!({"textDocument":{"uri":uri}}),
    );
    assert_eq!(final_colors[0]["color"], green);
    assert_eq!(final_colors[1]["color"], blue);
    assert_eq!(final_colors[2]["color"], found[2]["color"]);
    let transparent = server.request(9, "textDocument/colorPresentation", json!({"textDocument":{"uri":uri},"range":final_colors[1]["range"],"color":{"red":0,"green":0,"blue":1,"alpha":0.5}}));
    assert_eq!(transparent, json!([]));
    server.request(10, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[cfg(unix)]
fn configure_rebuild(
    server: &mut Server,
    directory: &tempfile::TempDir,
    on_save: bool,
    extra: &str,
) {
    let script = directory.path().join("compiler.sh");
    server.notify(
        "workspace/didChangeConfiguration",
        json!({"settings":{"build":{
            "executable":"/bin/sh", "arguments":[script,"%o","%f","normal"],
            "rebuildArguments":[script,"%o","%f",extra],"onSave":on_save,"timeoutSeconds":5
        }}}),
    );
}

#[test]
#[cfg(unix)]
fn rebuild_requests_coalesce_and_saves_preserve_force_with_fresh_configuration_and_versions() {
    for on_save in [false, true] {
        for initial_force in [false, true] {
            let script = r#"count=0
[ ! -f "$1/count" ] || count=$(cat "$1/count")
count=$((count + 1))
printf '%s' "$count" > "$1/count"
printf '%s' "$3" > "$1/mode$count"
touch "$1/ready$count"
while [ ! -f "$1/release$count" ]; do sleep 0.02; done
printf '%%PDF-1.4\n%s\n' "$count" > "$1/main.pdf"
printf '%s:2: LaTeX Warning: build %s.\n' "$2" "$count" > "$1/main.log"
"#;
            let (mut server, directory, uri) = fake_build_server(script, on_save);
            configure_rebuild(&mut server, &directory, on_save, "force-old");
            let started = server.request(2,"workspace/executeCommand",json!({"command":if initial_force {"latex.rebuild"} else {"latex.build"},"arguments":[{"uri":uri}]}));
            assert_eq!(started["rebuild"], initial_force);
            let output = directory.path().join("build/latex-lsp");
            let deadline = std::time::Instant::now() + Duration::from_secs(3);
            while !output.join("ready1").exists() {
                assert!(std::time::Instant::now() < deadline);
                std::thread::sleep(Duration::from_millis(10));
            }
            for id in [3, 4, 5] {
                let queued = server.request(
                    id,
                    "workspace/executeCommand",
                    json!({"command":"latex.rebuild","arguments":[uri]}),
                );
                assert_eq!(queued["buildId"], started["buildId"]);
                assert_eq!(queued["queuedRebuild"], true);
                assert_eq!(queued["rebuild"], initial_force);
            }
            configure_rebuild(&mut server, &directory, on_save, "force-new");
            for version in [2, 3] {
                let source = format!("\\documentclass{{article}}\n\\section{{Saved {version}}}\n");
                std::fs::write(uri.to_file_path().unwrap(), &source).unwrap();
                server.notify("textDocument/didChange",json!({"textDocument":{"uri":uri,"version":version},"contentChanges":[{"text":source}]}));
                server.notify("textDocument/didSave", json!({"textDocument":{"uri":uri}}));
            }
            let status = server.request(
                6,
                "workspace/executeCommand",
                json!({"command":"latex.buildStatus","arguments":[uri]}),
            );
            assert_eq!(status["queuedRebuild"], true);
            std::fs::write(output.join("release1"), "").unwrap();
            let first = server.until(|m| {
                m["method"] == "latex/buildFinished" && m["params"]["buildId"] == started["buildId"]
            });
            assert_eq!(first["params"]["stale"], true);
            let second_started = server.until(|m| {
                m["method"] == "latex/buildStarted" && m["params"]["buildId"] != started["buildId"]
            });
            assert_eq!(second_started["params"]["rebuild"], true);
            assert_eq!(second_started["params"]["engine"], Value::Null);
            let status = server.request(
                7,
                "workspace/executeCommand",
                json!({"command":"latex.buildStatus","arguments":[uri]}),
            );
            assert_eq!(status["rebuild"], true);
            assert_eq!(status["queued"], false);
            std::fs::write(output.join("release2"), "").unwrap();
            let second = server.until(|m| {
                m["method"] == "latex/buildFinished"
                    && m["params"]["buildId"] == second_started["params"]["buildId"]
            });
            assert_eq!(second["params"]["status"], "success", "{second}");
            assert_eq!(second["params"]["stale"], false);
            assert_eq!(second["params"]["rebuild"], true);
            assert_eq!(
                std::fs::read_to_string(output.join("mode2")).unwrap(),
                "force-new"
            );
            assert_eq!(
                std::fs::read_to_string(output.join("mode1")).unwrap(),
                if initial_force { "force-old" } else { "normal" }
            );
            let diagnostics = server.until(|m| {
                m["method"] == "textDocument/publishDiagnostics"
                    && m["params"]["diagnostics"].as_array().is_some_and(|items| {
                        items
                            .iter()
                            .any(|d| d["message"].as_str().is_some_and(|s| s.contains("build 2")))
                    })
            });
            assert_eq!(diagnostics["params"]["version"], 3);
            std::thread::sleep(Duration::from_millis(100));
            assert_eq!(std::fs::read_to_string(output.join("count")).unwrap(), "2");
            let final_status = server.request(
                8,
                "workspace/executeCommand",
                json!({"command":"latex.buildStatus","arguments":[uri]}),
            );
            assert_eq!(final_status, second["params"]);
            server.request(9, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
#[cfg(unix)]
fn cancellation_file_events_and_shutdown_discard_queued_rebuilds() {
    for action in ["command", "progress", "watched", "created", "shutdown"] {
        let (mut server, directory, uri) = fake_build_server_capabilities(
            "printf 'run\\n' >> runs\nsleep 30\n",
            false,
            json!({"window":{"workDoneProgress":true}}),
        );
        // Track a missing conditional file so creating it cancels this build.
        let source = "\\documentclass{article}\n\\IfFileExists{choice.dat}{}{}\n";
        std::fs::write(uri.to_file_path().unwrap(), source).unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"text":source}]}),
        );
        configure_rebuild(&mut server, &directory, false, "force");
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.rebuild","arguments":[uri]}),
        );
        let create = server.until(|m| m["method"] == "window/workDoneProgress/create");
        server.send(json!({"jsonrpc":"2.0","id":create["id"],"result":null}));
        server.until(|m| m["method"] == "$/progress" && m["params"]["value"]["kind"] == "begin");
        let queued = server.request(
            3,
            "workspace/executeCommand",
            json!({"command":"latex.rebuild","arguments":[uri]}),
        );
        assert_eq!(queued["queuedRebuild"], true);
        match action {
            "command" => {
                server.request(
                    4,
                    "workspace/executeCommand",
                    json!({"command":"latex.cancelBuild","arguments":[uri]}),
                );
            }
            "progress" => server.notify(
                "window/workDoneProgress/cancel",
                json!({"token":create["params"]["token"]}),
            ),
            "watched" => {
                std::fs::write(uri.to_file_path().unwrap(), format!("{source}Changed.\n")).unwrap();
                server.notify(
                    "workspace/didChangeWatchedFiles",
                    json!({"changes":[{"uri":uri,"type":2}]}),
                );
            }
            "created" => {
                let choice = directory.path().join("choice.dat");
                std::fs::write(&choice, "data").unwrap();
                server.notify(
                    "workspace/didCreateFiles",
                    json!({"files":[{"uri":Url::from_file_path(choice).unwrap()}]}),
                );
            }
            "shutdown" => {
                server.request(4, "shutdown", Value::Null);
            }
            _ => unreachable!(),
        }
        let finished = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(
            finished["params"]["status"], "cancelled",
            "{action}: {finished}"
        );
        if action != "shutdown" {
            let status = server.request(
                5,
                "workspace/executeCommand",
                json!({"command":"latex.buildStatus","arguments":[uri]}),
            );
            assert_eq!(status["status"], "cancelled");
            std::thread::sleep(Duration::from_millis(100));
            server.request(6, "shutdown", Value::Null);
        }
        server.notify("exit", Value::Null);
        server.wait_exit(0);
        let runs = std::fs::read_to_string(directory.path().join("runs")).unwrap_or_default();
        assert!(runs.lines().count() <= 1, "{action}: {runs}");
    }
}

#[test]
#[cfg(unix)]
fn unsupported_rebuild_commands_fail_before_touching_previous_artifacts() {
    let (mut server, directory, uri) = fake_build_server("touch invoked\n", false);
    let output = directory.path().join("build/latex-lsp");
    std::fs::create_dir_all(&output).unwrap();
    for extension in ["log", "pdf"] {
        std::fs::write(output.join(format!("main.{extension}")), "previous").unwrap();
    }
    server.send(json!({"jsonrpc":"2.0","id":2,"method":"workspace/executeCommand","params":{"command":"latex.rebuild","arguments":[uri]}}));
    let error = server.until(|m| m["id"] == 2);
    assert_eq!(error["error"]["code"], -32602);
    assert!(error["error"]["message"]
        .as_str()
        .unwrap()
        .contains("build.rebuildArguments"));
    assert!(!directory.path().join("invoked").exists());
    for extension in ["log", "pdf"] {
        assert_eq!(
            std::fs::read_to_string(output.join(format!("main.{extension}"))).unwrap(),
            "previous"
        );
    }
    let status = server.request(
        3,
        "workspace/executeCommand",
        json!({"command":"latex.buildStatus","arguments":[uri]}),
    );
    assert_eq!(status["status"], "idle");
    server.request(4, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn rebuild_cancellation_before_progress_acknowledgement_preserves_existing_artifacts() {
    for existing in [false, true] {
        let (mut server, directory, uri) = fake_build_server_capabilities(
            "touch invoked\n",
            false,
            json!({"window":{"workDoneProgress":true}}),
        );
        configure_rebuild(&mut server, &directory, false, "force");
        let output = directory.path().join("build/latex-lsp");
        if existing {
            std::fs::create_dir_all(&output).unwrap();
            for extension in ["log", "pdf", "aux", "fls"] {
                std::fs::write(output.join(format!("main.{extension}")), "previous").unwrap();
            }
        }
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.rebuild","arguments":[uri]}),
        );
        let create = server.until(|m| m["method"] == "window/workDoneProgress/create");
        server.request(
            3,
            "workspace/executeCommand",
            json!({"command":"latex.rebuild","arguments":[uri]}),
        );
        server.notify(
            "window/workDoneProgress/cancel",
            json!({"token":create["params"]["token"]}),
        );
        server.request(4, "workspace/symbol", json!({"query":"Title"}));
        server.send(json!({"jsonrpc":"2.0","id":create["id"],"result":null}));
        let finished = server.until(|m| m["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["status"], "cancelled");
        assert_eq!(finished["params"]["rebuild"], true);
        assert_eq!(finished["params"]["pdfUri"], Value::Null);
        assert_eq!(finished["params"]["logUri"], Value::Null);
        assert_eq!(output.exists(), existing);
        if existing {
            for extension in ["log", "pdf", "aux", "fls"] {
                assert_eq!(
                    std::fs::read_to_string(output.join(format!("main.{extension}"))).unwrap(),
                    "previous"
                );
            }
        }
        server.request(5, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
        assert!(!directory.path().join("invoked").exists());
    }
}

#[test]
#[cfg(unix)]
fn rebuilds_keep_shared_output_conflict_protection() {
    let (mut server, directory, uri) = fake_build_server("sleep 30\n", false);
    let other = directory.path().join("other.tex");
    std::fs::write(&other, "\\documentclass{report}\n").unwrap();
    let other = Url::from_file_path(other).unwrap();
    server.notify("workspace/didChangeConfiguration",json!({"settings":{"build":{"executable":"/bin/sh","arguments":[directory.path().join("compiler.sh"),"%o","%f"],"rebuildArguments":[directory.path().join("compiler.sh"),"%o","%f"],"jobName":"shared"}}}));
    let started = server.request(
        2,
        "workspace/executeCommand",
        json!({"command":"latex.rebuild","arguments":[uri]}),
    );
    server.send(json!({"jsonrpc":"2.0","id":3,"method":"workspace/executeCommand","params":{"command":"latex.rebuild","arguments":[other]}}));
    let error = server.until(|m| m["id"] == 3);
    assert_eq!(error["error"]["code"], -32602);
    assert!(error["error"]["message"]
        .as_str()
        .unwrap()
        .contains("same output file"));
    let status = server.request(
        4,
        "workspace/executeCommand",
        json!({"command":"latex.buildStatus","arguments":[uri]}),
    );
    assert_eq!(status["buildId"], started["buildId"]);
    assert_eq!(status["queued"], false);
    server.request(5, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn static_code_inputs_keep_pdf_and_synctex_history_without_a_recorder_entry() {
    for (command, extension) in [
        "lstinputlisting",
        "verbatiminput",
        "verbatiminput *",
        "VerbatimInput *",
        "LVerbatimInput *",
        "BVerbatimInput *",
        "inputminted{latex}",
    ]
    .into_iter()
    .flat_map(|command| ["unknown", "", "rs", "tex"].map(|extension| (command, extension)))
    {
        let external = tempfile::tempdir().unwrap();
        let data = external.path().join(if extension.is_empty() {
            "README".into()
        } else {
            format!("table.{extension}")
        });
        std::fs::write(&data, "\\label{data-source-old}\n").unwrap();
        let modified = std::fs::metadata(&data).unwrap().modified().unwrap();
        let (mut server, directory, main) = fake_synctex_server("touch queried\nprintf 'SyncTeX result begin\\nPage:1\\nx:10\\ny:20\\nSyncTeX result end\\n'\n");
        let source = format!(
            "\\documentclass{{article}}\n\\{command}{{{}}}\n",
            data.display()
        );
        std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        let compiler = directory.path().join("compiler.sh");
        std::fs::write(&compiler, "if [ -f \"$1/noop\" ]; then exit 0; fi\nprintf '%%PDF-1.4\\nCOMPILED\\n' > \"$1/main.pdf\"\nprintf 'SyncTeX data\\n' > \"$1/main.synctex\"\nprintf 'INPUT %s\\n' \"$2\" > \"$1/main.fls\"\n").unwrap();
        server.notify(
            "workspace/didChangeConfiguration",
            json!({"settings":{"build":{"executable":"/bin/sh","arguments":[compiler,"%o","%f"]}}}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let first = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(first["params"]["status"], "success", "{first}");
        assert_eq!(first["params"]["stale"], false, "{first}");
        assert_eq!(
            first["params"]["dependenciesCount"], 2,
            "{extension}: {first}"
        );
        let forward = json!({"command":"latex.forwardSearch","arguments":[{"uri":main,"position":{"line":1,"character":0}}]});
        let valid = server.request(4, "workspace/executeCommand", forward.clone());
        assert_eq!(valid["locations"][0]["page"], 1, "{valid}");
        std::fs::remove_file(directory.path().join("queried")).unwrap();
        std::fs::write(&data, "\\label{data-source-new}\n").unwrap();
        std::fs::File::open(&data)
            .unwrap()
            .set_times(std::fs::FileTimes::new().set_modified(modified))
            .unwrap();
        server.send(
            json!({"jsonrpc":"2.0","id":5,"method":"workspace/executeCommand","params":forward}),
        );
        let rejected = server.until(|message| message["id"] == 5);
        assert!(
            rejected["error"]["message"]
                .as_str()
                .is_some_and(|message| message.contains("Input contents changed")),
            "{extension}: {rejected}"
        );
        assert!(!directory.path().join("queried").exists());
        let output = directory.path().join("build/latex-lsp");
        std::fs::write(output.join("noop"), "").unwrap();
        for id in [6, 7] {
            server.request(
                id,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let noop = server.until(|message| message["method"] == "latex/buildFinished");
            assert_eq!(noop["params"]["status"], "error", "{extension}: {noop}");
            assert!(noop["params"]["pdfUri"].is_null());
            assert!(
                noop["params"]["message"]
                    .as_str()
                    .is_some_and(|message| message.contains("input content changed")),
                "{noop}"
            );
        }
        std::fs::remove_file(output.join("noop")).unwrap();
        server.request(
            8,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let rebuilt = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(rebuilt["params"]["status"], "success", "{rebuilt}");
        let restored = server.request(9, "workspace/executeCommand", forward);
        assert_eq!(restored["locations"][0]["page"], 1, "{restored}");
        server.request(10, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn static_code_content_changes_invalidate_the_first_build_without_recorder_evidence() {
    for (command, name, notify) in [
        "lstinputlisting",
        "verbatiminput *",
        "VerbatimInput *",
        "LVerbatimInput *",
        "BVerbatimInput *",
        "inputminted{latex}",
    ]
    .into_iter()
    .flat_map(|command| {
        ["README", "example.unknown", "example.tex"]
            .into_iter()
            .flat_map(move |name| [false, true].map(move |notify| (command, name, notify)))
    }) {
        let external = tempfile::tempdir().unwrap();
        let code = external.path().join(name);
        std::fs::write(&code, "Original code.\n").unwrap();
        let modified = std::fs::metadata(&code).unwrap().modified().unwrap();
        let script = "printf '%%PDF-1.4\\n' > \"$1/main.pdf\"\nprintf 'INPUT %s\\n' \"$2\" > \"$1/main.fls\"\ntouch \"$1/ready\"\nwhile [ ! -f \"$1/release\" ]; do sleep 0.02; done\n";
        let (mut server, directory, main) = fake_build_server(script, false);
        let source = format!(
            "\\documentclass{{article}}\n\\{command}{{{}}}\n",
            code.display()
        );
        std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
        );
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let output = directory.path().join("build/latex-lsp");
        wait_for_file(&output.join("ready"));
        std::fs::write(&code, "Modified code.\n").unwrap();
        std::fs::File::open(&code)
            .unwrap()
            .set_times(std::fs::FileTimes::new().set_modified(modified))
            .unwrap();
        if notify {
            server.notify(
                "workspace/didChangeWatchedFiles",
                json!({"changes":[{"uri":Url::from_file_path(&code).unwrap(),"type":2}]}),
            );
        } else {
            std::fs::write(output.join("release"), "").unwrap();
        }
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(
            finished["params"]["status"],
            if notify { "cancelled" } else { "success" },
            "{name}: {finished}"
        );
        if !notify {
            assert_eq!(finished["params"]["stale"], true, "{name}: {finished}");
        }
        std::fs::write(output.join("release"), "").unwrap();
        server.request(
            3,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let fresh = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(fresh["params"]["status"], "success", "{name}: {fresh}");
        assert_eq!(fresh["params"]["stale"], false, "{name}: {fresh}");
        server.request(4, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

