#[cfg(unix)]
fn check_in_flight_code_input_history(command: &str) {
    let script = "printf '%%PDF-1.4\\n' > \"$1/main.pdf\"\nprintf 'INPUT %s\\n' \"$2\" > \"$1/main.fls\"\ntouch \"$1/ready\"\nwhile [ ! -f \"$1/release\" ]; do sleep 0.02; done\n";
    let (mut server, directory, main) = fake_build_server(script, false);
    let root = directory.path();
    let code = root.join("first.unknown");
    std::fs::write(&code, "Original code.\n").unwrap();
    std::fs::write(root.join("second.unknown"), "Other code.\n").unwrap();
    let source = &format!("\\documentclass{{article}}\n\\{command}{{first.unknown}}\n");
    let main_path = main.to_file_path().unwrap();
    std::fs::write(&main_path, source).unwrap();
    let main_time = std::fs::metadata(&main_path).unwrap().modified().unwrap();
    let code_time = std::fs::metadata(&code).unwrap().modified().unwrap();
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
    );
    server.request(
        2,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[main]}),
    );
    let output = root.join("build/latex-lsp");
    wait_for_file(&output.join("ready"));
    let changed = source.replace("first.unknown", "second.unknown");
    std::fs::write(&main_path, &changed).unwrap();
    std::fs::File::open(&main_path)
        .unwrap()
        .set_times(std::fs::FileTimes::new().set_modified(main_time))
        .unwrap();
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":main,"version":3},"contentChanges":[{"text":changed}]}),
    );
    std::fs::write(output.join("release"), "").unwrap();
    let stale = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(stale["params"]["status"], "success", "{stale}");
    assert_eq!(stale["params"]["stale"], true, "{stale}");
    std::fs::write(&main_path, source).unwrap();
    std::fs::File::open(&main_path)
        .unwrap()
        .set_times(std::fs::FileTimes::new().set_modified(main_time))
        .unwrap();
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":main,"version":4},"contentChanges":[{"text":source}]}),
    );
    std::fs::write(&code, "Modified code.\n").unwrap();
    std::fs::File::open(&code)
        .unwrap()
        .set_times(std::fs::FileTimes::new().set_modified(code_time))
        .unwrap();
    std::fs::write(root.join("compiler.sh"), "exit 0\n").unwrap();
    for id in [3, 4] {
        server.request(
            id,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[main]}),
        );
        let noop = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(noop["params"]["status"], "error", "{noop}");
        assert!(
            noop["params"]["message"]
                .as_str()
                .unwrap()
                .contains("input content changed"),
            "{noop}"
        );
    }
    std::fs::write(root.join("compiler.sh"), script).unwrap();
    server.request(
        5,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[main]}),
    );
    let fresh = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(fresh["params"]["status"], "success", "{fresh}");
    assert_eq!(fresh["params"]["stale"], false, "{fresh}");
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}
#[test]
#[cfg(unix)]
fn indirect_loader_candidates_created_during_failure_discard_obsolete_diagnostics() {
    for (loader, extension) in [
        ("usepackage", "sty"),
        ("RequirePackage", "sty"),
        ("RequirePackageWithOptions", "sty"),
        ("documentclass", "cls"),
        ("LoadClass", "cls"),
        ("LoadClassWithOptions", "cls"),
    ] {
        for call in [
            format!("\\csuse{{{loader}}}"),
            format!("\\csname {loader}\\endcsname"),
            r"\readpart".into(),
            r"\csuse{readpart}".into(),
            r"\csname readpart\endcsname".into(),
        ] {
            let script = "touch \"$1/ready\"\nwhile [ ! -f \"$1/release\" ]; do sleep 0.02; done\nprintf '%s:2: Undefined control sequence.\\n' \"$2\" > \"$1/main.log\"\nexit 1\n";
            let (mut server, directory, main) = fake_build_server(script, false);
            let source = format!("\\def\\readpart{{\\{loader}}}\n{call}{{fixture}}\\relax\n");
            std::fs::write(main.to_file_path().unwrap(), &source).unwrap();
            server.notify(
                "textDocument/didChange",
                json!({"textDocument":{"uri":main,"version":2},"contentChanges":[{"text":source}]}),
            );
            server.request(
                2,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[main]}),
            );
            let output = directory.path().join("build/latex-lsp");
            wait_for_file(&output.join("ready"));
            std::fs::write(
                directory.path().join(format!("fixture.{extension}")),
                "New input.",
            )
            .unwrap();
            std::fs::write(output.join("release"), "").unwrap();
            let finished = server.until(|message| message["method"] == "latex/buildFinished");
            assert_eq!(finished["params"]["status"], "error", "{finished}");
            assert_eq!(
                finished["params"]["stale"], true,
                "{loader}/{call}: {finished}"
            );
            assert!(finished["params"]["message"]
                .as_str()
                .unwrap()
                .contains("diagnostics discarded"));
            let diagnostics = server.request(
                3,
                "textDocument/diagnostic",
                json!({"textDocument":{"uri":main}}),
            );
            assert!(
                diagnostics["items"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .all(|d| d["source"] != "latex-build"),
                "{loader}/{call}: {diagnostics}"
            );
            server.request(4, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
fn multicite_groups_support_navigation_hints_completion_and_versioned_rename_over_stdio() {
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"capabilities":{"workspace":{"workspaceEdit":{"documentChanges":true}}}}));
    server.notify("initialized", json!({}));
    let main = "file:///multicite-protocol/main.tex";
    let bib = "file:///multicite-protocol/refs.bib";
    let source = "😀 \\parencites(overall)[alpha]{alpha}[note]{beta}{alpha}";
    server.notify("textDocument/didOpen", json!({"textDocument":{"uri":bib,"languageId":"bibtex","version":8,"text":"@book{alpha,title={Alpha}}\n@book{beta,title={Beta}}"}}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":main,"languageId":"latex","version":12,"text":source}}),
    );
    let position =
        latex_lsp::text::Text::new(source.into()).position(source.rfind("{alpha}").unwrap() + 3);
    let target = json!({"textDocument":{"uri":main},"position":position});
    let definition = server.request(2, "textDocument/definition", target.clone());
    assert_eq!(definition[0]["uri"], bib);
    let prepare = server.request(3, "textDocument/prepareRename", target.clone());
    assert_eq!(prepare["placeholder"], "alpha");
    let help = server.request(4, "textDocument/signatureHelp", target.clone());
    assert_eq!(help["activeParameter"], 10);
    let completions = server.request(5, "textDocument/completion", target.clone());
    assert!(completions
        .as_array()
        .unwrap()
        .iter()
        .any(|item| item["label"] == "alpha"));
    let references = server.request(6, "textDocument/references", json!({"textDocument":{"uri":main},"position":position,"context":{"includeDeclaration":true}}));
    assert_eq!(references.as_array().unwrap().len(), 3);
    let edits = server.request(
        7,
        "textDocument/rename",
        json!({"textDocument":{"uri":main},"position":position,"newName":"renamed"}),
    );
    let changes = edits["documentChanges"].as_array().unwrap();
    assert_eq!(changes.len(), 2);
    for change in changes {
        let is_main = change["textDocument"]["uri"] == main;
        assert_eq!(
            change["textDocument"]["version"],
            if is_main { 12 } else { 8 }
        );
        assert_eq!(
            change["edits"].as_array().unwrap().len(),
            if is_main { 2 } else { 1 }
        );
    }
    server.request(8, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

