#[test]
fn bibliography_formatting_uses_native_fields_preserves_values_and_is_idempotent() {
    use latex_lsp::text::Text;
    use tower_lsp::lsp_types::{TextDocumentContentChangeEvent, TextEdit};
    let dir = tempfile::tempdir().unwrap();
    let uri = Url::from_file_path(dir.path().join("refs.bib")).unwrap();
    std::fs::write(dir.path().join("refs.bib"), "disk content").unwrap();
    let source = "% 😀\r\n@book{key,title={A\r\n  B\nC},year=2026}\r\n";
    let expected = "% 😀\r\n@book{key,\r\n    title = {A\r\n  B\nC},\r\n    year = 2026\r\n}\r\n";
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(dir.path()).unwrap(),"capabilities":{},"initializationOptions":{"distribution":{"enabled":false},"formatting":{"executable":"/does/not/exist/formatter"}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"bibtex","version":1,"text":source}}),
    );
    let edits: Vec<TextEdit> = serde_json::from_value(server.request(
        2,
        "textDocument/formatting",
        formatting_params(&uri),
    ))
    .unwrap();
    let formatted = Text::new(source.into())
        .changed(
            edits
                .into_iter()
                .rev()
                .map(|edit| TextDocumentContentChangeEvent {
                    range: Some(edit.range),
                    range_length: None,
                    text: edit.new_text,
                })
                .collect(),
        )
        .unwrap()
        .source;
    assert_eq!(formatted, expected);
    assert_eq!(
        std::fs::read_to_string(dir.path().join("refs.bib")).unwrap(),
        "disk content"
    );
    server.notify(
        "textDocument/didChange",
        json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"text":formatted}]}),
    );
    assert_eq!(
        server.request(3, "textDocument/formatting", formatting_params(&uri)),
        json!([])
    );
    let mut params = formatting_params(&uri);
    params["options"]["insertSpaces"] = json!(false);
    let edits: Vec<TextEdit> =
        serde_json::from_value(server.request(4, "textDocument/formatting", params.clone()))
            .unwrap();
    let tabs = Text::new(formatted)
        .changed(
            edits
                .into_iter()
                .rev()
                .map(|edit| TextDocumentContentChangeEvent {
                    range: Some(edit.range),
                    range_length: None,
                    text: edit.new_text,
                })
                .collect(),
        )
        .unwrap()
        .source;
    assert!(tabs.contains("\r\n\ttitle = {A\r\n  B\nC}"));
    params["options"]["tabSize"] = json!(0);
    server.send(json!({"jsonrpc":"2.0","id":5,"method":"textDocument/formatting","params":params}));
    assert_eq!(
        server.until(|message| message["id"] == 5)["error"]["code"],
        -32602
    );
    server.request(6, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn bibliography_formatting_ranges_work_for_adjacent_entries_and_untitled_buffers() {
    use latex_lsp::text::Text;
    use tower_lsp::lsp_types::{TextDocumentContentChangeEvent, TextEdit};
    let first = "@book{one,title={😀}}";
    let second = "@book{two,title={Outside}}";
    let source = format!("{first}{second}");
    let uri = Url::parse("untitled:References").unwrap();
    let mut server = Server::start();
    server.request(1, "initialize", json!({"processId":null,"rootUri":null,"capabilities":{},"initializationOptions":{"distribution":{"enabled":false}}}));
    server.notify("initialized", json!({}));
    server.notify(
        "textDocument/didOpen",
        json!({"textDocument":{"uri":uri,"languageId":"bibtex","version":1,"text":source}}),
    );
    let mut params = formatting_params(&uri);
    params["range"] =
        serde_json::to_value(Text::new(source.clone()).range(0, first.len())).unwrap();
    let edits: Vec<TextEdit> =
        serde_json::from_value(server.request(2, "textDocument/rangeFormatting", params)).unwrap();
    let formatted = Text::new(source)
        .changed(
            edits
                .into_iter()
                .rev()
                .map(|edit| TextDocumentContentChangeEvent {
                    range: Some(edit.range),
                    range_length: None,
                    text: edit.new_text,
                })
                .collect(),
        )
        .unwrap()
        .source;
    assert_eq!(
        formatted,
        format!("@book{{one,\n    title = {{😀}}\n}}{second}")
    );
    // A differently named document still follows the editor's bibliography language.
    let other = Url::parse("untitled:Other.txt").unwrap();
    server.notify("textDocument/didOpen", json!({"textDocument":{"uri":other,"languageId":"bibtex","version":1,"text":"@book{k,title={T}}"}}));
    assert!(!server
        .request(3, "textDocument/formatting", formatting_params(&other))
        .as_array()
        .unwrap()
        .is_empty());
    let style = Url::parse("untitled:plain.bst").unwrap();
    server.notify("textDocument/didOpen", json!({"textDocument":{"uri":style,"languageId":"bst","version":1,"text":"ENTRY {} {} {}"}}));
    assert_eq!(
        server.request(4, "textDocument/formatting", formatting_params(&style)),
        Value::Null
    );
    server.request(5, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
fn static_bibliography_field_diagnostics_refresh_push_and_pull_without_building() {
    for pull in [false, true] {
        let directory = tempfile::tempdir().unwrap();
        let uri = Url::from_file_path(directory.path().join("refs.bib")).unwrap();
        let source = "% 😀\r\n@book{k,title={One},TITLE={Two}}";
        let capabilities = if pull {
            json!({"textDocument":{"diagnostic":{}}})
        } else {
            json!({})
        };
        let mut server = Server::start();
        server.request(1, "initialize", json!({"processId":null,"rootUri":Url::from_directory_path(directory.path()).unwrap(),"capabilities":capabilities,"initializationOptions":{"distribution":{"enabled":false}}}));
        server.notify("initialized", json!({}));
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":uri,"languageId":"bibtex","version":1,"text":source}}),
        );
        let report = |server: &mut Server, id, version, count| -> Value {
            if pull {
                server.request(
                    id,
                    "textDocument/diagnostic",
                    json!({"textDocument":{"uri":uri}}),
                )["items"]
                    .clone()
            } else {
                server.until(|message| {
                    message["method"] == "textDocument/publishDiagnostics"
                        && message["params"]["uri"] == uri.as_str()
                        && message["params"]["version"] == version
                        && message["params"]["diagnostics"]
                            .as_array()
                            .is_some_and(|items| items.len() == count)
                })["params"]["diagnostics"]
                    .clone()
            }
        };
        let items = report(&mut server, 2, 1, 1);
        assert_eq!(items.as_array().unwrap().len(), 1);
        assert_eq!(items[0]["code"], "repeated-bibliography-field");
        assert_eq!(items[0]["source"], "latex-lsp");
        let at = source.find("TITLE").unwrap();
        let text = latex_lsp::text::Text::new(source.into());
        assert_eq!(
            items[0]["range"],
            serde_json::to_value(text.range(at, at + 5)).unwrap()
        );
        assert_eq!(
            items[0]["relatedInformation"][0]["location"]["uri"],
            uri.as_str()
        );
        server.notify("textDocument/didChange", json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"range":text.range(at,at+5),"text":"note"}]}));
        assert_eq!(report(&mut server, 3, 2, 0), json!([]));
        server.notify(
            "textDocument/didChange",
            json!({"textDocument":{"uri":uri,"version":3},"contentChanges":[{"text":source}]}),
        );
        assert_eq!(report(&mut server, 4, 3, 1).as_array().unwrap().len(), 1);
        server.notify("workspace/didChangeConfiguration", json!({"settings":{"distribution":{"enabled":false},"diagnostics":{"duplicateBibliographyFields":false}}}));
        assert_eq!(report(&mut server, 5, 3, 0), json!([]));
        assert!(!directory.path().join("refs.bib").exists());
        server.request(6, "shutdown", Value::Null);
        if pull {
            assert_no_pushed_diagnostics(&server);
        }
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn range_formatting_clamps_oversized_columns_for_latex_and_bibliography() {
    use latex_lsp::text::Text;
    use tower_lsp::lsp_types::{TextDocumentContentChangeEvent, TextEdit};
    for language in ["latex", "bibtex"] {
        let (mut server, directory, uri) = formatting_server("sed 's/^/  /'", 10);
        let (source, expected) = if language == "latex" {
            (
                "% outside\r\n😀 selected\r\nuntouched\r\n",
                "% outside\r\n  😀 selected\r\nuntouched\r\n",
            )
        } else {
            (
                "% outside\r\n@book{k,title={😀}}\r\nuntouched\r\n",
                "% outside\r\n@book{k,\r\n    title = {😀}\r\n}\r\nuntouched\r\n",
            )
        };
        server.notify(
            "textDocument/didOpen",
            json!({"textDocument":{"uri":uri,"languageId":language,"version":1,"text":source}}),
        );
        let mut params = formatting_params(&uri);
        params["range"] =
            json!({"start":{"line":1,"character":0},"end":{"line":1,"character":4294967295u32}});
        let edits: Vec<TextEdit> = serde_json::from_value(server.request(
            2,
            "textDocument/rangeFormatting",
            params.clone(),
        ))
        .unwrap();
        let result = Text::new(source.into())
            .changed(
                edits
                    .into_iter()
                    .rev()
                    .map(|edit| TextDocumentContentChangeEvent {
                        range: Some(edit.range),
                        range_length: None,
                        text: edit.new_text,
                    })
                    .collect(),
            )
            .unwrap()
            .source;
        assert_eq!(result, expected);
        std::fs::remove_file(directory.path().join("formatter with spaces")).unwrap();
        params["range"] =
            json!({"start":{"line":1,"character":999},"end":{"line":1,"character":1000}});
        assert_eq!(
            server.request(3, "textDocument/rangeFormatting", params),
            json!([])
        );
        server.request(4, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

