#[cfg(unix)]
fn index_workflow_server(tool_body: &str, named: bool) -> (Server, tempfile::TempDir, Url) {
    let compiler = r#"set -eu
output="$1"; source="$2"; job="$3"
printf x >> "$output/passes"
printf '\\indexentry{Apple}{1}\n' > "$output/$job.idx"
printf '%%PDF-index\n' > "$output/$job.pdf"
printf '(./main.tex\nOutput written on %s.pdf (1 page, 11 bytes).\n)\n' "$job" > "$output/$job.log"
printf 'PWD %s\nINPUT %s\n' "$output" "$source" > "$output/$job.fls"
"#;
    let (mut server, directory, uri) = fake_build_server(compiler, false);
    let tool = directory.path().join("index-tool.sh");
    std::fs::write(&tool, format!("set -eu\n{tool_body}\n")).unwrap();
    std::fs::write(directory.path().join("style.ist"), "style").unwrap();
    let arguments = json!([directory.path().join("compiler.sh"), "%o", "%f", "%j"]);
    server.notify("workspace/didChangeConfiguration", json!({"settings":{"distribution":{"enabled":false},"build":{"executable":"/bin/sh","arguments":arguments,"rebuildArguments":arguments,"timeoutSeconds":10,"indexTools":[{"executable":"/bin/sh","arguments":[tool,"%i","%t","%r/style.ist"],"dependencies":["style.ist"],"jobName":if named {json!("shared")} else {Value::Null}}]}}}));
    (server, directory, uri)
}

#[test]
#[cfg(unix)]
fn index_rebuild_actions_run_matching_pipelines_and_reject_changed_task_configuration() {
    let compiler = r#"set -eu
printf x >> "$1/passes"
printf 'index entries\n' > "$1/main.idx"
printf '%%PDF-index\n' > "$1/main.pdf"
printf '(./main.tex\n' > "$1/main.log"
if ! cmp -s "$1/main.idx" "$1/main.ind"; then
  printf "Package rerunfilecheck Warning: File \140main.idx' has changed. Rerun LaTeX/makeindex to get index right.\n" >> "$1/main.log"
fi
printf 'Output written on main.pdf (1 page, 11 bytes).\n)\n' >> "$1/main.log"
printf 'PWD %s\nINPUT %s\n' "$PWD" "$2" > "$1/main.fls"
"#;
    for literals in [false, true] {
        for change in ["execute", "remove", "job", "type"] {
            let capabilities = if literals {
                json!({"textDocument":{"codeAction":{"codeActionLiteralSupport":{"codeActionKind":{"valueSet":["quickfix"]}}}}})
            } else {
                json!({})
            };
            let (mut server, directory, uri) =
                fake_build_server_capabilities(compiler, false, capabilities);
            let arguments = json!([directory.path().join("compiler.sh"), "%o", "%f"]);
            let mut settings = json!({"build":{"executable":"/bin/sh","arguments":arguments,"rebuildArguments":arguments}});
            server.notify(
                "workspace/didChangeConfiguration",
                json!({"settings":settings}),
            );
            server.request(
                2,
                "workspace/executeCommand",
                json!({"command":"latex.build","arguments":[uri]}),
            );
            let finished = server.until(|message| message["method"] == "latex/buildFinished");
            assert_eq!(finished["params"]["status"], "success", "{finished}");
            let published = server.until(|message| {
                message["method"] == "textDocument/publishDiagnostics"
                    && message["params"]["uri"] == uri.as_str()
                    && message["params"]["diagnostics"]
                        .as_array()
                        .is_some_and(|items| {
                            items.iter().any(|item| item["source"] == "latex-build")
                        })
            });
            let diagnostic = published["params"]["diagnostics"]
                .as_array()
                .unwrap()
                .iter()
                .find(|item| item["source"] == "latex-build")
                .unwrap();
            let request = json!({"textDocument":{"uri":uri},"range":diagnostic["range"],"context":{"diagnostics":[diagnostic],"only":["quickfix"]}});
            assert_eq!(
                server.request(3, "textDocument/codeAction", request.clone()),
                json!([])
            );
            let tool = directory.path().join("index-tool.sh");
            std::fs::write(&tool, "cat \"$1\" > \"$2\"\n").unwrap();
            settings["build"]["indexTools"] =
                json!([{"executable":"/bin/sh","arguments":[tool,"%i","%t"]}]);
            server.notify(
                "workspace/didChangeConfiguration",
                json!({"settings":settings}),
            );
            let actions = server.request(4, "textDocument/codeAction", request.clone());
            assert_eq!(
                actions.as_array().unwrap().len(),
                1,
                "{change}/{literals}: {actions}"
            );
            let command = if literals {
                &actions[0]["command"]
            } else {
                &actions[0]
            };
            match change {
                "remove" => settings["build"]["indexTools"] = json!([]),
                "job" => settings["build"]["indexTools"][0]["jobName"] = json!("other"),
                "type" => {
                    settings["build"]["indexTools"][0]["inputExtension"] = json!("glo");
                    settings["build"]["indexTools"][0]["outputExtension"] = json!("gls");
                }
                "execute" => {}
                _ => unreachable!(),
            }
            if change != "execute" {
                server.notify(
                    "workspace/didChangeConfiguration",
                    json!({"settings":settings}),
                );
                assert_eq!(
                    server.request(5, "textDocument/codeAction", request.clone()),
                    json!([])
                );
            }
            server.send(json!({"jsonrpc":"2.0","id":6,"method":"workspace/executeCommand","params":command}));
            let response = server.until(|message| message["id"] == 6);
            if change == "execute" {
                assert_eq!(response["result"]["status"], "started", "{response}");
                let finished = server.until(|message| message["method"] == "latex/buildFinished");
                assert_eq!(finished["params"]["status"], "success", "{finished}");
                assert_eq!(finished["params"]["analysis"]["rerunRequired"], false);
                assert_eq!(finished["params"]["analysis"]["indexProcessingRounds"], 1);
                assert_eq!(
                    std::fs::read(directory.path().join("build/latex-lsp/passes"))
                        .unwrap()
                        .len(),
                    3
                );
                assert_eq!(
                    server.request(7, "textDocument/codeAction", request),
                    json!([])
                );
            } else {
                assert_eq!(
                    response["error"]["code"], -32602,
                    "{change}/{literals}: {response}"
                );
                assert!(response["error"]["message"]
                    .as_str()
                    .unwrap()
                    .contains("code actions again"));
                assert_eq!(
                    std::fs::read(directory.path().join("build/latex-lsp/passes"))
                        .unwrap()
                        .len(),
                    1
                );
            }
            server.request(8, "shutdown", Value::Null);
            server.notify("exit", Value::Null);
            server.wait_exit(0);
        }
    }
}

#[test]
#[cfg(unix)]
fn index_workflow_over_stdio_keeps_status_final_artifacts_and_saved_dependencies_consistent() {
    let (mut server, directory, uri) = index_workflow_server("cat \"$1\" > \"$2\"", false);
    let style = Url::from_file_path(directory.path().join("style.ist")).unwrap();
    server.notify("textDocument/didOpen", json!({"textDocument":{"uri":style,"languageId":"plaintext","version":1,"text":"unsaved style"}}));
    server.send(json!({"jsonrpc":"2.0","id":2,"method":"workspace/executeCommand","params":{"command":"latex.build","arguments":[uri]}}));
    let refused = server.until(|message| message["id"] == 2);
    assert_eq!(refused["error"]["code"], -32602);
    assert!(refused["error"]["message"]
        .as_str()
        .unwrap()
        .contains("Save"));
    assert!(!directory.path().join("build/latex-lsp/passes").exists());
    server.notify(
        "textDocument/didClose",
        json!({"textDocument":{"uri":style}}),
    );
    let started = server.request(
        3,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[uri]}),
    );
    assert_eq!(started["status"], "started");
    let finished = server.until(|message| message["method"] == "latex/buildFinished");
    let finished = &finished["params"];
    assert_eq!(finished["status"], "success", "{finished}");
    assert_eq!(finished["stale"], false, "{finished}");
    assert_eq!(finished["analysis"]["indexProcessingRounds"], 1);
    assert_eq!(
        finished["analysis"]["processedIndexTools"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert_eq!(
        std::fs::read(directory.path().join("build/latex-lsp/passes"))
            .unwrap()
            .len(),
        2
    );
    assert_eq!(
        std::fs::read_to_string(directory.path().join("build/latex-lsp/main.ind")).unwrap(),
        "\\indexentry{Apple}{1}\n"
    );
    let status = server.request(
        4,
        "workspace/executeCommand",
        json!({"command":"latex.buildStatus","arguments":[uri]}),
    );
    assert_eq!(status, *finished);
    server.request(5, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn index_workflow_cancellation_remains_responsive_and_blocks_shared_named_outputs() {
    let (mut server, directory, uri) = index_workflow_server(
        "printf ready > ready\nwhile test ! -f release; do sleep 0.02; done\ncat \"$1\" > \"$2\"",
        true,
    );
    let output = directory.path().join("build/latex-lsp");
    std::fs::create_dir_all(&output).unwrap();
    std::fs::write(output.join("shared.idx"), "shared input").unwrap();
    std::fs::write(output.join("shared.ind"), "old index").unwrap();
    let other = Url::from_file_path(directory.path().join("other.tex")).unwrap();
    std::fs::write(
        other.to_file_path().unwrap(),
        "\\documentclass{article}Other.",
    )
    .unwrap();
    server.notify(
        "workspace/didChangeWatchedFiles",
        json!({"changes":[{"uri":other,"type":1}]}),
    );
    let started = server.request(
        2,
        "workspace/executeCommand",
        json!({"command":"latex.build","arguments":[uri]}),
    );
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    while !output.join("ready").exists() {
        assert!(std::time::Instant::now() < deadline);
        std::thread::sleep(Duration::from_millis(10));
    }
    server.request(3, "workspace/symbol", json!({"query":"Title"}));
    server.send(json!({"jsonrpc":"2.0","id":4,"method":"workspace/executeCommand","params":{"command":"latex.build","arguments":[other]}}));
    let refused = server.until(|message| message["id"] == 4);
    assert_eq!(refused["error"]["code"], -32602, "{refused}");
    assert!(
        refused["error"]["message"]
            .as_str()
            .unwrap()
            .contains("same index output file"),
        "{refused}"
    );
    let status = server.request(
        5,
        "workspace/executeCommand",
        json!({"command":"latex.buildStatus","arguments":[uri]}),
    );
    assert_eq!(status["buildId"], started["buildId"]);
    assert_eq!(status["status"], "running");
    assert_eq!(
        server.request(
            6,
            "workspace/executeCommand",
            json!({"command":"latex.cancelBuild","arguments":[uri]})
        )["cancelled"],
        1
    );
    let finished = server.until(|message| message["method"] == "latex/buildFinished");
    assert_eq!(finished["params"]["status"], "cancelled", "{finished}");
    assert_eq!(finished["params"]["analysis"], Value::Null);
    assert_eq!(
        std::fs::read_to_string(output.join("shared.ind")).unwrap(),
        "old index"
    );
    server.request(7, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

#[test]
#[cfg(unix)]
fn index_workflow_source_edits_and_style_file_events_invalidate_inflight_results() {
    for style_event in [false, true] {
        let (mut server, directory, uri) = index_workflow_server("printf ready > ready\nwhile test ! -f release; do sleep 0.02; done\ncat \"$1\" > \"$2\"", false);
        let output = directory.path().join("build/latex-lsp");
        std::fs::create_dir_all(&output).unwrap();
        std::fs::write(output.join("main.ind"), "old index").unwrap();
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[uri]}),
        );
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while !output.join("ready").exists() {
            assert!(std::time::Instant::now() < deadline);
            std::thread::sleep(Duration::from_millis(10));
        }
        if style_event {
            let style = directory.path().join("style.ist");
            std::fs::write(&style, "changed style").unwrap();
            server.notify(
                "workspace/didChangeWatchedFiles",
                json!({"changes":[{"uri":Url::from_file_path(style).unwrap(),"type":2}]}),
            );
        } else {
            server.notify("textDocument/didChange", json!({"textDocument":{"uri":uri,"version":2},"contentChanges":[{"text":"\\documentclass{article}\\section{Edited}"}]}));
            server.request(3, "workspace/symbol", json!({"query":"Edited"}));
            std::fs::write(output.join("release"), "").unwrap();
        }
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(finished["params"]["stale"], true, "{finished}");
        assert_eq!(finished["params"]["analysis"], Value::Null);
        if style_event {
            assert_eq!(finished["params"]["status"], "cancelled");
            assert_eq!(
                std::fs::read_to_string(output.join("main.ind")).unwrap(),
                "old index"
            );
        }
        server.request(4, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[cfg(unix)]
fn bibliography_workflow_server(body: &str, backend: &str) -> (Server, tempfile::TempDir, Url) {
    let compiler = r#"set -eu
printf x >> "$1/passes"
printf '\\citation{key}\n\\bibdata{refs}\n\\bibstyle{custom}\n' > "$1/main.aux"
printf 'bcf fixture\n' > "$1/main.bcf"
printf '%%PDF-bibliography\n' > "$1/main.pdf"
printf '(./main.tex\n' > "$1/main.log"
if test ! -f "$1/main.bbl"; then
 printf 'Package biblatex Warning: Please (re)run BibTeX on the file(s): main and rerun LaTeX afterwards.\n' >> "$1/main.log"
fi
printf 'Output written on main.pdf (1 page, 18 bytes).\n)\n' >> "$1/main.log"
printf 'PWD %s\nINPUT %s\n' "$PWD" "$2" > "$1/main.fls"
"#;
    let (mut server, directory, uri) = fake_build_server(compiler, false);
    let tool = directory.path().join("bibliography-tool.sh");
    let header = r#"set -eu
root="$1"; shift
if test "$1" = --input-directory; then
  directory="$4"; job="$5"
else
  directory="$PWD"; job=${1#./}; job=${job%.aux}
fi
printf 'This is BibTeX, Version 0.99d\nThe top-level auxiliary file: ./%s.aux\nThe style file: custom.bst\nDatabase file #1: refs.bib\n' "$job" > "$directory/$job.blg"
"#;
    std::fs::write(&tool, format!("{header}\n{body}\n")).unwrap();
    std::fs::write(
        directory.path().join("refs.bib"),
        "@book{key,title={One}}\n@book{key,title={Two}}\n",
    )
    .unwrap();
    std::fs::write(directory.path().join("custom.bst"), "style").unwrap();
    let arguments = json!([directory.path().join("compiler.sh"), "%o", "%f"]);
    server.notify("workspace/didChangeConfiguration", json!({"settings":{"distribution":{"enabled":false},"build":{"executable":"/bin/sh","arguments":arguments,"rebuildArguments":arguments,"bibliographyTool":{"backend":backend,"executable":"/bin/sh","arguments":[tool,directory.path()],"dependencies":["refs.bib","custom.bst"],"timeoutSeconds":10}}}}));
    (server, directory, uri)
}

#[test]
#[cfg(unix)]
fn bibliography_workflow_over_stdio_checks_saved_dependencies_and_reports_final_artifacts() {
    for backend in ["bibtex", "biber"] {
        let (mut server, directory, uri) = bibliography_workflow_server(
            "printf 'bibliography entries\\n' > \"$directory/$job.bbl\"",
            backend,
        );
        let style = Url::from_file_path(directory.path().join("custom.bst")).unwrap();
        server.notify("textDocument/didOpen", json!({"textDocument":{"uri":style,"languageId":"plaintext","version":1,"text":"unsaved style"}}));
        server.send(json!({"jsonrpc":"2.0","id":2,"method":"workspace/executeCommand","params":{"command":"latex.build","arguments":[uri]}}));
        let rejected = server.until(|message| message["id"] == 2);
        assert_eq!(rejected["error"]["code"], -32602, "{rejected}");
        assert!(!directory.path().join("build/latex-lsp/passes").exists());
        server.notify(
            "textDocument/didClose",
            json!({"textDocument":{"uri":style}}),
        );
        server.request(
            3,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[uri]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        let result = &finished["params"];
        assert_eq!(result["status"], "success", "{result}");
        assert_eq!(result["stale"], false);
        assert_eq!(result["analysis"]["rerunRequired"], false);
        assert_eq!(
            result["analysis"]["processedBibliographyTool"]["backend"],
            backend
        );
        assert_eq!(result["analysis"]["bibliographyProcessingRounds"], 1);
        assert_eq!(
            std::fs::read(directory.path().join("build/latex-lsp/passes"))
                .unwrap()
                .len(),
            3
        );
        let status = server.request(
            4,
            "workspace/executeCommand",
            json!({"command":"latex.buildStatus","arguments":[uri]}),
        );
        assert_eq!(status, *result);
        server.request(5, "shutdown", Value::Null);
        server.notify("exit", Value::Null);
        server.wait_exit(0);
    }
}

#[test]
#[cfg(unix)]
fn bibliography_workflow_failures_publish_database_errors_and_preserve_previous_bbl() {
    let body = r#"printf 'new bibliography\n' > "$directory/$job.bbl"
if test ! -f "$root/repaired"; then
 printf 'Repeated entry---line 2 of file refs.bib\n' >> "$directory/$job.blg"
 exit 2
fi
"#;
    let (mut server, directory, uri) = bibliography_workflow_server(body, "bibtex");
    let output = directory.path().join("build/latex-lsp");
    std::fs::create_dir_all(&output).unwrap();
    std::fs::write(output.join("main.bbl"), "old bibliography").unwrap();
    let bib = Url::from_file_path(directory.path().join("refs.bib")).unwrap();
    for repaired in [false, true] {
        if repaired {
            std::fs::write(directory.path().join("repaired"), "").unwrap();
        }
        server.request(
            2,
            "workspace/executeCommand",
            json!({"command":"latex.build","arguments":[uri]}),
        );
        let finished = server.until(|message| message["method"] == "latex/buildFinished");
        assert_eq!(
            finished["params"]["status"],
            if repaired { "success" } else { "error" },
            "{finished}"
        );
        let published = server.until(|message| {
            message["method"] == "textDocument/publishDiagnostics"
                && message["params"]["uri"] == bib.as_str()
                && message["params"]["diagnostics"]
                    .as_array()
                    .is_some_and(|items| {
                        items.iter().any(|item| {
                            item["message"]
                                .as_str()
                                .is_some_and(|text| text.contains("Repeated entry"))
                        }) != repaired
                    })
        });
        if !repaired {
            let diagnostic = published["params"]["diagnostics"]
                .as_array()
                .unwrap()
                .iter()
                .find(|item| {
                    item["message"]
                        .as_str()
                        .is_some_and(|text| text.contains("Repeated entry"))
                })
                .unwrap();
            assert_eq!(diagnostic["range"]["start"]["line"], 1);
            assert_eq!(
                std::fs::read_to_string(output.join("main.bbl")).unwrap(),
                "old bibliography"
            );
            assert!(finished["params"]["pdfUri"].is_null());
        } else {
            assert_eq!(
                std::fs::read_to_string(output.join("main.bbl")).unwrap(),
                "new bibliography\n"
            );
        }
    }
    server.request(3, "shutdown", Value::Null);
    server.notify("exit", Value::Null);
    server.wait_exit(0);
}

